INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C1','math',3,1,'u3',2,'똑같이 나누기의 뜻 — 여러 개를 나눌 때 묶음마다 개수가 같아야 공평하게(똑같이) 나눈 것임을 알고, 생활 속 똑같이 나누는 상황 찾기',ARRAY['4수01-05']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C2','math',3,1,'u3',2,'묶음 수로 똑같이 나누기 — 전체를 사람(접시) 수만큼 하나씩 번갈아 놓아 똑같이 나누고, 한 묶음(한 사람)에 몇 개씩인지 구하기',ARRAY['4수01-05']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C3','math',3,1,'u3',3,'몇씩 묶어 덜어 내기 — 전체에서 한 묶음 개수씩 똑같이 덜어 내어 몇 묶음이 되는지 구하고, 같은 수를 0이 될 때까지 되풀이해 빼는 것과 이어 보기',ARRAY['4수01-05']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C4','math',3,1,'u3',4,'나눗셈식과 몫 — 똑같이 나누는 상황을 「나누어지는 수 ÷ 나누는 수 = 몫」으로 쓰고 「나누기」로 읽으며, 앞뒤 순서를 바꾸면 다른 식임을 알기',ARRAY['4수01-05']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C5','math',3,1,'u3',5,'곱셈과 나눗셈의 관계 — 한 배열을 곱셈식 2개와 나눗셈식 2개로 읽고, 곱셈식을 나눗셈식으로·나눗셈식을 곱셈식으로 바꾸기(같은 세 수의 식 가족)',ARRAY['4수01-05']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C6','math',3,1,'u3',6,'곱셈구구로 몫 구하기 — 나눗셈을 「나누는 수 × □ = 나누어지는 수」로 바꾸어 곱셈구구에서 □(몫)를 찾고, 나누는 수 × 몫이 나누어지는 수가 되는지 곱셈으로 확인하기',ARRAY['4수01-06']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C7','math',3,1,'u3',7,'상황에 맞는 나눗셈식 세우기 — 문제 상황이 몇 개씩을 묻는지 몇 묶음을 묻는지 읽어 나누어지는 수와 나누는 수를 정하고, 나눗셈식을 세워 몫을 구해 답하기',ARRAY['4수01-06']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M3-1-u3-C8','math',3,1,'u3',7,'여러 방법으로 똑같이 나누기 — 한 수를 남김없이 똑같이 나누는 여러 방법을 곱셈구구로 찾고, 남김없이 나눌 수 없는 경우를 가려내기',ARRAY['4수01-06']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X01','math',3,'u3',ARRAY['M3-1-u3-C1','M3-1-u3-C2']::text[],'묶음마다 개수가 달라도 다 나누어 주었으면 똑같이(공평하게) 나눈 것이라고 여긴다','묶음마다 개수가 같은지 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X02','math',3,'u3',ARRAY['M3-1-u3-C2','M3-1-u3-C3','M3-1-u3-C7']::text[],'묻는 것을 헷갈려 주어진 수(사람 수·한 묶음 개수)를 그대로 답한다','무엇을 묻는지 밑줄 — 몇 개씩? 몇 묶음?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X03','math',3,'u3',ARRAY['M3-1-u3-C3','M3-1-u3-C7']::text[],'몇 묶음으로 나누는 것과 몇 개씩 묶는 것을 같은 상황으로 여긴다','같은 12라도 묻는 것이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X04','math',3,'u3',ARRAY['M3-1-u3-C3']::text[],'되풀이해 뺄 때 뺀 횟수를 하나 더 세거나 덜 센다','0이 될 때까지 뺀 횟수에 표시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X05','math',3,'u3',ARRAY['M3-1-u3-C4','M3-1-u3-C5']::text[],'나눗셈식의 앞뒤 순서를 바꾸어 쓴다(12 ÷ 4 대신 4 ÷ 12)','앞에는 나누어지는 수(전체)') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X06','math',3,'u3',ARRAY['M3-1-u3-C4']::text[],'몫이 무엇인지 헷갈려 나누어지는 수나 나누는 수를 몫이라고 한다','= 뒤의 결과가 몫') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X07','math',3,'u3',ARRAY['M3-1-u3-C4','M3-1-u3-C6']::text[],'÷를 ×나 −로 읽거나 계산한다(12 ÷ 3을 9나 36으로)','÷는 나누기 — 똑같이 나누기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X08','math',3,'u3',ARRAY['M3-1-u3-C5']::text[],'곱셈식과 나눗셈식을 바꿀 때 세 수가 아닌 다른 수를 넣거나 자리를 잘못 놓는다','세 수가 그대로인지 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X09','math',3,'u3',ARRAY['M3-1-u3-C5']::text[],'배열을 식으로 읽을 때 한 줄의 개수나 줄 수를 잘못 센다','가로 한 줄·세로 한 줄을 따로 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X10','math',3,'u3',ARRAY['M3-1-u3-C6']::text[],'몫을 찾을 때 곱셈구구의 단을 잘못 골라 나누어지는 수를 곱한다(12 × □ = 3)','나누는 수의 단에서 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X11','math',3,'u3',ARRAY['M3-1-u3-C4','M3-1-u3-C5','M3-1-u3-C6','M3-1-u3-C7','M3-1-u3-C8']::text[],'곱셈구구를 잘못 떠올려 몫이 하나 크거나 작다','나누는 수 × 몫으로 다시 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X12','math',3,'u3',ARRAY['M3-1-u3-C6']::text[],'몫을 확인할 때 몫과 나누어지는 수를 곱한다(4 × 12)','나누는 수 × 몫 = 나누어지는 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X13','math',3,'u3',ARRAY['M3-1-u3-C7']::text[],'똑같이 나누는 상황에서 곱셈·덧셈·뺄셈을 고른다','「똑같이 나누어」·「몇씩 담으면」은 나눗셈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M3-1-u3-X15','math',3,'u3',ARRAY['M3-1-u3-C1','M3-1-u3-C2','M3-1-u3-C3','M3-1-u3-C4','M3-1-u3-C5','M3-1-u3-C6','M3-1-u3-C7','M3-1-u3-C8']::text[],'묻는 말을 거꾸로 읽는다 — 틀린↔바른, 아닌↔맞는','물음의 「틀린·아닌」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#1','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C2',1,'mc','auto','사탕 12개를 봉지 3개에 똑같이 나누었어요. 한 봉지에 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":1,"concept":"M3-1-u3-C2","difficulty":1,"kind":"mc","stem":"사탕 12개를 봉지 3개에 똑같이 나누었어요. 한 봉지에 몇 개씩인가요?","options":[{"t":"4개","correct":true},{"t":"3개","mis":"M3-1-u3-X02"},{"t":"9개","mis":"M3-1-u3-X07"},{"t":"5개","mis":"M3-1-u3-X11"}],"explanation":["사탕 12개를 봉지 3개에 하나씩 번갈아 놓았어요.","묶음마다 4개씩 똑같이 있어요.","그래서 한 봉지에 4개예요."],"asset":{"type":"mul_groups","item":"🍬","k":4,"n":3},"variant_rule":{"alt":[{"stem":"쿠키 45개를 상자 9개에 똑같이 나누었어요. 한 상자에 몇 개씩인가요?","options":[{"t":"5개","correct":true},{"t":"9개","mis":"M3-1-u3-X02"},{"t":"36개","mis":"M3-1-u3-X07"},{"t":"6개","mis":"M3-1-u3-X11"}],"explanation":["쿠키 45개를 상자 9개에 하나씩 번갈아 놓았어요.","묶음마다 5개씩 똑같이 있어요.","그래서 한 상자에 5개예요."],"asset":{"type":"mul_groups","item":"🍪","k":5,"n":9}},{"stem":"딸기 10개를 바구니 2개에 똑같이 나누었어요. 한 바구니에 몇 개씩인가요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M3-1-u3-X02"},{"t":"8개","mis":"M3-1-u3-X07"},{"t":"6개","mis":"M3-1-u3-X11"}],"explanation":["딸기 10개를 바구니 2개에 하나씩 번갈아 놓았어요.","묶음마다 5개씩 똑같이 있어요.","그래서 한 바구니에 5개예요."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":2}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#2','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C1',1,'mc','auto','쿠키 12개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":2,"concept":"M3-1-u3-C1","difficulty":1,"kind":"mc","stem":"쿠키 12개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"3명에게 4개씩","correct":true},{"t":"3명에게 1·6·5개","mis":"M3-1-u3-X01"},{"t":"4명에게 4·4·1·3개","mis":"M3-1-u3-X01"},{"t":"2명에게 7·5개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","3명이 모두 4개씩 받으면 3 × 4 = 12개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"variant_rule":{"alt":[{"stem":"딸기 14개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"2명에게 7개씩","correct":true},{"t":"2명에게 6·8개","mis":"M3-1-u3-X01"},{"t":"3명에게 6·5·3개","mis":"M3-1-u3-X01"},{"t":"4명에게 5·2·5·2개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","2명이 모두 7개씩 받으면 2 × 7 = 14개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null},{"stem":"풍선 8개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"4명에게 2개씩","correct":true},{"t":"4명에게 1·1·1·5개","mis":"M3-1-u3-X01"},{"t":"5명에게 3·2·2·2·1개","mis":"M3-1-u3-X01"},{"t":"3명에게 2·4·2개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","4명이 모두 2개씩 받으면 4 × 2 = 8개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#3','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C2',1,'sa','auto','카드 10장을 모둠 2개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C2","difficulty":1,"kind":"sa","stem":"카드 10장을 모둠 2개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["10장을 모둠 2개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","2묶음으로 똑같이 나누니 2 × □ = 10에서 □ = 5예요.","한 모둠에 5장이에요."],"variant_rule":{"alt":[{"stem":"지우개 24개를 봉지 4개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["24개를 봉지 4개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","4묶음으로 똑같이 나누니 4 × □ = 24에서 □ = 6이에요.","한 봉지에 6개예요."],"asset":null},{"stem":"클립 27개를 상자 3개에 똑같이 나누어 담으면 한 상자에 몇 개씩인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["27개를 상자 3개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","3묶음으로 똑같이 나누니 3 × □ = 27에서 □ = 9예요.","한 상자에 9개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#4','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C1',1,'mc','auto','똑같이 나눈다는 것은 어떤 뜻인가요?',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":4,"concept":"M3-1-u3-C1","difficulty":1,"kind":"mc","stem":"똑같이 나눈다는 것은 어떤 뜻인가요?","options":[{"t":"묶음마다 개수가 같다","correct":true},{"t":"묶음마다 개수가 다르다","mis":"M3-1-u3-X01"},{"t":"한 묶음만 많다","mis":"M3-1-u3-X01"},{"t":"아무렇게나 나눈다","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","그래야 모두 공평해요.","들쭉날쭉하면 똑같이 나눈 것이 아니에요."],"variant_rule":{"alt":[{"stem":"친구들에게 간식을 공평하게 나누려면 어떻게 해야 하나요?","options":[{"t":"모두 같은 개수로 나눈다","correct":true},{"t":"내가 더 많이 가진다","mis":"M3-1-u3-X01"},{"t":"친구마다 다르게 준다","mis":"M3-1-u3-X01"},{"t":"한 명에게만 준다","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","그래야 모두 공평해요.","들쭉날쭉하면 똑같이 나눈 것이 아니에요."],"asset":null},{"stem":"접시 4개에 쿠키를 똑같이 나누었어요. 접시에 놓인 쿠키 수는 어떤가요?","options":[{"t":"네 접시 모두 같다","correct":true},{"t":"네 접시 모두 다르다","mis":"M3-1-u3-X01"},{"t":"한 접시만 많다","mis":"M3-1-u3-X01"},{"t":"마음대로다","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","그래야 모두 공평해요.","들쭉날쭉하면 똑같이 나눈 것이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#5','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C2',2,'mc','auto','지우개 12개를 접시 4개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":5,"concept":"M3-1-u3-C2","difficulty":2,"kind":"mc","stem":"지우개 12개를 접시 4개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요?","options":[{"t":"3개","correct":true},{"t":"4개","mis":"M3-1-u3-X02"},{"t":"8개","mis":"M3-1-u3-X07"},{"t":"2개","mis":"M3-1-u3-X11"}],"explanation":["12개를 접시 4개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","4묶음으로 똑같이 나누니 4 × □ = 12에서 □ = 3이에요.","한 접시에 3개예요."],"variant_rule":{"alt":[{"stem":"클립 16개를 모둠 8개에 똑같이 나누어 주면 한 모둠에 몇 개씩인가요?","options":[{"t":"2개","correct":true},{"t":"8개","mis":"M3-1-u3-X02"},{"t":"3개","mis":"M3-1-u3-X11"},{"t":"1개","mis":"M3-1-u3-X11"}],"explanation":["16개를 모둠 8개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","8묶음으로 똑같이 나누니 8 × □ = 16에서 □ = 2예요.","한 모둠에 2개예요."],"asset":null},{"stem":"귤 6개를 봉지 3개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요?","options":[{"t":"2개","correct":true},{"t":"3개","mis":"M3-1-u3-X02"},{"t":"1개","mis":"M3-1-u3-X11"},{"t":"6개","mis":"M3-1-u3-X06"}],"explanation":["6개를 봉지 3개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","3묶음으로 똑같이 나누니 3 × □ = 6에서 □ = 2예요.","한 봉지에 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#6','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C1',2,'ox','auto','클립 12개를 4명에게 차례로 2·3·3·4개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":6,"concept":"M3-1-u3-C1","difficulty":2,"kind":"ox","stem":"클립 12개를 4명에게 차례로 2·3·3·4개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"mis":"M3-1-u3-X01","explanation":["모두 더하면 12개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 2·3·3·4개로 달라요.","똑같이 나누려면 4명 모두 3개씩 받아야 해요."],"variant_rule":{"alt":[{"stem":"귤 48개를 8명에게 차례로 6·6·5·6·6·6·7·6개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 48개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 6·6·5·6·6·6·7·6개로 달라요.","똑같이 나누려면 8명 모두 6개씩 받아야 해요."],"asset":null},{"stem":"공책 42권을 6명에게 차례로 6·7·7·7·7·8권을 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 42권 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 6·7·7·7·7·8권으로 달라요.","똑같이 나누려면 6명 모두 7권씩 받아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#7','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C2',2,'sa','auto','색종이 15장을 3명에게 한 장씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 색종이 몇 장씩 놓였나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u3-C2","difficulty":2,"kind":"sa","stem":"색종이 15장을 3명에게 한 장씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 색종이 몇 장씩 놓였나요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 바퀴 돌 때마다 3장씩 놓여요.","15장을 다 놓으려면 5바퀴를 돌아요 — 3 × 5 = 15.","그래서 한 사람 앞에 5장씩 놓였어요."],"variant_rule":{"alt":[{"stem":"구슬 24개를 6명에게 한 개씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 구슬 몇 개씩 놓였나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 바퀴 돌 때마다 6개씩 놓여요.","24개를 다 놓으려면 4바퀴를 돌아요 — 6 × 4 = 24.","그래서 한 사람 앞에 4개씩 놓였어요."],"asset":null},{"stem":"카드 21장을 7명에게 한 장씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 카드 몇 장씩 놓였나요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 바퀴 돌 때마다 7장씩 놓여요.","21장을 다 놓으려면 3바퀴를 돌아요 — 7 × 3 = 21.","그래서 한 사람 앞에 3장씩 놓였어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#8','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C2',2,'match','auto','공책을 똑같이 나누었어요. 한 명이 받는 수와 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C2","difficulty":2,"kind":"match","stem":"공책을 똑같이 나누었어요. 한 명이 받는 수와 알맞게 이으세요.","pairs":[{"l":"12권 → 3명","r":"4권씩"},{"l":"9권 → 3명","r":"3권씩"},{"l":"48권 → 8명","r":"6권씩"}],"mis":"M3-1-u3-X02","explanation":["전체를 사람 수만큼 똑같이 나누어요.","사람 수 × □ = 전체가 되는 □가 한 명이 받는 수예요.","3명이면 4권씩, 3명이면 3권씩, 8명이면 6권씩."],"variant_rule":{"alt":[{"stem":"연필을 똑같이 나누었어요. 한 명이 받는 수와 알맞게 이으세요.","pairs":[{"l":"16자루 → 8명","r":"2자루씩"},{"l":"45자루 → 5명","r":"9자루씩"},{"l":"35자루 → 5명","r":"7자루씩"}],"explanation":["전체를 사람 수만큼 똑같이 나누어요.","사람 수 × □ = 전체가 되는 □가 한 명이 받는 수예요.","8명이면 2자루씩, 5명이면 9자루씩, 5명이면 7자루씩."],"asset":null},{"stem":"색종이를 똑같이 나누었어요. 한 명이 받는 수와 알맞게 이으세요.","pairs":[{"l":"10장 → 2명","r":"5장씩"},{"l":"56장 → 8명","r":"7장씩"},{"l":"72장 → 9명","r":"8장씩"}],"explanation":["전체를 사람 수만큼 똑같이 나누어요.","사람 수 × □ = 전체가 되는 □가 한 명이 받는 수예요.","2명이면 5장씩, 8명이면 7장씩, 9명이면 8장씩."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#9','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C1',2,'ox','auto','나눔 장터에서 사탕을 친구들에게 똑같이 나누어 주면 모두 같은 개수를 받아 공평해요.',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":9,"concept":"M3-1-u3-C1","difficulty":2,"kind":"ox","stem":"나눔 장터에서 사탕을 친구들에게 똑같이 나누어 주면 모두 같은 개수를 받아 공평해요.","answer":"O","reason_options":[{"t":"묶음마다 개수가 같으면 공평해서","correct":true},{"t":"나누어 주면 내 것이 줄어 손해라서","mis":"M3-1-u3-X01"}],"mis":"M3-1-u3-X01","explanation":["똑같이 나누면 묶음마다 개수가 같아요.","개수가 같아야 공평해요.","나누면 함께 즐거워요 — 손해가 아니에요."],"variant_rule":{"alt":[{"stem":"한 명에게만 공책을 많이 주는 것도 공평한 나눔이에요.","answer":"X","reason_options":[{"t":"한 명만 많으면 받은 수가 달라서","correct":true},{"t":"어쨌든 공책을 다 나누어 주었으니까","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","개수가 같아야 공평해요.","나누면 함께 즐거워요 — 손해가 아니에요."],"asset":null},{"stem":"똑같이 나누면 접시마다 놓인 개수가 모두 같아요.","answer":"O","reason_options":[{"t":"똑같이 = 묶음마다 같은 개수라서","correct":true},{"t":"접시가 다르면 개수도 달라야 해서","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","개수가 같아야 공평해요.","나누면 함께 즐거워요 — 손해가 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_basic#10','math',3,1,'u3','L02','g3_1_math_u3_L02_basic','lesson_basic','M3-1-u3-C2',3,'mc','auto','연필 24자루를 봉지 6개에 똑같이 나누어 담으면 한 봉지에 몇 자루씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":10,"concept":"M3-1-u3-C2","difficulty":3,"kind":"mc","stem":"연필 24자루를 봉지 6개에 똑같이 나누어 담으면 한 봉지에 몇 자루씩인가요?","options":[{"t":"4자루","correct":true},{"t":"6자루","mis":"M3-1-u3-X02"},{"t":"18자루","mis":"M3-1-u3-X07"},{"t":"5자루","mis":"M3-1-u3-X11"}],"explanation":["24자루를 봉지 6개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","6묶음으로 똑같이 나누니 6 × □ = 24에서 □ = 4예요.","한 봉지에 4자루예요."],"variant_rule":{"alt":[{"stem":"색종이 15장을 상자 5개에 똑같이 나누어 담으면 한 상자에 몇 장씩인가요?","options":[{"t":"3장","correct":true},{"t":"5장","mis":"M3-1-u3-X02"},{"t":"10장","mis":"M3-1-u3-X07"},{"t":"4장","mis":"M3-1-u3-X11"}],"explanation":["15장을 상자 5개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","5묶음으로 똑같이 나누니 5 × □ = 15에서 □ = 3이에요.","한 상자에 3장이에요."],"asset":null},{"stem":"구슬 54개를 바구니 9개에 똑같이 나누어 담으면 한 바구니에 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"9개","mis":"M3-1-u3-X02"},{"t":"45개","mis":"M3-1-u3-X07"},{"t":"7개","mis":"M3-1-u3-X11"}],"explanation":["54개를 바구니 9개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","9묶음으로 똑같이 나누니 9 × □ = 54에서 □ = 6이에요.","한 바구니에 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#1','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C2',2,'mc','auto','당근 20개를 접시 4개에 똑같이 나누었어요. 한 접시에 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":1,"concept":"M3-1-u3-C2","difficulty":2,"kind":"mc","stem":"당근 20개를 접시 4개에 똑같이 나누었어요. 한 접시에 몇 개씩인가요?","options":[{"t":"5개","correct":true},{"t":"4개","mis":"M3-1-u3-X02"},{"t":"16개","mis":"M3-1-u3-X07"},{"t":"6개","mis":"M3-1-u3-X11"}],"explanation":["당근 20개를 접시 4개에 하나씩 번갈아 놓았어요.","묶음마다 5개씩 똑같이 있어요.","그래서 한 접시에 5개예요."],"asset":{"type":"mul_groups","item":"🥕","k":5,"n":4},"variant_rule":{"alt":[{"stem":"물고기 6마리를 모둠 3개에 똑같이 나누었어요. 한 모둠에 몇 마리씩인가요?","options":[{"t":"2마리","correct":true},{"t":"3마리","mis":"M3-1-u3-X02"},{"t":"1마리","mis":"M3-1-u3-X11"},{"t":"6마리","mis":"M3-1-u3-X06"}],"explanation":["물고기 6마리를 모둠 3개에 하나씩 번갈아 놓았어요.","묶음마다 2마리씩 똑같이 있어요.","그래서 한 모둠에 2마리예요."],"asset":{"type":"mul_groups","item":"🐟","k":2,"n":3}},{"stem":"사탕 28개를 봉지 4개에 똑같이 나누었어요. 한 봉지에 몇 개씩인가요?","options":[{"t":"7개","correct":true},{"t":"4개","mis":"M3-1-u3-X02"},{"t":"24개","mis":"M3-1-u3-X07"},{"t":"8개","mis":"M3-1-u3-X11"}],"explanation":["사탕 28개를 봉지 4개에 하나씩 번갈아 놓았어요.","묶음마다 7개씩 똑같이 있어요.","그래서 한 봉지에 7개예요."],"asset":{"type":"mul_groups","item":"🍬","k":7,"n":4}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#2','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C2',2,'sa','auto','구슬 20개를 접시 5개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C2","difficulty":2,"kind":"sa","stem":"구슬 20개를 접시 5개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20개를 접시 5개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","5묶음으로 똑같이 나누니 5 × □ = 20에서 □ = 4예요.","한 접시에 4개예요."],"variant_rule":{"alt":[{"stem":"카드 12장을 모둠 6개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["12장을 모둠 6개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","6묶음으로 똑같이 나누니 6 × □ = 12에서 □ = 2예요.","한 모둠에 2장이에요."],"asset":null},{"stem":"지우개 36개를 봉지 9개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["36개를 봉지 9개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","9묶음으로 똑같이 나누니 9 × □ = 36에서 □ = 4예요.","한 봉지에 4개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#3','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C2',3,'error','auto','클립 20개를 4명에게 똑같이 나누었어요. 이를 보고 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X15']::text[],true,'{"seq":3,"concept":"M3-1-u3-C2","difficulty":3,"kind":"error","stem":"클립 20개를 4명에게 똑같이 나누었어요. 이를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「한 명에게 4개씩이야.」","correct":true,"mis_target":"M3-1-u3-X02"},{"t":"시우 — 「한 명에게 5개씩이야.」","mis":"M3-1-u3-X15"},{"t":"은우 — 「4명이 받은 수가 모두 같아.」","mis":"M3-1-u3-X15"}],"explanation":["4명에게 하나씩 번갈아 놓으면 한 명에게 5개씩이에요.","4명 모두 5개씩이라 받은 수가 같아요.","태오는 사람 수 4를 한 명이 받는 수로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"귤 72개를 9명에게 똑같이 나누었어요. 이를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「한 명에게 9개씩이야.」","correct":true,"mis_target":"M3-1-u3-X02"},{"t":"태오 — 「한 명에게 8개씩이야.」","mis":"M3-1-u3-X15"},{"t":"은우 — 「9명이 받은 수가 모두 같아.」","mis":"M3-1-u3-X15"}],"explanation":["9명에게 하나씩 번갈아 놓으면 한 명에게 8개씩이에요.","9명 모두 8개씩이라 받은 수가 같아요.","시우는 사람 수 9를 한 명이 받는 수로 잘못 말했어요."],"asset":null},{"stem":"공책 28권을 7명에게 똑같이 나누었어요. 이를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「한 명에게 7권씩이야.」","correct":true,"mis_target":"M3-1-u3-X02"},{"t":"은우 — 「한 명에게 4권씩이야.」","mis":"M3-1-u3-X15"},{"t":"지유 — 「7명이 받은 수가 모두 같아.」","mis":"M3-1-u3-X15"}],"explanation":["7명에게 하나씩 번갈아 놓으면 한 명에게 4권씩이에요.","7명 모두 4권씩이라 받은 수가 같아요.","도윤은 사람 수 7을 한 명이 받는 수로 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#4','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C1',3,'mc','auto','쿠키 15개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":4,"concept":"M3-1-u3-C1","difficulty":3,"kind":"mc","stem":"쿠키 15개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"5명에게 3개씩","correct":true},{"t":"5명에게 5·2·1·2·5개","mis":"M3-1-u3-X01"},{"t":"6명에게 1·2·3·7·1·1개","mis":"M3-1-u3-X01"},{"t":"4명에게 1·3·8·3개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","5명이 모두 3개씩 받으면 5 × 3 = 15개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"variant_rule":{"alt":[{"stem":"딸기 16개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"2명에게 8개씩","correct":true},{"t":"2명에게 9·7개","mis":"M3-1-u3-X01"},{"t":"3명에게 6·7·3개","mis":"M3-1-u3-X01"},{"t":"4명에게 4·2·6·4개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","2명이 모두 8개씩 받으면 2 × 8 = 16개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null},{"stem":"풍선 27개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"3명에게 9개씩","correct":true},{"t":"3명에게 10·9·8개","mis":"M3-1-u3-X01"},{"t":"4명에게 8·7·6·6개","mis":"M3-1-u3-X01"},{"t":"2명에게 10·8개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","3명이 모두 9개씩 받으면 3 × 9 = 27개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#5','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C1',3,'mc','auto','색종이 9장을 3묶음에 1·2·6장 들쭉날쭉 담았어요. 똑같이 다시 나누면 한 묶음에 몇 장씩인가요?',ARRAY['M3-1-u3-X01','M3-1-u3-X11']::text[],true,'{"seq":5,"concept":"M3-1-u3-C1","difficulty":3,"kind":"mc","stem":"색종이 9장을 3묶음에 1·2·6장 들쭉날쭉 담았어요. 똑같이 다시 나누면 한 묶음에 몇 장씩인가요?","options":[{"t":"3장","correct":true},{"t":"6장","mis":"M3-1-u3-X01"},{"t":"1장","mis":"M3-1-u3-X01"},{"t":"4장","mis":"M3-1-u3-X11"}],"explanation":["모두 1 + 2 + 6 = 9장.","9를 3묶음으로 똑같이 나눠요 — 9 ÷ 3.","3 × 3 = 9 — 한 묶음에 3장씩이에요."],"variant_rule":{"alt":[{"stem":"구슬 16개를 4묶음에 6·3·5·2개 들쭉날쭉 담았어요. 똑같이 다시 나누면 한 묶음에 몇 개씩인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M3-1-u3-X01"},{"t":"2개","mis":"M3-1-u3-X01"},{"t":"5개","mis":"M3-1-u3-X11"}],"explanation":["모두 6 + 3 + 5 + 2 = 16개.","16을 4묶음으로 똑같이 나눠요 — 16 ÷ 4.","4 × 4 = 16 — 한 묶음에 4개씩이에요."],"asset":null},{"stem":"카드 48장을 6묶음에 7·6·7·9·7·12장 들쭉날쭉 담았어요. 똑같이 다시 나누면 한 묶음에 몇 장씩인가요?","options":[{"t":"8장","correct":true},{"t":"12장","mis":"M3-1-u3-X01"},{"t":"6장","mis":"M3-1-u3-X02"},{"t":"9장","mis":"M3-1-u3-X11"}],"explanation":["모두 7 + 6 + 7 + 9 + 7 + 12 = 48장.","48을 6묶음으로 똑같이 나눠요 — 48 ÷ 6.","6 × 8 = 48 — 한 묶음에 8장씩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#6','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C2',3,'mc','auto','귤 42개를 봉지 7개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":6,"concept":"M3-1-u3-C2","difficulty":3,"kind":"mc","stem":"귤 42개를 봉지 7개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"7개","mis":"M3-1-u3-X02"},{"t":"35개","mis":"M3-1-u3-X07"},{"t":"5개","mis":"M3-1-u3-X11"}],"explanation":["42개를 봉지 7개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","7묶음으로 똑같이 나누니 7 × □ = 42에서 □ = 6이에요.","한 봉지에 6개예요."],"variant_rule":{"alt":[{"stem":"공책 48권을 상자 8개에 똑같이 나누어 담으면 한 상자에 몇 권씩인가요?","options":[{"t":"6권","correct":true},{"t":"8권","mis":"M3-1-u3-X02"},{"t":"40권","mis":"M3-1-u3-X07"},{"t":"7권","mis":"M3-1-u3-X11"}],"explanation":["48권을 상자 8개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","8묶음으로 똑같이 나누니 8 × □ = 48에서 □ = 6이에요.","한 상자에 6권이에요."],"asset":null},{"stem":"연필 15자루를 바구니 5개에 똑같이 나누어 담으면 한 바구니에 몇 자루씩인가요?","options":[{"t":"3자루","correct":true},{"t":"5자루","mis":"M3-1-u3-X02"},{"t":"10자루","mis":"M3-1-u3-X07"},{"t":"4자루","mis":"M3-1-u3-X11"}],"explanation":["15자루를 바구니 5개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","5묶음으로 똑같이 나누니 5 × □ = 15에서 □ = 3이에요.","한 바구니에 3자루예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#7','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C2',3,'sa','auto','구슬 42개를 6명에게 한 개씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 구슬 몇 개씩 놓였나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u3-C2","difficulty":3,"kind":"sa","stem":"구슬 42개를 6명에게 한 개씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 구슬 몇 개씩 놓였나요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 바퀴 돌 때마다 6개씩 놓여요.","42개를 다 놓으려면 7바퀴를 돌아요 — 6 × 7 = 42.","그래서 한 사람 앞에 7개씩 놓였어요."],"variant_rule":{"alt":[{"stem":"카드 28장을 4명에게 한 장씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 카드 몇 장씩 놓였나요? 숫자로 쓰세요.","answer":["7"],"explanation":["한 바퀴 돌 때마다 4장씩 놓여요.","28장을 다 놓으려면 7바퀴를 돌아요 — 4 × 7 = 28.","그래서 한 사람 앞에 7장씩 놓였어요."],"asset":null},{"stem":"지우개 54개를 6명에게 한 개씩 번갈아 놓았더니 남김없이 똑같이 나누어졌어요. 한 사람 앞에 지우개 몇 개씩 놓였나요? 숫자로 쓰세요.","answer":["9"],"explanation":["한 바퀴 돌 때마다 6개씩 놓여요.","54개를 다 놓으려면 9바퀴를 돌아요 — 6 × 9 = 54.","그래서 한 사람 앞에 9개씩 놓였어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#8','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C2',4,'essay','teacher','나눔 장터에서 사탕 12개를 친구 3명에게 똑같이 나누어 주려고 해요. 하나씩 번갈아 놓는 방법으로 어떻게 나누는지 설명하고, 한 명이 몇 개씩 받는지 구해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u3-C2","difficulty":4,"kind":"essay","stem":"나눔 장터에서 사탕 12개를 친구 3명에게 똑같이 나누어 주려고 해요. 하나씩 번갈아 놓는 방법으로 어떻게 나누는지 설명하고, 한 명이 몇 개씩 받는지 구해 보세요.","answer_guide":{"answer":"예: 사탕을 세 친구 앞에 하나씩 차례로 번갈아 놓는다. 한 바퀴 돌 때마다 3개가 놓이고, 4바퀴를 돌면 12개를 모두 놓는다. 그래서 한 명이 4개씩 받는다(3 × 4 = 12).","scoring_points":["하나씩 번갈아 놓는다고 썼는가","4바퀴(3 × 4 = 12)를 밝혔는가","한 명에게 4개씩을 구했는가"]},"explanation":["세 친구에게 하나씩 차례로 놓아요.","한 바퀴에 3개 — 4바퀴면 12개.","한 명이 4개씩 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#9','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C1',4,'essay','teacher','지유는 구슬 15개를 친구 3명에게 4개, 5개, 6개 나누어 주고 「다 나누어 주었으니 똑같이 나눈 거야.」라고 말했어요. 지유의 말이 맞는지 판단하고, 똑같이 나누려면 어떻게 해야 하는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u3-C1","difficulty":4,"kind":"essay","stem":"지유는 구슬 15개를 친구 3명에게 4개, 5개, 6개 나누어 주고 「다 나누어 주었으니 똑같이 나눈 거야.」라고 말했어요. 지유의 말이 맞는지 판단하고, 똑같이 나누려면 어떻게 해야 하는지 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 4개, 5개, 6개는 받은 수가 서로 달라 공평하지 않다. 똑같이 나누려면 15개를 3명에게 하나씩 번갈아 놓아 한 명에게 5개씩 주어야 한다(3 × 5 = 15).","scoring_points":["맞지 않다고 판단했는가","받은 수가 달라서라고 까닭을 썼는가","한 명에게 5개씩 주면 된다고 썼는가"]},"explanation":["4·5·6개는 받은 수가 달라요.","똑같이 = 모두 같은 개수.","15 ÷ 3 — 한 명에게 5개씩이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L02_challenge#10','math',3,1,'u3','L02','g3_1_math_u3_L02_challenge','lesson_challenge','M3-1-u3-C2',4,'sa','auto','당근이 접시 4개에 5개씩 똑같이 놓여 있어요. 당근 4개를 더 가져와 다시 똑같이 나누면 한 접시에 몇 개씩인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u3-C2","difficulty":4,"kind":"sa","stem":"당근이 접시 4개에 5개씩 똑같이 놓여 있어요. 당근 4개를 더 가져와 다시 똑같이 나누면 한 접시에 몇 개씩인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["처음 당근은 4 × 5 = 20개.","4개 더하면 20 + 4 = 24개.","24 ÷ 4 = 6 — 한 접시에 6개씩이에요."],"variant_rule":{"alt":[{"stem":"물고기가 접시 2개에 3마리씩 똑같이 놓여 있어요. 물고기 2마리를 더 가져와 다시 똑같이 나누면 한 접시에 몇 마리씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["처음 물고기는 2 × 3 = 6마리.","2마리 더하면 6 + 2 = 8마리.","8 ÷ 2 = 4 — 한 접시에 4마리씩이에요."],"asset":null},{"stem":"사탕이 접시 6개에 4개씩 똑같이 놓여 있어요. 사탕 6개를 더 가져와 다시 똑같이 나누면 한 접시에 몇 개씩인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["처음 사탕은 6 × 4 = 24개.","6개 더하면 24 + 6 = 30개.","30 ÷ 6 = 5 — 한 접시에 5개씩이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#1','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',1,'mc','auto','풍선 12개를 3개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":1,"concept":"M3-1-u3-C3","difficulty":1,"kind":"mc","stem":"풍선 12개를 3개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"4묶음","correct":true},{"t":"3묶음","mis":"M3-1-u3-X02"},{"t":"9묶음","mis":"M3-1-u3-X07"},{"t":"5묶음","mis":"M3-1-u3-X11"}],"explanation":["3개씩 묶은 테두리를 세어요.","3씩 4번 덜어 내면 12개 모두 덜어 내져요 — 3 × 4 = 12.","그래서 4묶음이에요."],"asset":{"type":"mul_groups","item":"🎈","k":3,"n":4},"variant_rule":{"alt":[{"stem":"별 스티커 16장을 2장씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"8묶음","correct":true},{"t":"2묶음","mis":"M3-1-u3-X02"},{"t":"14묶음","mis":"M3-1-u3-X07"},{"t":"9묶음","mis":"M3-1-u3-X11"}],"explanation":["2장씩 묶은 테두리를 세어요.","2씩 8번 덜어 내면 16장 모두 덜어 내져요 — 2 × 8 = 16.","그래서 8묶음이에요."],"asset":{"type":"mul_groups","item":"⭐","k":2,"n":8}},{"stem":"컵케이크 6개를 2개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"3묶음","correct":true},{"t":"2묶음","mis":"M3-1-u3-X02"},{"t":"4묶음","mis":"M3-1-u3-X07"},{"t":"6묶음","mis":"M3-1-u3-X06"}],"explanation":["2개씩 묶은 테두리를 세어요.","2씩 3번 덜어 내면 6개 모두 덜어 내져요 — 2 × 3 = 6.","그래서 3묶음이에요."],"asset":{"type":"mul_groups","item":"🧁","k":2,"n":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#2','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',1,'sa','auto','12 − 3 − 3 − 3 − 3 = 0에서 3을 몇 번 뺐나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C3","difficulty":1,"kind":"sa","stem":"12 − 3 − 3 − 3 − 3 = 0에서 3을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["4"],"explanation":["빼는 수 3이 몇 개인지 세어요.","12 − 3을 4번 하면 0이 돼요.","12는 3씩 4묶음으로 덜어 낼 수 있어요."],"variant_rule":{"alt":[{"stem":"14 − 7 − 7 = 0에서 7을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["2"],"explanation":["빼는 수 7이 몇 개인지 세어요.","14 − 7을 2번 하면 0이 돼요.","14는 7씩 2묶음으로 덜어 낼 수 있어요."],"asset":null},{"stem":"30 − 6 − 6 − 6 − 6 − 6 = 0에서 6을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["5"],"explanation":["빼는 수 6이 몇 개인지 세어요.","30 − 6을 5번 하면 0이 돼요.","30은 6씩 5묶음으로 덜어 낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#3','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',1,'sa','auto','공책 10권을 한 주머니에 2권씩 담으면 몇 주머니가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C3","difficulty":1,"kind":"sa","stem":"공책 10권을 한 주머니에 2권씩 담으면 몇 주머니가 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["10권에서 2권씩 덜어 내요.","2 × □ = 10에서 □ = 5 — 5번 덜어 낼 수 있어요.","그래서 5주머니예요."],"variant_rule":{"alt":[{"stem":"연필 28자루를 한 봉지에 7자루씩 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["28자루에서 7자루씩 덜어 내요.","7 × □ = 28에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4봉지예요."],"asset":null},{"stem":"색종이 24장을 한 상자에 8장씩 담으면 몇 상자가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["24장에서 8장씩 덜어 내요.","8 × □ = 24에서 □ = 3 — 3번 덜어 낼 수 있어요.","그래서 3상자예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#4','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',1,'mc','auto','한 묶음 개수씩 똑같이 덜어 내면 무엇을 알 수 있나요?',ARRAY['M3-1-u3-X03','M3-1-u3-X02','M3-1-u3-X15']::text[],true,'{"seq":4,"concept":"M3-1-u3-C3","difficulty":1,"kind":"mc","stem":"한 묶음 개수씩 똑같이 덜어 내면 무엇을 알 수 있나요?","options":[{"t":"묶음 수","correct":true},{"t":"한 묶음 개수","mis":"M3-1-u3-X03"},{"t":"전체 개수","mis":"M3-1-u3-X02"},{"t":"알 수 없어요","mis":"M3-1-u3-X15"}],"explanation":["몇씩 덜어 내면 몇 묶음인지 알 수 있어요.","같은 수를 0이 될 때까지 되풀이해 빼요.","뺀 횟수가 묶음 수예요."],"variant_rule":{"alt":[{"stem":"「스티커 18장을 한 명에게 6장씩 주면 몇 명에게 줄 수 있나요?」는 무엇을 묻는 문제인가요?","options":[{"t":"몇 묶음(몇 명)인지","correct":true},{"t":"한 명이 몇 장씩인지","mis":"M3-1-u3-X03"},{"t":"스티커가 모두 몇 장인지","mis":"M3-1-u3-X02"},{"t":"스티커가 몇 장 남는지","mis":"M3-1-u3-X15"}],"explanation":["몇씩 덜어 내면 몇 묶음인지 알 수 있어요.","같은 수를 0이 될 때까지 되풀이해 빼요.","뺀 횟수가 묶음 수예요."],"asset":null},{"stem":"사탕 12개를 3개씩 묶어 덜어 낼 때 알맞은 방법은 어느 것인가요?","options":[{"t":"12에서 3씩 0이 될 때까지 빼고 뺀 횟수를 센다","correct":true},{"t":"12에서 3을 한 번만 뺀다","mis":"M3-1-u3-X04"},{"t":"12와 3을 더한다","mis":"M3-1-u3-X13"},{"t":"3명에게 하나씩 번갈아 놓는다","mis":"M3-1-u3-X03"}],"explanation":["몇씩 덜어 내면 몇 묶음인지 알 수 있어요.","같은 수를 0이 될 때까지 되풀이해 빼요.","뺀 횟수가 묶음 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#5','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',2,'mc','auto','연필 16자루를 한 컵에 4자루씩 담으면 몇 컵이 되나요?',ARRAY['M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":5,"concept":"M3-1-u3-C3","difficulty":2,"kind":"mc","stem":"연필 16자루를 한 컵에 4자루씩 담으면 몇 컵이 되나요?","options":[{"t":"4컵","correct":true},{"t":"12컵","mis":"M3-1-u3-X07"},{"t":"5컵","mis":"M3-1-u3-X11"},{"t":"3컵","mis":"M3-1-u3-X11"}],"explanation":["16자루에서 4자루씩 덜어 내요.","4 × □ = 16에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4컵이에요."],"variant_rule":{"alt":[{"stem":"색종이 8장을 한 주머니에 4장씩 담으면 몇 주머니가 되나요?","options":[{"t":"2주머니","correct":true},{"t":"4주머니","mis":"M3-1-u3-X02"},{"t":"3주머니","mis":"M3-1-u3-X11"},{"t":"1주머니","mis":"M3-1-u3-X11"}],"explanation":["8장에서 4장씩 덜어 내요.","4 × □ = 8에서 □ = 2 — 2번 덜어 낼 수 있어요.","그래서 2주머니예요."],"asset":null},{"stem":"구슬 8개를 한 봉지에 2개씩 담으면 몇 봉지가 되나요?","options":[{"t":"4봉지","correct":true},{"t":"2봉지","mis":"M3-1-u3-X02"},{"t":"6봉지","mis":"M3-1-u3-X07"},{"t":"5봉지","mis":"M3-1-u3-X11"}],"explanation":["8개에서 2개씩 덜어 내요.","2 × □ = 8에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#6','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',2,'sa','auto','15에서 5씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 5씩 몇 번 뛰었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u3-C3","difficulty":2,"kind":"sa","stem":"15에서 5씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 5씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["화살표 하나가 5씩 한 번 덜어 낸 거예요.","화살표를 세면 3개 — ?는 0이에요.","15는 5씩 3번 덜어 내면 0 — 3묶음이에요."],"asset":{"type":"jump_row","cells":[15,10,5,null],"step":5,"dir":"down"},"variant_rule":{"alt":[{"stem":"6에서 3씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 3씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["2"],"explanation":["화살표 하나가 3씩 한 번 덜어 낸 거예요.","화살표를 세면 2개 — ?는 0이에요.","6은 3씩 2번 덜어 내면 0 — 2묶음이에요."],"asset":{"type":"jump_row","cells":[6,3,null],"step":3,"dir":"down"}},{"stem":"20에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["5"],"explanation":["화살표 하나가 4씩 한 번 덜어 낸 거예요.","화살표를 세면 5개 — ?는 0이에요.","20은 4씩 5번 덜어 내면 0 — 5묶음이에요."],"asset":{"type":"jump_row","cells":[20,16,12,8,4,null],"step":4,"dir":"down"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#7','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',2,'mc','auto','12를 3씩 묶어 덜어 내는 것을 바르게 나타낸 식은 어느 것인가요?',ARRAY['M3-1-u3-X04']::text[],true,'{"seq":7,"concept":"M3-1-u3-C3","difficulty":2,"kind":"mc","stem":"12를 3씩 묶어 덜어 내는 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"12 − 3 − 3 − 3 − 3 = 0","correct":true},{"t":"12 − 3 − 3 − 3 = 0","mis":"M3-1-u3-X04"},{"t":"12 − 3 = 9","mis":"M3-1-u3-X04"},{"t":"12 − 3 − 3 − 3 − 3 − 3 = 0","mis":"M3-1-u3-X04"}],"explanation":["3씩 덜어 낼 때마다 − 3을 하나씩 써요.","12 − 3을 4번 하면 0이 돼요.","뺀 횟수 4가 묶음 수예요."],"variant_rule":{"alt":[{"stem":"24를 4씩 묶어 덜어 내는 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"24 − 4 − 4 − 4 − 4 − 4 − 4 = 0","correct":true},{"t":"24 − 4 − 4 − 4 − 4 − 4 = 0","mis":"M3-1-u3-X04"},{"t":"24 − 4 = 20","mis":"M3-1-u3-X04"},{"t":"24 − 4 − 4 − 4 − 4 − 4 − 4 − 4 = 0","mis":"M3-1-u3-X04"}],"explanation":["4씩 덜어 낼 때마다 − 4를 하나씩 써요.","24 − 4를 6번 하면 0이 돼요.","뺀 횟수 6이 묶음 수예요."],"asset":null},{"stem":"30을 5씩 묶어 덜어 내는 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"30 − 5 − 5 − 5 − 5 − 5 − 5 = 0","correct":true},{"t":"30 − 5 − 5 − 5 − 5 − 5 = 0","mis":"M3-1-u3-X04"},{"t":"30 − 5 = 25","mis":"M3-1-u3-X04"},{"t":"30 − 5 − 5 − 5 − 5 − 5 − 5 − 5 = 0","mis":"M3-1-u3-X04"}],"explanation":["5씩 덜어 낼 때마다 − 5를 하나씩 써요.","30 − 5를 6번 하면 0이 돼요.","뺀 횟수 6이 묶음 수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#8','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',2,'ox','auto','카드 18장을 6장씩 묶어 덜어 내면 6묶음이에요.',ARRAY['M3-1-u3-X02']::text[],true,'{"seq":8,"concept":"M3-1-u3-C3","difficulty":2,"kind":"ox","stem":"카드 18장을 6장씩 묶어 덜어 내면 6묶음이에요.","answer":"X","reason_options":[{"t":"6씩 3번 덜어 내야 0이 되어 3묶음이라서","correct":true},{"t":"6장씩 묶었으니 묶음 수도 6이라서","mis":"M3-1-u3-X02"}],"mis":"M3-1-u3-X02","explanation":["묻는 것은 묶음 수예요.","18 − 6을 3번 하면 0이에요.","그래서 3묶음이에요. 6은 한 묶음의 개수예요."],"variant_rule":{"alt":[{"stem":"지우개 12개를 3개씩 묶어 덜어 내면 3묶음이에요.","answer":"X","reason_options":[{"t":"3씩 4번 덜어 내야 0이 되어 4묶음이라서","correct":true},{"t":"3개씩 묶었으니 묶음 수도 3이라서","mis":"M3-1-u3-X02"}],"explanation":["묻는 것은 묶음 수예요.","12 − 3을 4번 하면 0이에요.","그래서 4묶음이에요. 3은 한 묶음의 개수예요."],"asset":null},{"stem":"클립 18개를 3개씩 묶어 덜어 내면 3묶음이에요.","answer":"X","reason_options":[{"t":"3씩 6번 덜어 내야 0이 되어 6묶음이라서","correct":true},{"t":"3개씩 묶었으니 묶음 수도 3이라서","mis":"M3-1-u3-X02"}],"explanation":["묻는 것은 묶음 수예요.","18 − 3을 6번 하면 0이에요.","그래서 6묶음이에요. 3은 한 묶음의 개수예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#9','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',2,'match','auto','카드 12장을 나누어요. 물음과 답을 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u3-C3","difficulty":2,"kind":"match","stem":"카드 12장을 나누어요. 물음과 답을 알맞게 이으세요.","pairs":[{"l":"3명에게 똑같이 나누면 한 명에게?","r":"4장씩"},{"l":"3장씩 묶으면?","r":"4묶음"},{"l":"4묶음으로 똑같이 나누면 한 묶음에?","r":"3장씩"}],"mis":"M3-1-u3-X03","explanation":["사람(묶음) 수로 나누면 한 묶음 개수를 구해요.","몇 개씩 덜어 내면 묶음 수를 구해요.","같은 12장도 무엇을 묻는지에 따라 답이 달라요."],"variant_rule":{"alt":[{"stem":"지우개 14개를 나누어요. 물음과 답을 알맞게 이으세요.","pairs":[{"l":"7명에게 똑같이 나누면 한 명에게?","r":"2개씩"},{"l":"7개씩 묶으면?","r":"2묶음"},{"l":"2묶음으로 똑같이 나누면 한 묶음에?","r":"7개씩"}],"explanation":["사람(묶음) 수로 나누면 한 묶음 개수를 구해요.","몇 개씩 덜어 내면 묶음 수를 구해요.","같은 14개도 무엇을 묻는지에 따라 답이 달라요."],"asset":null},{"stem":"클립 12개를 나누어요. 물음과 답을 알맞게 이으세요.","pairs":[{"l":"4명에게 똑같이 나누면 한 명에게?","r":"3개씩"},{"l":"4개씩 묶으면?","r":"3묶음"},{"l":"3묶음으로 똑같이 나누면 한 묶음에?","r":"4개씩"}],"explanation":["사람(묶음) 수로 나누면 한 묶음 개수를 구해요.","몇 개씩 덜어 내면 묶음 수를 구해요.","같은 12개도 무엇을 묻는지에 따라 답이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_basic#10','math',3,1,'u3','L03','g3_1_math_u3_L03_basic','lesson_basic','M3-1-u3-C3',3,'mc','auto','연필 48자루를 한 컵에 8자루씩 담으면 몇 컵이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":10,"concept":"M3-1-u3-C3","difficulty":3,"kind":"mc","stem":"연필 48자루를 한 컵에 8자루씩 담으면 몇 컵이 되나요?","options":[{"t":"6컵","correct":true},{"t":"8컵","mis":"M3-1-u3-X02"},{"t":"40컵","mis":"M3-1-u3-X07"},{"t":"7컵","mis":"M3-1-u3-X11"}],"explanation":["48자루에서 8자루씩 덜어 내요.","8 × □ = 48에서 □ = 6 — 6번 덜어 낼 수 있어요.","그래서 6컵이에요."],"variant_rule":{"alt":[{"stem":"색종이 20장을 한 주머니에 5장씩 담으면 몇 주머니가 되나요?","options":[{"t":"4주머니","correct":true},{"t":"5주머니","mis":"M3-1-u3-X02"},{"t":"15주머니","mis":"M3-1-u3-X07"},{"t":"3주머니","mis":"M3-1-u3-X11"}],"explanation":["20장에서 5장씩 덜어 내요.","5 × □ = 20에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4주머니예요."],"asset":null},{"stem":"구슬 14개를 한 봉지에 7개씩 담으면 몇 봉지가 되나요?","options":[{"t":"2봉지","correct":true},{"t":"7봉지","mis":"M3-1-u3-X02"},{"t":"3봉지","mis":"M3-1-u3-X11"},{"t":"1봉지","mis":"M3-1-u3-X11"}],"explanation":["14개에서 7개씩 덜어 내요.","7 × □ = 14에서 □ = 2 — 2번 덜어 낼 수 있어요.","그래서 2봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#1','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',2,'mc','auto','컵케이크 20개를 5개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":1,"concept":"M3-1-u3-C3","difficulty":2,"kind":"mc","stem":"컵케이크 20개를 5개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"4묶음","correct":true},{"t":"5묶음","mis":"M3-1-u3-X02"},{"t":"15묶음","mis":"M3-1-u3-X07"},{"t":"3묶음","mis":"M3-1-u3-X11"}],"explanation":["5개씩 묶은 테두리를 세어요.","5씩 4번 덜어 내면 20개 모두 덜어 내져요 — 5 × 4 = 20.","그래서 4묶음이에요."],"asset":{"type":"mul_groups","item":"🧁","k":5,"n":4},"variant_rule":{"alt":[{"stem":"도넛 8개를 2개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"4묶음","correct":true},{"t":"2묶음","mis":"M3-1-u3-X02"},{"t":"6묶음","mis":"M3-1-u3-X07"},{"t":"5묶음","mis":"M3-1-u3-X11"}],"explanation":["2개씩 묶은 테두리를 세어요.","2씩 4번 덜어 내면 8개 모두 덜어 내져요 — 2 × 4 = 8.","그래서 4묶음이에요."],"asset":{"type":"mul_groups","item":"🍩","k":2,"n":4}},{"stem":"사과 24개를 8개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"3묶음","correct":true},{"t":"8묶음","mis":"M3-1-u3-X02"},{"t":"16묶음","mis":"M3-1-u3-X07"},{"t":"4묶음","mis":"M3-1-u3-X11"}],"explanation":["8개씩 묶은 테두리를 세어요.","8씩 3번 덜어 내면 24개 모두 덜어 내져요 — 8 × 3 = 24.","그래서 3묶음이에요."],"asset":{"type":"mul_groups","item":"🍎","k":8,"n":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#2','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',2,'sa','auto','20에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C3","difficulty":2,"kind":"sa","stem":"20에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["5"],"explanation":["화살표 하나가 4씩 한 번 덜어 낸 거예요.","화살표를 세면 5개 — ?는 0이에요.","20은 4씩 5번 덜어 내면 0 — 5묶음이에요."],"asset":{"type":"jump_row","cells":[20,16,12,8,4,null],"step":4,"dir":"down"},"variant_rule":{"alt":[{"stem":"15에서 5씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 5씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["화살표 하나가 5씩 한 번 덜어 낸 거예요.","화살표를 세면 3개 — ?는 0이에요.","15는 5씩 3번 덜어 내면 0 — 3묶음이에요."],"asset":{"type":"jump_row","cells":[15,10,5,null],"step":5,"dir":"down"}},{"stem":"8에서 2씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 2씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 2씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","8은 2씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[8,6,4,2,null],"step":2,"dir":"down"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#3','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',3,'error','auto','클립 20개를 5개씩 묶어 덜어 냈어요. 이를 보고 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X15']::text[],true,'{"seq":3,"concept":"M3-1-u3-C3","difficulty":3,"kind":"error","stem":"클립 20개를 5개씩 묶어 덜어 냈어요. 이를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「묶음이 5개야.」","correct":true,"mis_target":"M3-1-u3-X02"},{"t":"도윤 — 「20에서 5씩 4번 빼면 0이 돼.」","mis":"M3-1-u3-X15"},{"t":"시우 — 「5개씩 묶으면 4묶음이야.」","mis":"M3-1-u3-X15"}],"explanation":["20 − 5를 4번 하면 0이에요.","그래서 4묶음이에요.","하랑은 한 묶음 개수 5를 묶음 수로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"귤 8개를 4개씩 묶어 덜어 냈어요. 이를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「묶음이 4개야.」","correct":true,"mis_target":"M3-1-u3-X02"},{"t":"시우 — 「8에서 4씩 2번 빼면 0이 돼.」","mis":"M3-1-u3-X15"},{"t":"서윤 — 「4개씩 묶으면 2묶음이야.」","mis":"M3-1-u3-X15"}],"explanation":["8 − 4를 2번 하면 0이에요.","그래서 2묶음이에요.","은우는 한 묶음 개수 4를 묶음 수로 잘못 말했어요."],"asset":null},{"stem":"공책 21권을 3권씩 묶어 덜어 냈어요. 이를 보고 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「묶음이 3개야.」","correct":true,"mis_target":"M3-1-u3-X02"},{"t":"시우 — 「21에서 3씩 7번 빼면 0이 돼.」","mis":"M3-1-u3-X15"},{"t":"지유 — 「3권씩 묶으면 7묶음이야.」","mis":"M3-1-u3-X15"}],"explanation":["21 − 3을 7번 하면 0이에요.","그래서 7묶음이에요.","하랑은 한 묶음 개수 3을 묶음 수로 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
