INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#5','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',3,'sa','auto','42 − 7 − 7 − 7 − 7 − 7 − 7 = 0에서 7을 몇 번 뺐나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C3","difficulty":3,"kind":"sa","stem":"42 − 7 − 7 − 7 − 7 − 7 − 7 = 0에서 7을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["6"],"explanation":["빼는 수 7이 몇 개인지 세어요.","42 − 7을 6번 하면 0이 돼요.","42는 7씩 6묶음으로 덜어 낼 수 있어요."],"variant_rule":{"alt":[{"stem":"24 − 8 − 8 − 8 = 0에서 8을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["3"],"explanation":["빼는 수 8이 몇 개인지 세어요.","24 − 8을 3번 하면 0이 돼요.","24는 8씩 3묶음으로 덜어 낼 수 있어요."],"asset":null},{"stem":"27 − 9 − 9 − 9 = 0에서 9를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["3"],"explanation":["빼는 수 9가 몇 개인지 세어요.","27 − 9를 3번 하면 0이 돼요.","27은 9씩 3묶음으로 덜어 낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#6','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',3,'sa','auto','귤 36개를 한 컵에 9개씩 담으면 몇 컵이 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u3-C3","difficulty":3,"kind":"sa","stem":"귤 36개를 한 컵에 9개씩 담으면 몇 컵이 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["36개에서 9개씩 덜어 내요.","9 × □ = 36에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4컵이에요."],"variant_rule":{"alt":[{"stem":"공책 6권을 한 주머니에 2권씩 담으면 몇 주머니가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["6권에서 2권씩 덜어 내요.","2 × □ = 6에서 □ = 3 — 3번 덜어 낼 수 있어요.","그래서 3주머니예요."],"asset":null},{"stem":"연필 24자루를 한 봉지에 6자루씩 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["24자루에서 6자루씩 덜어 내요.","6 × □ = 24에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#7','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',3,'ox','auto','공책 12권을 3명에게 똑같이 나누는 것과 3권씩 묶는 것은 묻는 것이 같은 상황이에요.',ARRAY['M3-1-u3-X03']::text[],true,'{"seq":7,"concept":"M3-1-u3-C3","difficulty":3,"kind":"ox","stem":"공책 12권을 3명에게 똑같이 나누는 것과 3권씩 묶는 것은 묻는 것이 같은 상황이에요.","answer":"X","reason_options":[{"t":"하나는 한 명이 받는 수를, 하나는 묶음 수를 물어서","correct":true},{"t":"둘 다 3을 쓰니까 같은 상황이라서","mis":"M3-1-u3-X03"}],"mis":"M3-1-u3-X03","explanation":["3명에게 똑같이 나누면 한 명에게 4권씩이에요.","3권씩 묶으면 4묶음이에요.","식은 둘 다 12 ÷ 3이지만 묻는 것과 답의 뜻이 달라요."],"variant_rule":{"alt":[{"stem":"연필 36자루를 9명에게 똑같이 나누는 것과 9자루씩 묶는 것은 묻는 것이 같은 상황이에요.","answer":"X","reason_options":[{"t":"하나는 한 명이 받는 수를, 하나는 묶음 수를 물어서","correct":true},{"t":"둘 다 9를 쓰니까 같은 상황이라서","mis":"M3-1-u3-X03"}],"explanation":["9명에게 똑같이 나누면 한 명에게 4자루씩이에요.","9자루씩 묶으면 4묶음이에요.","식은 둘 다 36 ÷ 9지만 묻는 것과 답의 뜻이 달라요."],"asset":null},{"stem":"색종이 63장을 9명에게 똑같이 나누는 것과 9장씩 묶는 것은 묻는 것이 같은 상황이에요.","answer":"X","reason_options":[{"t":"하나는 한 명이 받는 수를, 하나는 묶음 수를 물어서","correct":true},{"t":"둘 다 9를 쓰니까 같은 상황이라서","mis":"M3-1-u3-X03"}],"explanation":["9명에게 똑같이 나누면 한 명에게 7장씩이에요.","9장씩 묶으면 7묶음이에요.","식은 둘 다 63 ÷ 9지만 묻는 것과 답의 뜻이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#8','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',4,'essay','teacher','나눔 장터에서 스티커 18장을 한 명에게 6장씩 나누어 주려고 해요. 같은 수를 되풀이해 빼는 방법으로 몇 명에게 줄 수 있는지 구하고 그 과정을 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u3-C3","difficulty":4,"kind":"essay","stem":"나눔 장터에서 스티커 18장을 한 명에게 6장씩 나누어 주려고 해요. 같은 수를 되풀이해 빼는 방법으로 몇 명에게 줄 수 있는지 구하고 그 과정을 써 보세요.","answer_guide":{"answer":"예: 18 − 6 − 6 − 6 = 0으로 6을 3번 빼면 0이 된다. 6장씩 3번 덜어 낼 수 있으므로 3명에게 줄 수 있다(6 × 3 = 18).","scoring_points":["18에서 6을 되풀이해 뺐는가","뺀 횟수 3을 셌는가","3명을 구했는가"]},"explanation":["18 − 6 − 6 − 6 = 0.","6을 3번 뺐어요.","그래서 3명에게 줄 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#9','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',4,'essay','teacher','사탕 12개를 「3명에게 똑같이 나누기」와 「3개씩 묶어 덜어 내기」는 묻는 것이 어떻게 다른지 쓰고, 각각의 답을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u3-C3","difficulty":4,"kind":"essay","stem":"사탕 12개를 「3명에게 똑같이 나누기」와 「3개씩 묶어 덜어 내기」는 묻는 것이 어떻게 다른지 쓰고, 각각의 답을 구해 보세요.","answer_guide":{"answer":"예: 3명에게 똑같이 나누면 한 명이 받는 개수를 묻고 답은 4개씩이다. 3개씩 덜어 내면 몇 묶음인지를 묻고 답은 4묶음이다. 같은 12와 3이지만 하나는 한 묶음의 개수, 하나는 묶음 수를 구한다.","scoring_points":["3명에게 나누면 한 명이 받는 수(4개씩)라고 썼는가","3개씩 덜어 내면 묶음 수(4묶음)라고 썼는가","묻는 것이 다르다고 설명했는가"]},"explanation":["3명에게 → 한 명에 4개씩.","3개씩 → 4묶음.","같은 수라도 묻는 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L03_challenge#10','math',3,1,'u3','L03','g3_1_math_u3_L03_challenge','lesson_challenge','M3-1-u3-C3',4,'sa','auto','구슬 24개에서 4개씩 덜어 내고 있어요. 지금까지 4번 덜어 내서 8개가 남았어요. 몇 번 더 덜어 내면 모두 덜어 내나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u3-C3","difficulty":4,"kind":"sa","stem":"구슬 24개에서 4개씩 덜어 내고 있어요. 지금까지 4번 덜어 내서 8개가 남았어요. 몇 번 더 덜어 내면 모두 덜어 내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["남은 8개에서 4개씩 덜어 내요.","8 ÷ 4 = 2 — 2번 더 덜어 내요.","모두 6번(4 + 2) 덜어 내니 24 ÷ 4 = 6과 맞아요."],"variant_rule":{"alt":[{"stem":"구슬 45개에서 5개씩 덜어 내고 있어요. 지금까지 2번 덜어 내서 35개가 남았어요. 몇 번 더 덜어 내면 모두 덜어 내나요? 숫자로 쓰세요.","answer":["7"],"explanation":["남은 35개에서 5개씩 덜어 내요.","35 ÷ 5 = 7 — 7번 더 덜어 내요.","모두 9번(2 + 7) 덜어 내니 45 ÷ 5 = 9와 맞아요."],"asset":null},{"stem":"구슬 56개에서 8개씩 덜어 내고 있어요. 지금까지 5번 덜어 내서 16개가 남았어요. 몇 번 더 덜어 내면 모두 덜어 내나요? 숫자로 쓰세요.","answer":["2"],"explanation":["남은 16개에서 8개씩 덜어 내요.","16 ÷ 8 = 2 — 2번 더 덜어 내요.","모두 7번(5 + 2) 덜어 내니 56 ÷ 8 = 7과 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#1','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',1,'mc','auto','15 ÷ 3을 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-1-u3-X07','M3-1-u3-X05']::text[],true,'{"seq":1,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"15 ÷ 3을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"15 나누기 3","correct":true},{"t":"15 곱하기 3","mis":"M3-1-u3-X07"},{"t":"3 나누기 15","mis":"M3-1-u3-X05"},{"t":"15 빼기 3","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 15 나누기 3.","15 ÷ 3 = 5는 「15 나누기 3은 5」라고 읽어요."],"variant_rule":{"alt":[{"stem":"16 ÷ 4를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"16 나누기 4","correct":true},{"t":"16 곱하기 4","mis":"M3-1-u3-X07"},{"t":"4 나누기 16","mis":"M3-1-u3-X05"},{"t":"16 빼기 4","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 16 나누기 4.","16 ÷ 4 = 4는 「16 나누기 4는 4」라고 읽어요."],"asset":null},{"stem":"24 ÷ 8을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"24 나누기 8","correct":true},{"t":"24 곱하기 8","mis":"M3-1-u3-X07"},{"t":"8 나누기 24","mis":"M3-1-u3-X05"},{"t":"24 빼기 8","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 24 나누기 8.","24 ÷ 8 = 3은 「24 나누기 8은 3」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#2','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',1,'mc','auto','12 ÷ 4 = 3에서 몫은 어느 것인가요?',ARRAY['M3-1-u3-X06']::text[],true,'{"seq":2,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"12 ÷ 4 = 3에서 몫은 어느 것인가요?","options":[{"t":"3","correct":true},{"t":"12","mis":"M3-1-u3-X06"},{"t":"4","mis":"M3-1-u3-X06"},{"t":"12와 4","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","12는 나누어지는 수, 4는 나누는 수예요.","= 뒤의 3이 몫이에요."],"variant_rule":{"alt":[{"stem":"27 ÷ 3 = 9에서 몫은 어느 것인가요?","options":[{"t":"9","correct":true},{"t":"27","mis":"M3-1-u3-X06"},{"t":"3","mis":"M3-1-u3-X06"},{"t":"27과 3","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","27은 나누어지는 수, 3은 나누는 수예요.","= 뒤의 9가 몫이에요."],"asset":null},{"stem":"8 ÷ 2 = 4에서 몫은 어느 것인가요?","options":[{"t":"4","correct":true},{"t":"8","mis":"M3-1-u3-X06"},{"t":"2","mis":"M3-1-u3-X06"},{"t":"8과 2","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","8은 나누어지는 수, 2는 나누는 수예요.","= 뒤의 4가 몫이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#3','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',1,'sa','auto','20 ÷ 5의 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C4","difficulty":1,"kind":"sa","stem":"20 ÷ 5의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20을 5묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","5 × 4 = 20이에요.","그래서 20 ÷ 5의 몫은 4예요."],"variant_rule":{"alt":[{"stem":"15 ÷ 3의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["15를 3묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","3 × 5 = 15예요.","그래서 15 ÷ 3의 몫은 5예요."],"asset":null},{"stem":"8 ÷ 2의 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["8을 2묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","2 × 4 = 8이에요.","그래서 8 ÷ 2의 몫은 4예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#4','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',1,'mc','auto','연필 12자루를 4명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X03','M3-1-u3-X13']::text[],true,'{"seq":4,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"연필 12자루를 4명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"12 ÷ 4","correct":true},{"t":"4 ÷ 12","mis":"M3-1-u3-X05"},{"t":"12 ÷ 3","mis":"M3-1-u3-X03"},{"t":"12 × 4","mis":"M3-1-u3-X13"}],"explanation":["전체 12자루를 4명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 12 ÷ 4.","12 ÷ 4 = 3 — 한 명이 3자루씩 받아요."],"variant_rule":{"alt":[{"stem":"색종이 6장을 3명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"6 ÷ 3","correct":true},{"t":"3 ÷ 6","mis":"M3-1-u3-X05"},{"t":"6 ÷ 2","mis":"M3-1-u3-X03"},{"t":"6 × 3","mis":"M3-1-u3-X13"}],"explanation":["전체 6장을 3명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 6 ÷ 3.","6 ÷ 3 = 2 — 한 명이 2장씩 받아요."],"asset":null},{"stem":"구슬 30개를 6명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"30 ÷ 6","correct":true},{"t":"6 ÷ 30","mis":"M3-1-u3-X05"},{"t":"30 ÷ 5","mis":"M3-1-u3-X03"},{"t":"30 × 6","mis":"M3-1-u3-X13"}],"explanation":["전체 30개를 6명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 30 ÷ 6.","30 ÷ 6 = 5 — 한 명이 5개씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#5','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',2,'sa','auto','당근 18개를 접시 3개에 똑같이 나눈 그림이에요. 나눗셈식 18 ÷ 3 = □에서 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C4","difficulty":2,"kind":"sa","stem":"당근 18개를 접시 3개에 똑같이 나눈 그림이에요. 나눗셈식 18 ÷ 3 = □에서 □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["접시 3개에 6개씩 놓였어요.","18을 3으로 나누면 한 접시에 6개 — 이것이 몫이에요.","18 ÷ 3 = 6."],"asset":{"type":"mul_groups","item":"🥕","k":6,"n":3},"variant_rule":{"alt":[{"stem":"물고기 24마리를 접시 3개에 똑같이 나눈 그림이에요. 나눗셈식 24 ÷ 3 = □에서 □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["접시 3개에 8마리씩 놓였어요.","24를 3으로 나누면 한 접시에 8마리 — 이것이 몫이에요.","24 ÷ 3 = 8."],"asset":{"type":"mul_groups","item":"🐟","k":8,"n":3}},{"stem":"사탕 8개를 접시 4개에 똑같이 나눈 그림이에요. 나눗셈식 8 ÷ 4 = □에서 □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["접시 4개에 2개씩 놓였어요.","8을 4로 나누면 한 접시에 2개 — 이것이 몫이에요.","8 ÷ 4 = 2."],"asset":{"type":"mul_groups","item":"🍬","k":2,"n":4}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#6','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',2,'mc','auto','지우개 24개를 한 봉지에 4개씩 담으려고 해요. 몇 봉지가 되는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X03','M3-1-u3-X13']::text[],true,'{"seq":6,"concept":"M3-1-u3-C4","difficulty":2,"kind":"mc","stem":"지우개 24개를 한 봉지에 4개씩 담으려고 해요. 몇 봉지가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 4","correct":true},{"t":"4 ÷ 24","mis":"M3-1-u3-X05"},{"t":"24 ÷ 6","mis":"M3-1-u3-X03"},{"t":"24 − 4","mis":"M3-1-u3-X13"}],"explanation":["24개에서 4개씩 덜어 내는 상황이에요.","전체 24를 앞에, 한 봉지 개수 4를 뒤에 — 24 ÷ 4.","24 ÷ 4 = 6 — 6봉지예요."],"variant_rule":{"alt":[{"stem":"클립 28개를 한 상자에 7개씩 담으려고 해요. 몇 상자가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"28 ÷ 7","correct":true},{"t":"7 ÷ 28","mis":"M3-1-u3-X05"},{"t":"28 ÷ 4","mis":"M3-1-u3-X03"},{"t":"28 − 7","mis":"M3-1-u3-X13"}],"explanation":["28개에서 7개씩 덜어 내는 상황이에요.","전체 28을 앞에, 한 상자 개수 7을 뒤에 — 28 ÷ 7.","28 ÷ 7 = 4 — 4상자예요."],"asset":null},{"stem":"귤 30개를 한 접시에 5개씩 담으려고 해요. 몇 접시가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"30 ÷ 5","correct":true},{"t":"5 ÷ 30","mis":"M3-1-u3-X05"},{"t":"30 ÷ 6","mis":"M3-1-u3-X03"},{"t":"30 − 5","mis":"M3-1-u3-X13"}],"explanation":["30개에서 5개씩 덜어 내는 상황이에요.","전체 30을 앞에, 한 접시 개수 5를 뒤에 — 30 ÷ 5.","30 ÷ 5 = 6 — 6접시예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#7','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',2,'ox','auto','12 ÷ 4와 4 ÷ 12는 같은 식이에요.',ARRAY['M3-1-u3-X05']::text[],true,'{"seq":7,"concept":"M3-1-u3-C4","difficulty":2,"kind":"ox","stem":"12 ÷ 4와 4 ÷ 12는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"mis":"M3-1-u3-X05","explanation":["12 ÷ 4는 「12를 4로 나누기」예요.","4 ÷ 12는 작은 4를 큰 12로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"variant_rule":{"alt":[{"stem":"63 ÷ 7과 7 ÷ 63은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["63 ÷ 7은 「63을 7로 나누기」예요.","7 ÷ 63은 작은 7을 큰 63으로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null},{"stem":"24 ÷ 6과 6 ÷ 24는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["24 ÷ 6은 「24를 6으로 나누기」예요.","6 ÷ 24는 작은 6을 큰 24로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#8','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',2,'match','auto','클립 나눔 상황과 알맞은 나눗셈식을 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C4","difficulty":2,"kind":"match","stem":"클립 나눔 상황과 알맞은 나눗셈식을 이으세요.","pairs":[{"l":"12개 → 4명에게 똑같이","r":"12 ÷ 4"},{"l":"12개 → 3개씩 묶기","r":"12 ÷ 3"},{"l":"18개 → 9명에게 똑같이","r":"18 ÷ 9"}],"mis":"M3-1-u3-X05","explanation":["전체를 앞에, 사람 수나 한 묶음 개수를 뒤에 써요.","12 ÷ 4 = 3, 12 ÷ 3 = 4.","18 ÷ 9 = 2."],"variant_rule":{"alt":[{"stem":"귤 나눔 상황과 알맞은 나눗셈식을 이으세요.","pairs":[{"l":"6개 → 2명에게 똑같이","r":"6 ÷ 2"},{"l":"6개 → 3개씩 묶기","r":"6 ÷ 3"},{"l":"63개 → 7명에게 똑같이","r":"63 ÷ 7"}],"explanation":["전체를 앞에, 사람 수나 한 묶음 개수를 뒤에 써요.","6 ÷ 2 = 3, 6 ÷ 3 = 2.","63 ÷ 7 = 9."],"asset":null},{"stem":"공책 나눔 상황과 알맞은 나눗셈식을 이으세요.","pairs":[{"l":"32권 → 4명에게 똑같이","r":"32 ÷ 4"},{"l":"32권 → 8권씩 묶기","r":"32 ÷ 8"},{"l":"27권 → 3명에게 똑같이","r":"27 ÷ 3"}],"explanation":["전체를 앞에, 사람 수나 한 묶음 개수를 뒤에 써요.","32 ÷ 4 = 8, 32 ÷ 8 = 4.","27 ÷ 3 = 9."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#9','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',2,'mc','auto','18 ÷ 6의 몫은 얼마인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":9,"concept":"M3-1-u3-C4","difficulty":2,"kind":"mc","stem":"18 ÷ 6의 몫은 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M3-1-u3-X02"},{"t":"12","mis":"M3-1-u3-X07"},{"t":"4","mis":"M3-1-u3-X11"}],"explanation":["18을 6묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","6 × 3 = 18이에요.","그래서 18 ÷ 6의 몫은 3이에요."],"variant_rule":{"alt":[{"stem":"40 ÷ 8의 몫은 얼마인가요?","options":[{"t":"5","correct":true},{"t":"8","mis":"M3-1-u3-X02"},{"t":"32","mis":"M3-1-u3-X07"},{"t":"6","mis":"M3-1-u3-X11"}],"explanation":["40을 8묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","8 × 5 = 40이에요.","그래서 40 ÷ 8의 몫은 5예요."],"asset":null},{"stem":"54 ÷ 6의 몫은 얼마인가요?","options":[{"t":"9","correct":true},{"t":"6","mis":"M3-1-u3-X02"},{"t":"48","mis":"M3-1-u3-X07"},{"t":"10","mis":"M3-1-u3-X11"}],"explanation":["54를 6묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","6 × 9 = 54예요.","그래서 54 ÷ 6의 몫은 9예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_basic#10','math',3,1,'u3','L04','g3_1_math_u3_L04_basic','lesson_basic','M3-1-u3-C4',3,'error','auto','20 ÷ 4 = 5를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u3-X06','M3-1-u3-X15']::text[],true,'{"seq":10,"concept":"M3-1-u3-C4","difficulty":3,"kind":"error","stem":"20 ÷ 4 = 5를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「몫은 20이야.」","correct":true,"mis_target":"M3-1-u3-X06"},{"t":"하린 — 「20 나누기 4는 5라고 읽어.」","mis":"M3-1-u3-X15"},{"t":"도윤 — 「나누는 수는 4야.」","mis":"M3-1-u3-X15"}],"explanation":["나누어지는 수 ÷ 나누는 수 = 몫이에요.","20은 나누어지는 수, 4는 나누는 수, 5는 몫이에요.","은우는 나누어지는 수를 몫이라고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"35 ÷ 7 = 5를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「몫은 35야.」","correct":true,"mis_target":"M3-1-u3-X06"},{"t":"도윤 — 「35 나누기 7은 5라고 읽어.」","mis":"M3-1-u3-X15"},{"t":"서윤 — 「나누는 수는 7이야.」","mis":"M3-1-u3-X15"}],"explanation":["나누어지는 수 ÷ 나누는 수 = 몫이에요.","35는 나누어지는 수, 7은 나누는 수, 5는 몫이에요.","하랑은 나누어지는 수를 몫이라고 잘못 말했어요."],"asset":null},{"stem":"42 ÷ 6 = 7을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「몫은 42야.」","correct":true,"mis_target":"M3-1-u3-X06"},{"t":"은우 — 「42 나누기 6은 7이라고 읽어.」","mis":"M3-1-u3-X15"},{"t":"서윤 — 「나누는 수는 6이야.」","mis":"M3-1-u3-X15"}],"explanation":["나누어지는 수 ÷ 나누는 수 = 몫이에요.","42는 나누어지는 수, 6은 나누는 수, 7은 몫이에요.","하랑은 나누어지는 수를 몫이라고 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#1','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',2,'mc','auto','지우개 24개를 한 봉지에 6개씩 담으려고 해요. 몇 봉지가 되는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X03','M3-1-u3-X13']::text[],true,'{"seq":1,"concept":"M3-1-u3-C4","difficulty":2,"kind":"mc","stem":"지우개 24개를 한 봉지에 6개씩 담으려고 해요. 몇 봉지가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"24 ÷ 6","correct":true},{"t":"6 ÷ 24","mis":"M3-1-u3-X05"},{"t":"24 ÷ 4","mis":"M3-1-u3-X03"},{"t":"24 − 6","mis":"M3-1-u3-X13"}],"explanation":["24개에서 6개씩 덜어 내는 상황이에요.","전체 24를 앞에, 한 봉지 개수 6을 뒤에 — 24 ÷ 6.","24 ÷ 6 = 4 — 4봉지예요."],"variant_rule":{"alt":[{"stem":"클립 45개를 한 상자에 9개씩 담으려고 해요. 몇 상자가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"45 ÷ 9","correct":true},{"t":"9 ÷ 45","mis":"M3-1-u3-X05"},{"t":"45 ÷ 5","mis":"M3-1-u3-X03"},{"t":"45 − 9","mis":"M3-1-u3-X13"}],"explanation":["45개에서 9개씩 덜어 내는 상황이에요.","전체 45를 앞에, 한 상자 개수 9를 뒤에 — 45 ÷ 9.","45 ÷ 9 = 5 — 5상자예요."],"asset":null},{"stem":"귤 18개를 한 접시에 6개씩 담으려고 해요. 몇 접시가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"18 ÷ 6","correct":true},{"t":"6 ÷ 18","mis":"M3-1-u3-X05"},{"t":"18 ÷ 3","mis":"M3-1-u3-X03"},{"t":"18 − 6","mis":"M3-1-u3-X13"}],"explanation":["18개에서 6개씩 덜어 내는 상황이에요.","전체 18을 앞에, 한 접시 개수 6을 뒤에 — 18 ÷ 6.","18 ÷ 6 = 3 — 3접시예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#2','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',2,'sa','auto','당근 20개를 접시 5개에 똑같이 나눈 그림이에요. 나눗셈식 20 ÷ 5 = □에서 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C4","difficulty":2,"kind":"sa","stem":"당근 20개를 접시 5개에 똑같이 나눈 그림이에요. 나눗셈식 20 ÷ 5 = □에서 □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["접시 5개에 4개씩 놓였어요.","20을 5로 나누면 한 접시에 4개 — 이것이 몫이에요.","20 ÷ 5 = 4."],"asset":{"type":"mul_groups","item":"🥕","k":4,"n":5},"variant_rule":{"alt":[{"stem":"물고기 14마리를 접시 7개에 똑같이 나눈 그림이에요. 나눗셈식 14 ÷ 7 = □에서 □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["접시 7개에 2마리씩 놓였어요.","14를 7로 나누면 한 접시에 2마리 — 이것이 몫이에요.","14 ÷ 7 = 2."],"asset":{"type":"mul_groups","item":"🐟","k":2,"n":7}},{"stem":"사탕 18개를 접시 2개에 똑같이 나눈 그림이에요. 나눗셈식 18 ÷ 2 = □에서 □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["접시 2개에 9개씩 놓였어요.","18을 2로 나누면 한 접시에 9개 — 이것이 몫이에요.","18 ÷ 2 = 9."],"asset":{"type":"mul_groups","item":"🍬","k":9,"n":2}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#3','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',3,'error','auto','30 ÷ 6 = 5를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u3-X06','M3-1-u3-X15']::text[],true,'{"seq":3,"concept":"M3-1-u3-C4","difficulty":3,"kind":"error","stem":"30 ÷ 6 = 5를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「몫은 30이야.」","correct":true,"mis_target":"M3-1-u3-X06"},{"t":"지유 — 「30 나누기 6은 5라고 읽어.」","mis":"M3-1-u3-X15"},{"t":"하린 — 「나누는 수는 6이야.」","mis":"M3-1-u3-X15"}],"explanation":["나누어지는 수 ÷ 나누는 수 = 몫이에요.","30은 나누어지는 수, 6은 나누는 수, 5는 몫이에요.","도윤은 나누어지는 수를 몫이라고 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"40 ÷ 8 = 5를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「몫은 40이야.」","correct":true,"mis_target":"M3-1-u3-X06"},{"t":"서윤 — 「40 나누기 8은 5라고 읽어.」","mis":"M3-1-u3-X15"},{"t":"도윤 — 「나누는 수는 8이야.」","mis":"M3-1-u3-X15"}],"explanation":["나누어지는 수 ÷ 나누는 수 = 몫이에요.","40은 나누어지는 수, 8은 나누는 수, 5는 몫이에요.","하린은 나누어지는 수를 몫이라고 잘못 말했어요."],"asset":null},{"stem":"56 ÷ 8 = 7을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「몫은 56이야.」","correct":true,"mis_target":"M3-1-u3-X06"},{"t":"하랑 — 「56 나누기 8은 7이라고 읽어.」","mis":"M3-1-u3-X15"},{"t":"도윤 — 「나누는 수는 8이야.」","mis":"M3-1-u3-X15"}],"explanation":["나누어지는 수 ÷ 나누는 수 = 몫이에요.","56은 나누어지는 수, 8은 나누는 수, 7은 몫이에요.","서윤은 나누어지는 수를 몫이라고 잘못 말했어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#4','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',3,'match','auto','귤 나눔 상황과 알맞은 나눗셈식을 이으세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u3-C4","difficulty":3,"kind":"match","stem":"귤 나눔 상황과 알맞은 나눗셈식을 이으세요.","pairs":[{"l":"24개 → 6명에게 똑같이","r":"24 ÷ 6"},{"l":"24개 → 4개씩 묶기","r":"24 ÷ 4"},{"l":"15개 → 5명에게 똑같이","r":"15 ÷ 5"}],"mis":"M3-1-u3-X05","explanation":["전체를 앞에, 사람 수나 한 묶음 개수를 뒤에 써요.","24 ÷ 6 = 4, 24 ÷ 4 = 6.","15 ÷ 5 = 3."],"variant_rule":{"alt":[{"stem":"공책 나눔 상황과 알맞은 나눗셈식을 이으세요.","pairs":[{"l":"36권 → 4명에게 똑같이","r":"36 ÷ 4"},{"l":"36권 → 9권씩 묶기","r":"36 ÷ 9"},{"l":"56권 → 7명에게 똑같이","r":"56 ÷ 7"}],"explanation":["전체를 앞에, 사람 수나 한 묶음 개수를 뒤에 써요.","36 ÷ 4 = 9, 36 ÷ 9 = 4.","56 ÷ 7 = 8."],"asset":null},{"stem":"연필 나눔 상황과 알맞은 나눗셈식을 이으세요.","pairs":[{"l":"12자루 → 2명에게 똑같이","r":"12 ÷ 2"},{"l":"12자루 → 6자루씩 묶기","r":"12 ÷ 6"},{"l":"18자루 → 9명에게 똑같이","r":"18 ÷ 9"}],"explanation":["전체를 앞에, 사람 수나 한 묶음 개수를 뒤에 써요.","12 ÷ 2 = 6, 12 ÷ 6 = 2.","18 ÷ 9 = 2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#5','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',3,'mc','auto','56 ÷ 8의 몫은 얼마인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":5,"concept":"M3-1-u3-C4","difficulty":3,"kind":"mc","stem":"56 ÷ 8의 몫은 얼마인가요?","options":[{"t":"7","correct":true},{"t":"8","mis":"M3-1-u3-X02"},{"t":"48","mis":"M3-1-u3-X07"},{"t":"6","mis":"M3-1-u3-X11"}],"explanation":["56을 8묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","8 × 7 = 56이에요.","그래서 56 ÷ 8의 몫은 7이에요."],"variant_rule":{"alt":[{"stem":"28 ÷ 7의 몫은 얼마인가요?","options":[{"t":"4","correct":true},{"t":"7","mis":"M3-1-u3-X02"},{"t":"21","mis":"M3-1-u3-X07"},{"t":"5","mis":"M3-1-u3-X11"}],"explanation":["28을 7묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","7 × 4 = 28이에요.","그래서 28 ÷ 7의 몫은 4예요."],"asset":null},{"stem":"20 ÷ 4의 몫은 얼마인가요?","options":[{"t":"5","correct":true},{"t":"4","mis":"M3-1-u3-X02"},{"t":"16","mis":"M3-1-u3-X07"},{"t":"6","mis":"M3-1-u3-X11"}],"explanation":["20을 4묶음으로 똑같이 나누면 한 묶음에 몇인지 생각해요.","4 × 5 = 20이에요.","그래서 20 ÷ 4의 몫은 5예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#6','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',3,'ox','auto','30 ÷ 6과 6 ÷ 30은 같은 식이에요.',ARRAY['M3-1-u3-X05']::text[],true,'{"seq":6,"concept":"M3-1-u3-C4","difficulty":3,"kind":"ox","stem":"30 ÷ 6과 6 ÷ 30은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"mis":"M3-1-u3-X05","explanation":["30 ÷ 6은 「30을 6으로 나누기」예요.","6 ÷ 30은 작은 6을 큰 30으로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"variant_rule":{"alt":[{"stem":"54 ÷ 6과 6 ÷ 54는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["54 ÷ 6은 「54를 6으로 나누기」예요.","6 ÷ 54는 작은 6을 큰 54로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null},{"stem":"20 ÷ 4와 4 ÷ 20은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["20 ÷ 4는 「20을 4로 나누기」예요.","4 ÷ 20은 작은 4를 큰 20으로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#7','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',3,'mc','auto','18 ÷ 6 = 3에서 나누어지는 수는 무엇인가요?',ARRAY['M3-1-u3-X06','M3-1-u3-X07']::text[],true,'{"seq":7,"concept":"M3-1-u3-C4","difficulty":3,"kind":"mc","stem":"18 ÷ 6 = 3에서 나누어지는 수는 무엇인가요?","options":[{"t":"18","correct":true},{"t":"3","mis":"M3-1-u3-X06"},{"t":"6","mis":"M3-1-u3-X06"},{"t":"24","mis":"M3-1-u3-X07"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","18 ÷ 6 = 3에서 18은 나누어지는 수, 6은 나누는 수, 3은 몫이에요.","그래서 나누어지는 수는 18이에요."],"variant_rule":{"alt":[{"stem":"20 ÷ 5 = 4에서 나누는 수는 무엇인가요?","options":[{"t":"5","correct":true},{"t":"20","mis":"M3-1-u3-X06"},{"t":"4","mis":"M3-1-u3-X06"},{"t":"15","mis":"M3-1-u3-X07"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","20 ÷ 5 = 4에서 20은 나누어지는 수, 5는 나누는 수, 4는 몫이에요.","그래서 나누는 수는 5예요."],"asset":null},{"stem":"42 ÷ 6 = 7에서 나누어지는 수는 무엇인가요?","options":[{"t":"42","correct":true},{"t":"7","mis":"M3-1-u3-X06"},{"t":"6","mis":"M3-1-u3-X06"},{"t":"48","mis":"M3-1-u3-X07"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","42 ÷ 6 = 7에서 42는 나누어지는 수, 6은 나누는 수, 7은 몫이에요.","그래서 나누어지는 수는 42예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#8','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',4,'essay','teacher','사탕 12개를 「4명에게 똑같이 나누는 상황」과 「4개씩 봉지에 담는 상황」을 각각 나눗셈식으로 나타내고, 몫이 무엇을 뜻하는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u3-C4","difficulty":4,"kind":"essay","stem":"사탕 12개를 「4명에게 똑같이 나누는 상황」과 「4개씩 봉지에 담는 상황」을 각각 나눗셈식으로 나타내고, 몫이 무엇을 뜻하는지 써 보세요.","answer_guide":{"answer":"예: 4명에게 똑같이 나누면 12 ÷ 4 = 3이고 몫 3은 한 명이 받는 사탕 수(3개씩)이다. 4개씩 봉지에 담으면 12 ÷ 4 = 3이고 몫 3은 봉지 수(3봉지)이다. 식은 같아도 몫이 뜻하는 것이 다르다.","scoring_points":["두 상황을 12 ÷ 4 = 3으로 나타냈는가","몫이 한 명이 받는 수·봉지 수를 뜻한다고 각각 썼는가","식은 같아도 뜻이 다르다고 설명했는가"]},"explanation":["두 상황 모두 12 ÷ 4 = 3.","첫째는 한 명에 3개씩, 둘째는 3봉지.","몫의 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#9','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',4,'essay','teacher','친구가 「12 ÷ 4와 4 ÷ 12는 같은 식이야.」라고 말했어요. 이 말이 맞는지 판단하고 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u3-C4","difficulty":4,"kind":"essay","stem":"친구가 「12 ÷ 4와 4 ÷ 12는 같은 식이야.」라고 말했어요. 이 말이 맞는지 판단하고 까닭을 써 보세요.","answer_guide":{"answer":"예: 맞지 않다. 12 ÷ 4는 12를 4묶음으로 똑같이 나누는 것이고 몫은 3이다. 4 ÷ 12는 4를 12묶음으로 나누는 것이라 뜻이 다르다. 나눗셈식은 앞에 나누어지는 수(전체)를 써야 하므로 순서를 바꾸면 안 된다.","scoring_points":["맞지 않다고 판단했는가","12 ÷ 4의 뜻(몫 3)을 썼는가","앞뒤 순서를 바꾸면 뜻이 달라진다고 썼는가"]},"explanation":["12 ÷ 4 = 3.","4 ÷ 12는 4를 12로 나누는 식 — 뜻이 달라요.","나눗셈은 순서가 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L04_challenge#10','math',3,1,'u3','L04','g3_1_math_u3_L04_challenge','lesson_challenge','M3-1-u3-C4',4,'mc','auto','15 ÷ 3 = 5에 알맞은 이야기는 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X13','M3-1-u3-X06']::text[],true,'{"seq":10,"concept":"M3-1-u3-C4","difficulty":4,"kind":"mc","stem":"15 ÷ 3 = 5에 알맞은 이야기는 어느 것인가요?","options":[{"t":"지우개 15개를 3명에게 똑같이 나누면 한 명에게 5개씩","correct":true},{"t":"지우개 3개를 15명에게 똑같이 나누면 한 명에게 5개씩","mis":"M3-1-u3-X05"},{"t":"지우개 15개에 3개를 더 받으면 모두 18개","mis":"M3-1-u3-X13"},{"t":"지우개 15개를 5명에게 똑같이 나누면 한 명에게 5개씩","mis":"M3-1-u3-X06"}],"explanation":["15 ÷ 3은 15를 3묶음(3명)으로 똑같이 나누는 거예요.","3명에게 똑같이 나누면 한 명에게 5개씩 — 몫 5예요.","앞뒤를 바꾸거나 더하는 이야기는 이 식과 맞지 않아요."],"variant_rule":{"alt":[{"stem":"27 ÷ 3 = 9에 알맞은 이야기는 어느 것인가요?","options":[{"t":"클립 27개를 3명에게 똑같이 나누면 한 명에게 9개씩","correct":true},{"t":"클립 3개를 27명에게 똑같이 나누면 한 명에게 9개씩","mis":"M3-1-u3-X05"},{"t":"클립 27개에 3개를 더 받으면 모두 30개","mis":"M3-1-u3-X13"},{"t":"클립 27개를 9명에게 똑같이 나누면 한 명에게 9개씩","mis":"M3-1-u3-X06"}],"explanation":["27 ÷ 3은 27을 3묶음(3명)으로 똑같이 나누는 거예요.","3명에게 똑같이 나누면 한 명에게 9개씩 — 몫 9예요.","앞뒤를 바꾸거나 더하는 이야기는 이 식과 맞지 않아요."],"asset":null},{"stem":"8 ÷ 2 = 4에 알맞은 이야기는 어느 것인가요?","options":[{"t":"귤 8개를 2명에게 똑같이 나누면 한 명에게 4개씩","correct":true},{"t":"귤 2개를 8명에게 똑같이 나누면 한 명에게 4개씩","mis":"M3-1-u3-X05"},{"t":"귤 8개에 2개를 더 받으면 모두 10개","mis":"M3-1-u3-X13"},{"t":"귤 8개를 4명에게 똑같이 나누면 한 명에게 4개씩","mis":"M3-1-u3-X06"}],"explanation":["8 ÷ 2는 8을 2묶음(2명)으로 똑같이 나누는 거예요.","2명에게 똑같이 나누면 한 명에게 4개씩 — 몫 4예요.","앞뒤를 바꾸거나 더하는 이야기는 이 식과 맞지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#1','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',1,'mc','auto','사탕을 한 줄에 5개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?',ARRAY['M3-1-u3-X09','M3-1-u3-X11','M3-1-u3-X13']::text[],true,'{"seq":1,"concept":"M3-1-u3-C5","difficulty":1,"kind":"mc","stem":"사탕을 한 줄에 5개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"5 × 2 = 10","correct":true},{"t":"5 × 3 = 15","mis":"M3-1-u3-X09"},{"t":"5 × 2 = 15","mis":"M3-1-u3-X11"},{"t":"5 + 2 = 7","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 5개씩, 줄은 2줄이에요.","5씩 2줄이니 5 × 2.","5 × 2 = 10 — 모두 10개."],"asset":{"type":"mul_groups","item":"🍬","k":5,"n":2,"look":"rows"},"variant_rule":{"alt":[{"stem":"쿠키를 한 줄에 4개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"4 × 5 = 20","correct":true},{"t":"4 × 6 = 24","mis":"M3-1-u3-X09"},{"t":"4 × 5 = 24","mis":"M3-1-u3-X11"},{"t":"4 + 5 = 9","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 4개씩, 줄은 5줄이에요.","4씩 5줄이니 4 × 5.","4 × 5 = 20 — 모두 20개."],"asset":{"type":"mul_groups","item":"🍪","k":4,"n":5,"look":"rows"}},{"stem":"딸기를 한 줄에 5개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"5 × 3 = 15","correct":true},{"t":"5 × 4 = 20","mis":"M3-1-u3-X09"},{"t":"5 × 3 = 20","mis":"M3-1-u3-X11"},{"t":"5 + 3 = 8","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 5개씩, 줄은 3줄이에요.","5씩 3줄이니 5 × 3.","5 × 3 = 15 — 모두 15개."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":3,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#2','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',1,'mc','auto','3 × 4 = 12를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X08']::text[],true,'{"seq":2,"concept":"M3-1-u3-C5","difficulty":1,"kind":"mc","stem":"3 × 4 = 12를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"12 ÷ 3 = 4","correct":true},{"t":"3 ÷ 12 = 4","mis":"M3-1-u3-X05"},{"t":"12 ÷ 3 = 9","mis":"M3-1-u3-X08"},{"t":"12 ÷ 4 = 4","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 3 × 4 = 12에서 곱 12가 나누어지는 수가 돼요.","12를 3으로 나누면 4 — 12 ÷ 3 = 4.","같은 세 수 3, 4, 12만 써요."],"variant_rule":{"alt":[{"stem":"7 × 5 = 35를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"35 ÷ 7 = 5","correct":true},{"t":"7 ÷ 35 = 5","mis":"M3-1-u3-X05"},{"t":"35 ÷ 7 = 28","mis":"M3-1-u3-X08"},{"t":"35 ÷ 8 = 5","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 7 × 5 = 35에서 곱 35가 나누어지는 수가 돼요.","35를 7로 나누면 5 — 35 ÷ 7 = 5.","같은 세 수 7, 5, 35만 써요."],"asset":null},{"stem":"9 × 8 = 72를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"72 ÷ 9 = 8","correct":true},{"t":"9 ÷ 72 = 8","mis":"M3-1-u3-X05"},{"t":"72 ÷ 9 = 63","mis":"M3-1-u3-X08"},{"t":"72 ÷ 10 = 8","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 9 × 8 = 72에서 곱 72가 나누어지는 수가 돼요.","72를 9로 나누면 8 — 72 ÷ 9 = 8.","같은 세 수 9, 8, 72만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#3','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',1,'mc','auto','12 ÷ 4 = 3을 곱셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X08','M3-1-u3-X07']::text[],true,'{"seq":3,"concept":"M3-1-u3-C5","difficulty":1,"kind":"mc","stem":"12 ÷ 4 = 3을 곱셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"4 × 3 = 12","correct":true},{"t":"12 × 4 = 3","mis":"M3-1-u3-X08"},{"t":"4 × 3 = 7","mis":"M3-1-u3-X07"},{"t":"4 × 4 = 16","mis":"M3-1-u3-X08"}],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 3 = 12예요.","12, 4, 3 — 같은 세 수가 한 가족이에요."],"variant_rule":{"alt":[{"stem":"40 ÷ 5 = 8을 곱셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"5 × 8 = 40","correct":true},{"t":"40 × 5 = 8","mis":"M3-1-u3-X08"},{"t":"5 × 8 = 13","mis":"M3-1-u3-X07"},{"t":"5 × 5 = 25","mis":"M3-1-u3-X08"}],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","5 × 8 = 40이에요.","40, 5, 8 — 같은 세 수가 한 가족이에요."],"asset":null},{"stem":"42 ÷ 6 = 7을 곱셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"6 × 7 = 42","correct":true},{"t":"42 × 6 = 7","mis":"M3-1-u3-X08"},{"t":"6 × 7 = 13","mis":"M3-1-u3-X07"},{"t":"6 × 6 = 36","mis":"M3-1-u3-X08"}],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","6 × 7 = 42예요.","42, 6, 7 — 같은 세 수가 한 가족이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#4','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',1,'sa','auto','별 스티커 20장을 한 줄에 4장씩 늘어놓은 그림이에요. 20 ÷ 4 = □에서 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u3-C5","difficulty":1,"kind":"sa","stem":"별 스티커 20장을 한 줄에 4장씩 늘어놓은 그림이에요. 20 ÷ 4 = □에서 □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["한 줄에 4장씩이에요.","20을 4장씩 나누면 몇 줄인지 세어요 — 5줄.","20 ÷ 4 = 5 — 4 × 5 = 20과 한 가족이에요."],"asset":{"type":"mul_groups","item":"⭐","k":4,"n":5,"look":"rows"},"variant_rule":{"alt":[{"stem":"컵케이크 8개를 한 줄에 4개씩 늘어놓은 그림이에요. 8 ÷ 4 = □에서 □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["한 줄에 4개씩이에요.","8을 4개씩 나누면 몇 줄인지 세어요 — 2줄.","8 ÷ 4 = 2 — 4 × 2 = 8과 한 가족이에요."],"asset":{"type":"mul_groups","item":"🧁","k":4,"n":2,"look":"rows"}},{"stem":"도넛 24개를 한 줄에 4개씩 늘어놓은 그림이에요. 24 ÷ 4 = □에서 □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["한 줄에 4개씩이에요.","24를 4개씩 나누면 몇 줄인지 세어요 — 6줄.","24 ÷ 4 = 6 — 4 × 6 = 24와 한 가족이에요."],"asset":{"type":"mul_groups","item":"🍩","k":4,"n":6,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#5','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',2,'mc','auto','3 × 4 = 12와 한 가족인 식이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":5,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"3 × 4 = 12와 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"12 ÷ 2 = 6","correct":true},{"t":"4 × 3 = 12","mis":"M3-1-u3-X15"},{"t":"12 ÷ 3 = 4","mis":"M3-1-u3-X15"},{"t":"12 ÷ 4 = 3","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 3, 4, 12로 만든 식이에요.","곱셈 2개(3 × 4, 4 × 3), 나눗셈 2개(12 ÷ 3, 12 ÷ 4).","12 ÷ 2 = 6은 다른 수가 들어 있어 한 가족이 아니에요."],"variant_rule":{"alt":[{"stem":"6 × 4 = 24와 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"24 ÷ 3 = 8","correct":true},{"t":"4 × 6 = 24","mis":"M3-1-u3-X15"},{"t":"24 ÷ 6 = 4","mis":"M3-1-u3-X15"},{"t":"24 ÷ 4 = 6","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 6, 4, 24로 만든 식이에요.","곱셈 2개(6 × 4, 4 × 6), 나눗셈 2개(24 ÷ 6, 24 ÷ 4).","24 ÷ 3 = 8은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null},{"stem":"9 × 7 = 63과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"72 ÷ 9 = 8","correct":true},{"t":"7 × 9 = 63","mis":"M3-1-u3-X15"},{"t":"63 ÷ 9 = 7","mis":"M3-1-u3-X15"},{"t":"63 ÷ 7 = 9","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 9, 7, 63으로 만든 식이에요.","곱셈 2개(9 × 7, 7 × 9), 나눗셈 2개(63 ÷ 9, 63 ÷ 7).","72 ÷ 9 = 8은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#6','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',2,'sa','auto','15 ÷ 3 = 5면 □ × 5 = 15예요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u3-C5","difficulty":2,"kind":"sa","stem":"15 ÷ 3 = 5면 □ × 5 = 15예요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["곱셈과 나눗셈은 서로 반대 관계예요.","15 ÷ 3 = 5를 곱셈으로 바꾸면 3 × 5 = 15.","□ × 5 = 15에서 □ = 3이에요."],"variant_rule":{"alt":[{"stem":"36 ÷ 4 = 9면 □ × 9 = 36이에요. □에 알맞은 수를 쓰세요.","answer":["4"],"explanation":["곱셈과 나눗셈은 서로 반대 관계예요.","36 ÷ 4 = 9를 곱셈으로 바꾸면 4 × 9 = 36.","□ × 9 = 36에서 □ = 4예요."],"asset":null},{"stem":"54 ÷ 9 = 6이면 □ × 6 = 54예요. □에 알맞은 수를 쓰세요.","answer":["9"],"explanation":["곱셈과 나눗셈은 서로 반대 관계예요.","54 ÷ 9 = 6을 곱셈으로 바꾸면 9 × 6 = 54.","□ × 6 = 54에서 □ = 9예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#7','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',2,'ox','auto','3 × 4 = 12를 알면 12 ÷ 4 = 3도 바로 알 수 있어요.',ARRAY['M3-1-u3-X08']::text[],true,'{"seq":7,"concept":"M3-1-u3-C5","difficulty":2,"kind":"ox","stem":"3 × 4 = 12를 알면 12 ÷ 4 = 3도 바로 알 수 있어요.","answer":"O","reason_options":[{"t":"같은 세 수로 만든 한 가족 식이라서","correct":true},{"t":"곱셈과 나눗셈은 아무 사이도 아니라서","mis":"M3-1-u3-X08"}],"mis":"M3-1-u3-X08","explanation":["3 × 4 = 12에서 12를 4묶음으로 나누면 한 묶음에 3개예요.","그래서 12 ÷ 4 = 3이에요.","곱셈 하나를 알면 나눗셈 둘을 알 수 있어요."],"variant_rule":{"alt":[{"stem":"9 × 4 = 36을 알면 36 ÷ 4 = 9도 바로 알 수 있어요.","answer":"O","reason_options":[{"t":"같은 세 수로 만든 한 가족 식이라서","correct":true},{"t":"곱셈과 나눗셈은 아무 사이도 아니라서","mis":"M3-1-u3-X08"}],"explanation":["9 × 4 = 36에서 36을 4묶음으로 나누면 한 묶음에 9개예요.","그래서 36 ÷ 4 = 9예요.","곱셈 하나를 알면 나눗셈 둘을 알 수 있어요."],"asset":null},{"stem":"9 × 5 = 45를 알면 45 ÷ 5 = 9도 바로 알 수 있어요.","answer":"O","reason_options":[{"t":"같은 세 수로 만든 한 가족 식이라서","correct":true},{"t":"곱셈과 나눗셈은 아무 사이도 아니라서","mis":"M3-1-u3-X08"}],"explanation":["9 × 5 = 45에서 45를 5묶음으로 나누면 한 묶음에 9개예요.","그래서 45 ÷ 5 = 9예요.","곱셈 하나를 알면 나눗셈 둘을 알 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#8','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',2,'match','auto','곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C5","difficulty":2,"kind":"match","stem":"곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.","pairs":[{"l":"3 × 4 = 12","r":"12 ÷ 3 = 4"},{"l":"2 × 4 = 8","r":"8 ÷ 2 = 4"},{"l":"6 × 5 = 30","r":"30 ÷ 6 = 5"}],"mis":"M3-1-u3-X08","explanation":["곱셈식의 곱이 나눗셈식의 나누어지는 수가 돼요.","세 수가 그대로인 짝을 찾아요.","3 × 4 = 12 ↔ 12 ÷ 3 = 4, 2 × 4 = 8 ↔ 8 ÷ 2 = 4, 6 × 5 = 30 ↔ 30 ÷ 6 = 5."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.","pairs":[{"l":"7 × 6 = 42","r":"42 ÷ 7 = 6"},{"l":"3 × 4 = 12","r":"12 ÷ 3 = 4"},{"l":"5 × 2 = 10","r":"10 ÷ 5 = 2"}],"explanation":["곱셈식의 곱이 나눗셈식의 나누어지는 수가 돼요.","세 수가 그대로인 짝을 찾아요.","7 × 6 = 42 ↔ 42 ÷ 7 = 6, 3 × 4 = 12 ↔ 12 ÷ 3 = 4, 5 × 2 = 10 ↔ 10 ÷ 5 = 2."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.","pairs":[{"l":"9 × 8 = 72","r":"72 ÷ 9 = 8"},{"l":"4 × 2 = 8","r":"8 ÷ 4 = 2"},{"l":"3 × 8 = 24","r":"24 ÷ 3 = 8"}],"explanation":["곱셈식의 곱이 나눗셈식의 나누어지는 수가 돼요.","세 수가 그대로인 짝을 찾아요.","9 × 8 = 72 ↔ 72 ÷ 9 = 8, 4 × 2 = 8 ↔ 8 ÷ 4 = 2, 3 × 8 = 24 ↔ 24 ÷ 3 = 8."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#9','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',2,'mc','auto','당근을 한 줄에 6개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?',ARRAY['M3-1-u3-X09','M3-1-u3-X11','M3-1-u3-X13']::text[],true,'{"seq":9,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"당근을 한 줄에 6개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"6 × 4 = 24","correct":true},{"t":"6 × 5 = 30","mis":"M3-1-u3-X09"},{"t":"6 × 4 = 30","mis":"M3-1-u3-X11"},{"t":"6 + 4 = 10","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 6개씩, 줄은 4줄이에요.","6씩 4줄이니 6 × 4.","6 × 4 = 24 — 모두 24개."],"asset":{"type":"mul_groups","item":"🥕","k":6,"n":4,"look":"rows"},"variant_rule":{"alt":[{"stem":"물고기를 한 줄에 2마리씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 4 = 8","correct":true},{"t":"2 × 5 = 10","mis":"M3-1-u3-X09"},{"t":"2 × 4 = 10","mis":"M3-1-u3-X11"},{"t":"2 + 4 = 6","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2마리씩, 줄은 4줄이에요.","2씩 4줄이니 2 × 4.","2 × 4 = 8 — 모두 8마리."],"asset":{"type":"mul_groups","item":"🐟","k":2,"n":4,"look":"rows"}},{"stem":"사탕을 한 줄에 9개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"9 × 5 = 45","correct":true},{"t":"9 × 6 = 54","mis":"M3-1-u3-X09"},{"t":"9 × 5 = 54","mis":"M3-1-u3-X11"},{"t":"9 + 5 = 14","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 9개씩, 줄은 5줄이에요.","9씩 5줄이니 9 × 5.","9 × 5 = 45 — 모두 45개."],"asset":{"type":"mul_groups","item":"🍬","k":9,"n":5,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_basic#10','math',3,1,'u3','L05','g3_1_math_u3_L05_basic','lesson_basic','M3-1-u3-C5',3,'error','auto','딸기를 한 줄에 4개씩 6줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u3-X08','M3-1-u3-X15']::text[],true,'{"seq":10,"concept":"M3-1-u3-C5","difficulty":3,"kind":"error","stem":"딸기를 한 줄에 4개씩 6줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「24 ÷ 3 = 8도 한 가족이야.」","correct":true,"mis_target":"M3-1-u3-X08"},{"t":"지유 — 「4 × 6 = 24야.」","mis":"M3-1-u3-X15"},{"t":"시우 — 「24 ÷ 4 = 6이야.」","mis":"M3-1-u3-X15"}],"explanation":["배열은 4씩 6줄 — 4 × 6 = 24.","한 가족은 4, 6, 24로 만든 식 4개예요.","은우는 다른 수가 든 식을 한 가족이라고 했어요."],"asset":{"type":"mul_groups","item":"🍓","k":4,"n":6,"look":"rows"},"variant_rule":{"alt":[{"stem":"풍선을 한 줄에 2개씩 3줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"시우 — 「6 ÷ 4 = 2도 한 가족이야.」","correct":true,"mis_target":"M3-1-u3-X08"},{"t":"하랑 — 「2 × 3 = 6이야.」","mis":"M3-1-u3-X15"},{"t":"하린 — 「6 ÷ 2 = 3이야.」","mis":"M3-1-u3-X15"}],"explanation":["배열은 2씩 3줄 — 2 × 3 = 6.","한 가족은 2, 3, 6으로 만든 식 4개예요.","시우는 다른 수가 든 식을 한 가족이라고 했어요."],"asset":{"type":"mul_groups","item":"🎈","k":2,"n":3,"look":"rows"}},{"stem":"별 스티커를 한 줄에 2장씩 4줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은우 — 「8 ÷ 5 = 2도 한 가족이야.」","correct":true,"mis_target":"M3-1-u3-X08"},{"t":"시우 — 「2 × 4 = 8이야.」","mis":"M3-1-u3-X15"},{"t":"도윤 — 「8 ÷ 2 = 4야.」","mis":"M3-1-u3-X15"}],"explanation":["배열은 2씩 4줄 — 2 × 4 = 8.","한 가족은 2, 4, 8로 만든 식 4개예요.","은우는 다른 수가 든 식을 한 가족이라고 했어요."],"asset":{"type":"mul_groups","item":"⭐","k":2,"n":4,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#1','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',2,'sa','auto','쿠키 18개를 한 줄에 6개씩 늘어놓은 그림이에요. 18 ÷ 6 = □에서 □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M3-1-u3-C5","difficulty":2,"kind":"sa","stem":"쿠키 18개를 한 줄에 6개씩 늘어놓은 그림이에요. 18 ÷ 6 = □에서 □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["한 줄에 6개씩이에요.","18을 6개씩 나누면 몇 줄인지 세어요 — 3줄.","18 ÷ 6 = 3 — 6 × 3 = 18과 한 가족이에요."],"asset":{"type":"mul_groups","item":"🍪","k":6,"n":3,"look":"rows"},"variant_rule":{"alt":[{"stem":"딸기 28개를 한 줄에 4개씩 늘어놓은 그림이에요. 28 ÷ 4 = □에서 □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["한 줄에 4개씩이에요.","28을 4개씩 나누면 몇 줄인지 세어요 — 7줄.","28 ÷ 4 = 7 — 4 × 7 = 28과 한 가족이에요."],"asset":{"type":"mul_groups","item":"🍓","k":4,"n":7,"look":"rows"}},{"stem":"풍선 24개를 한 줄에 4개씩 늘어놓은 그림이에요. 24 ÷ 4 = □에서 □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["한 줄에 4개씩이에요.","24를 4개씩 나누면 몇 줄인지 세어요 — 6줄.","24 ÷ 4 = 6 — 4 × 6 = 24와 한 가족이에요."],"asset":{"type":"mul_groups","item":"🎈","k":4,"n":6,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#2','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',2,'sa','auto','42 ÷ 6 = 7이면 □ × 7 = 42예요. □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C5","difficulty":2,"kind":"sa","stem":"42 ÷ 6 = 7이면 □ × 7 = 42예요. □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["곱셈과 나눗셈은 서로 반대 관계예요.","42 ÷ 6 = 7을 곱셈으로 바꾸면 6 × 7 = 42.","□ × 7 = 42에서 □ = 6이에요."],"variant_rule":{"alt":[{"stem":"24 ÷ 3 = 8이면 □ × 8 = 24예요. □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["곱셈과 나눗셈은 서로 반대 관계예요.","24 ÷ 3 = 8을 곱셈으로 바꾸면 3 × 8 = 24.","□ × 8 = 24에서 □ = 3이에요."],"asset":null},{"stem":"56 ÷ 7 = 8이면 □ × 8 = 56이에요. □에 알맞은 수를 쓰세요.","answer":["7"],"explanation":["곱셈과 나눗셈은 서로 반대 관계예요.","56 ÷ 7 = 8을 곱셈으로 바꾸면 7 × 8 = 56.","□ × 8 = 56에서 □ = 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#3','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',3,'error','auto','컵케이크를 한 줄에 3개씩 4줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u3-X08','M3-1-u3-X15']::text[],true,'{"seq":3,"concept":"M3-1-u3-C5","difficulty":3,"kind":"error","stem":"컵케이크를 한 줄에 3개씩 4줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하랑 — 「12 ÷ 2 = 6도 한 가족이야.」","correct":true,"mis_target":"M3-1-u3-X08"},{"t":"태오 — 「3 × 4 = 12야.」","mis":"M3-1-u3-X15"},{"t":"서윤 — 「12 ÷ 3 = 4야.」","mis":"M3-1-u3-X15"}],"explanation":["배열은 3씩 4줄 — 3 × 4 = 12.","한 가족은 3, 4, 12로 만든 식 4개예요.","하랑은 다른 수가 든 식을 한 가족이라고 했어요."],"asset":{"type":"mul_groups","item":"🧁","k":3,"n":4,"look":"rows"},"variant_rule":{"alt":[{"stem":"도넛을 한 줄에 5개씩 3줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「15 ÷ 4 = 5도 한 가족이야.」","correct":true,"mis_target":"M3-1-u3-X08"},{"t":"은우 — 「5 × 3 = 15야.」","mis":"M3-1-u3-X15"},{"t":"하린 — 「15 ÷ 5 = 3이야.」","mis":"M3-1-u3-X15"}],"explanation":["배열은 5씩 3줄 — 5 × 3 = 15.","한 가족은 5, 3, 15로 만든 식 4개예요.","서윤은 다른 수가 든 식을 한 가족이라고 했어요."],"asset":{"type":"mul_groups","item":"🍩","k":5,"n":3,"look":"rows"}},{"stem":"사과를 한 줄에 3개씩 9줄로 늘어놓았어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「27 ÷ 10 = 3도 한 가족이야.」","correct":true,"mis_target":"M3-1-u3-X08"},{"t":"지유 — 「3 × 9 = 27이야.」","mis":"M3-1-u3-X15"},{"t":"시우 — 「27 ÷ 3 = 9야.」","mis":"M3-1-u3-X15"}],"explanation":["배열은 3씩 9줄 — 3 × 9 = 27.","한 가족은 3, 9, 27로 만든 식 4개예요.","하린은 다른 수가 든 식을 한 가족이라고 했어요."],"asset":{"type":"mul_groups","item":"🍎","k":3,"n":9,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#4','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',3,'mc','auto','6 × 3 = 18과 한 가족인 식이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":4,"concept":"M3-1-u3-C5","difficulty":3,"kind":"mc","stem":"6 × 3 = 18과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"18 ÷ 2 = 9","correct":true},{"t":"3 × 6 = 18","mis":"M3-1-u3-X15"},{"t":"18 ÷ 6 = 3","mis":"M3-1-u3-X15"},{"t":"18 ÷ 3 = 6","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 6, 3, 18로 만든 식이에요.","곱셈 2개(6 × 3, 3 × 6), 나눗셈 2개(18 ÷ 6, 18 ÷ 3).","18 ÷ 2 = 9는 다른 수가 들어 있어 한 가족이 아니에요."],"variant_rule":{"alt":[{"stem":"5 × 6 = 30과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"35 ÷ 5 = 7","correct":true},{"t":"6 × 5 = 30","mis":"M3-1-u3-X15"},{"t":"30 ÷ 5 = 6","mis":"M3-1-u3-X15"},{"t":"30 ÷ 6 = 5","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 5, 6, 30으로 만든 식이에요.","곱셈 2개(5 × 6, 6 × 5), 나눗셈 2개(30 ÷ 5, 30 ÷ 6).","35 ÷ 5 = 7은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null},{"stem":"2 × 5 = 10과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"12 ÷ 2 = 6","correct":true},{"t":"5 × 2 = 10","mis":"M3-1-u3-X15"},{"t":"10 ÷ 2 = 5","mis":"M3-1-u3-X15"},{"t":"10 ÷ 5 = 2","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 2, 5, 10으로 만든 식이에요.","곱셈 2개(2 × 5, 5 × 2), 나눗셈 2개(10 ÷ 2, 10 ÷ 5).","12 ÷ 2 = 6은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#5','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',3,'mc','auto','7 × 8 = 56을 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X08']::text[],true,'{"seq":5,"concept":"M3-1-u3-C5","difficulty":3,"kind":"mc","stem":"7 × 8 = 56을 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"56 ÷ 7 = 8","correct":true},{"t":"7 ÷ 56 = 8","mis":"M3-1-u3-X05"},{"t":"56 ÷ 7 = 49","mis":"M3-1-u3-X08"},{"t":"56 ÷ 8 = 8","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 7 × 8 = 56에서 곱 56이 나누어지는 수가 돼요.","56을 7로 나누면 8 — 56 ÷ 7 = 8.","같은 세 수 7, 8, 56만 써요."],"variant_rule":{"alt":[{"stem":"3 × 5 = 15를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"15 ÷ 3 = 5","correct":true},{"t":"3 ÷ 15 = 5","mis":"M3-1-u3-X05"},{"t":"15 ÷ 3 = 12","mis":"M3-1-u3-X08"},{"t":"15 ÷ 4 = 5","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 3 × 5 = 15에서 곱 15가 나누어지는 수가 돼요.","15를 3으로 나누면 5 — 15 ÷ 3 = 5.","같은 세 수 3, 5, 15만 써요."],"asset":null},{"stem":"5 × 4 = 20을 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"20 ÷ 5 = 4","correct":true},{"t":"5 ÷ 20 = 4","mis":"M3-1-u3-X05"},{"t":"20 ÷ 5 = 15","mis":"M3-1-u3-X08"},{"t":"20 ÷ 6 = 4","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 5 × 4 = 20에서 곱 20이 나누어지는 수가 돼요.","20을 5로 나누면 4 — 20 ÷ 5 = 4.","같은 세 수 5, 4, 20만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#6','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',3,'mc','auto','54 ÷ 9 = 6을 곱셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X08','M3-1-u3-X07']::text[],true,'{"seq":6,"concept":"M3-1-u3-C5","difficulty":3,"kind":"mc","stem":"54 ÷ 9 = 6을 곱셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"9 × 6 = 54","correct":true},{"t":"54 × 9 = 6","mis":"M3-1-u3-X08"},{"t":"9 × 6 = 15","mis":"M3-1-u3-X07"},{"t":"9 × 9 = 81","mis":"M3-1-u3-X08"}],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","9 × 6 = 54예요.","54, 9, 6 — 같은 세 수가 한 가족이에요."],"variant_rule":{"alt":[{"stem":"15 ÷ 3 = 5를 곱셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"3 × 5 = 15","correct":true},{"t":"15 × 3 = 5","mis":"M3-1-u3-X08"},{"t":"3 × 5 = 8","mis":"M3-1-u3-X07"},{"t":"3 × 3 = 9","mis":"M3-1-u3-X08"}],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","3 × 5 = 15예요.","15, 3, 5 — 같은 세 수가 한 가족이에요."],"asset":null},{"stem":"10 ÷ 2 = 5를 곱셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"2 × 5 = 10","correct":true},{"t":"10 × 2 = 5","mis":"M3-1-u3-X08"},{"t":"2 × 5 = 7","mis":"M3-1-u3-X07"},{"t":"2 × 2 = 4","mis":"M3-1-u3-X08"}],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","2 × 5 = 10이에요.","10, 2, 5 — 같은 세 수가 한 가족이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#7','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',3,'match','auto','곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u3-C5","difficulty":3,"kind":"match","stem":"곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.","pairs":[{"l":"7 × 6 = 42","r":"42 ÷ 7 = 6"},{"l":"5 × 3 = 15","r":"15 ÷ 5 = 3"},{"l":"8 × 6 = 48","r":"48 ÷ 8 = 6"}],"mis":"M3-1-u3-X08","explanation":["곱셈식의 곱이 나눗셈식의 나누어지는 수가 돼요.","세 수가 그대로인 짝을 찾아요.","7 × 6 = 42 ↔ 42 ÷ 7 = 6, 5 × 3 = 15 ↔ 15 ÷ 5 = 3, 8 × 6 = 48 ↔ 48 ÷ 8 = 6."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.","pairs":[{"l":"5 × 9 = 45","r":"45 ÷ 5 = 9"},{"l":"9 × 4 = 36","r":"36 ÷ 9 = 4"},{"l":"7 × 9 = 63","r":"63 ÷ 7 = 9"}],"explanation":["곱셈식의 곱이 나눗셈식의 나누어지는 수가 돼요.","세 수가 그대로인 짝을 찾아요.","5 × 9 = 45 ↔ 45 ÷ 5 = 9, 9 × 4 = 36 ↔ 36 ÷ 9 = 4, 7 × 9 = 63 ↔ 63 ÷ 7 = 9."],"asset":null},{"stem":"이번에는 다른 수예요. 곱셈식과 같은 가족인 나눗셈식을 알맞게 이으세요.","pairs":[{"l":"7 × 3 = 21","r":"21 ÷ 7 = 3"},{"l":"8 × 4 = 32","r":"32 ÷ 8 = 4"},{"l":"9 × 2 = 18","r":"18 ÷ 9 = 2"}],"explanation":["곱셈식의 곱이 나눗셈식의 나누어지는 수가 돼요.","세 수가 그대로인 짝을 찾아요.","7 × 3 = 21 ↔ 21 ÷ 7 = 3, 8 × 4 = 32 ↔ 32 ÷ 8 = 4, 9 × 2 = 18 ↔ 18 ÷ 9 = 2."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#8','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',4,'essay','teacher','사과를 한 줄에 4개씩 3줄로 늘어놓았어요. 이 배열을 보고 곱셈식 2개와 나눗셈식 2개를 쓰고, 네 식이 한 가족인 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u3-C5","difficulty":4,"kind":"essay","stem":"사과를 한 줄에 4개씩 3줄로 늘어놓았어요. 이 배열을 보고 곱셈식 2개와 나눗셈식 2개를 쓰고, 네 식이 한 가족인 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 4 × 3 = 12, 3 × 4 = 12, 12 ÷ 4 = 3, 12 ÷ 3 = 4. 네 식 모두 같은 세 수 3, 4, 12로 만들었고, 한 배열을 가로로 보거나 세로로 보거나 나누어 본 것이라 한 가족이다.","scoring_points":["곱셈식 2개를 바르게 썼는가","나눗셈식 2개를 바르게 썼는가","같은 세 수·같은 배열이라 한 가족이라고 썼는가"]},"explanation":["곱셈 4 × 3, 3 × 4.","나눗셈 12 ÷ 4, 12 ÷ 3.","세 수 3, 4, 12로 만든 한 가족이에요."],"asset":{"type":"mul_groups","item":"🍎","k":4,"n":3,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#9','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',4,'essay','teacher','5 × 6 = 30을 알면 30 ÷ 5와 30 ÷ 6의 몫을 바로 알 수 있는 까닭을 곱셈과 나눗셈의 관계로 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u3-C5","difficulty":4,"kind":"essay","stem":"5 × 6 = 30을 알면 30 ÷ 5와 30 ÷ 6의 몫을 바로 알 수 있는 까닭을 곱셈과 나눗셈의 관계로 설명해 보세요.","answer_guide":{"answer":"예: 5 × 6 = 30은 5씩 6묶음이 30이라는 뜻이다. 그래서 30을 5씩 덜어 내면 6묶음(30 ÷ 5 = 6)이고, 30을 6묶음으로 똑같이 나누면 한 묶음에 5(30 ÷ 6 = 5)이다. 곱셈과 나눗셈은 서로 반대 관계라 곱셈 하나로 나눗셈 둘을 알 수 있다.","scoring_points":["30 ÷ 5 = 6을 썼는가","30 ÷ 6 = 5를 썼는가","곱셈과 나눗셈이 반대 관계(한 가족)라고 설명했는가"]},"explanation":["5씩 6묶음 = 30.","30 ÷ 5 = 6, 30 ÷ 6 = 5.","곱셈과 나눗셈은 반대 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L05_challenge#10','math',3,1,'u3','L05','g3_1_math_u3_L05_challenge','lesson_challenge','M3-1-u3-C5',4,'sa','auto','어떤 수를 4로 나누었더니 몫이 7이 되었어요. 어떤 수를 7로 나누면 몫은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u3-C5","difficulty":4,"kind":"sa","stem":"어떤 수를 4로 나누었더니 몫이 7이 되었어요. 어떤 수를 7로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["어떤 수 = 나누는 수 × 몫 = 4 × 7 = 28이에요.","28 ÷ 7은 같은 가족 식이에요.","28 ÷ 7 = 4예요."],"variant_rule":{"alt":[{"stem":"어떤 수를 8로 나누었더니 몫이 9가 되었어요. 어떤 수를 9로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["어떤 수 = 나누는 수 × 몫 = 8 × 9 = 72예요.","72 ÷ 9는 같은 가족 식이에요.","72 ÷ 9 = 8이에요."],"asset":null},{"stem":"어떤 수를 7로 나누었더니 몫이 8이 되었어요. 어떤 수를 8로 나누면 몫은 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["어떤 수 = 나누는 수 × 몫 = 7 × 8 = 56이에요.","56 ÷ 8은 같은 가족 식이에요.","56 ÷ 8 = 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#1','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',1,'mc','auto','12 ÷ 3의 몫을 구하려고 해요. 알맞은 곱셈식은 어느 것인가요?',ARRAY['M3-1-u3-X10']::text[],true,'{"seq":1,"concept":"M3-1-u3-C6","difficulty":1,"kind":"mc","stem":"12 ÷ 3의 몫을 구하려고 해요. 알맞은 곱셈식은 어느 것인가요?","options":[{"t":"3 × □ = 12","correct":true},{"t":"12 × □ = 3","mis":"M3-1-u3-X10"},{"t":"□ × 12 = 3","mis":"M3-1-u3-X10"},{"t":"3 × 12 = □","mis":"M3-1-u3-X10"}],"explanation":["나누는 수 3의 단에서 12를 찾아요.","3 × □ = 12 — □가 몫이에요.","3 × 4 = 12라 몫은 4예요."],"variant_rule":{"alt":[{"stem":"18 ÷ 6의 몫을 구하려고 해요. 알맞은 곱셈식은 어느 것인가요?","options":[{"t":"6 × □ = 18","correct":true},{"t":"18 × □ = 6","mis":"M3-1-u3-X10"},{"t":"□ × 18 = 6","mis":"M3-1-u3-X10"},{"t":"6 × 18 = □","mis":"M3-1-u3-X10"}],"explanation":["나누는 수 6의 단에서 18을 찾아요.","6 × □ = 18 — □가 몫이에요.","6 × 3 = 18이라 몫은 3이에요."],"asset":null},{"stem":"14 ÷ 7의 몫을 구하려고 해요. 알맞은 곱셈식은 어느 것인가요?","options":[{"t":"7 × □ = 14","correct":true},{"t":"14 × □ = 7","mis":"M3-1-u3-X10"},{"t":"□ × 14 = 7","mis":"M3-1-u3-X10"},{"t":"7 × 14 = □","mis":"M3-1-u3-X10"}],"explanation":["나누는 수 7의 단에서 14를 찾아요.","7 × □ = 14 — □가 몫이에요.","7 × 2 = 14라 몫은 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#2','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',1,'sa','auto','곱셈구구를 이용해 20 ÷ 5의 몫을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C6","difficulty":1,"kind":"sa","stem":"곱셈구구를 이용해 20 ÷ 5의 몫을 구하세요. 숫자로 쓰세요.","answer":["4"],"explanation":["5 × □ = 20이 되는 □를 찾아요.","5단: … 5 × 4 = 20.","그래서 20 ÷ 5 = 4예요."],"variant_rule":{"alt":[{"stem":"곱셈구구를 이용해 24 ÷ 3의 몫을 구하세요. 숫자로 쓰세요.","answer":["8"],"explanation":["3 × □ = 24가 되는 □를 찾아요.","3단: … 3 × 8 = 24.","그래서 24 ÷ 3 = 8이에요."],"asset":null},{"stem":"곱셈구구를 이용해 56 ÷ 8의 몫을 구하세요. 숫자로 쓰세요.","answer":["7"],"explanation":["8 × □ = 56이 되는 □를 찾아요.","8단: … 8 × 7 = 56.","그래서 56 ÷ 8 = 7이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#3','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',1,'sa','auto','곱셈표에서 색칠한 4단을 보고 24 ÷ 4의 몫을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C6","difficulty":1,"kind":"sa","stem":"곱셈표에서 색칠한 4단을 보고 24 ÷ 4의 몫을 구하세요. 숫자로 쓰세요.","answer":["6"],"explanation":["색칠한 4단에서 24를 찾아요.","24는 위쪽 6과 만나는 칸이에요 — 4 × 6 = 24.","그래서 몫은 6이에요."],"asset":{"type":"gugu_table","rows":[3,4,5],"cols":[1,2,3,4,5,6,7,8,9],"hrow":4},"variant_rule":{"alt":[{"stem":"곱셈표에서 색칠한 4단을 보고 12 ÷ 4의 몫을 구하세요. 숫자로 쓰세요.","answer":["3"],"explanation":["색칠한 4단에서 12를 찾아요.","12는 위쪽 3과 만나는 칸이에요 — 4 × 3 = 12.","그래서 몫은 3이에요."],"asset":{"type":"gugu_table","rows":[3,4,5],"cols":[1,2,3,4,5,6,7,8,9],"hrow":4}},{"stem":"곱셈표에서 색칠한 3단을 보고 21 ÷ 3의 몫을 구하세요. 숫자로 쓰세요.","answer":["7"],"explanation":["색칠한 3단에서 21을 찾아요.","21은 위쪽 7과 만나는 칸이에요 — 3 × 7 = 21.","그래서 몫은 7이에요."],"asset":{"type":"gugu_table","rows":[2,3,4],"cols":[1,2,3,4,5,6,7,8,9],"hrow":3}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#4','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',1,'mc','auto','12 ÷ 3 = 4가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M3-1-u3-X12','M3-1-u3-X13']::text[],true,'{"seq":4,"concept":"M3-1-u3-C6","difficulty":1,"kind":"mc","stem":"12 ÷ 3 = 4가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"3 × 4 = 12","correct":true},{"t":"4 × 12 = □","mis":"M3-1-u3-X12"},{"t":"12 × 3 = □","mis":"M3-1-u3-X12"},{"t":"3 + 4 = 7","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","3 × 4 = 12예요.","그래서 12 ÷ 3 = 4는 맞아요."],"variant_rule":{"alt":[{"stem":"30 ÷ 5 = 6이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"5 × 6 = 30","correct":true},{"t":"6 × 30 = □","mis":"M3-1-u3-X12"},{"t":"30 × 5 = □","mis":"M3-1-u3-X12"},{"t":"5 + 6 = 11","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","5 × 6 = 30이에요.","그래서 30 ÷ 5 = 6은 맞아요."],"asset":null},{"stem":"72 ÷ 9 = 8이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"9 × 8 = 72","correct":true},{"t":"8 × 72 = □","mis":"M3-1-u3-X12"},{"t":"72 × 9 = □","mis":"M3-1-u3-X12"},{"t":"9 + 8 = 17","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","9 × 8 = 72예요.","그래서 72 ÷ 9 = 8은 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#5','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',2,'mc','auto','곱셈구구를 이용해 18 ÷ 6의 몫을 구하면 얼마인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":5,"concept":"M3-1-u3-C6","difficulty":2,"kind":"mc","stem":"곱셈구구를 이용해 18 ÷ 6의 몫을 구하면 얼마인가요?","options":[{"t":"3","correct":true},{"t":"6","mis":"M3-1-u3-X02"},{"t":"12","mis":"M3-1-u3-X07"},{"t":"4","mis":"M3-1-u3-X11"}],"explanation":["6 × □ = 18이 되는 □를 찾아요.","6단: … 6 × 3 = 18.","그래서 18 ÷ 6 = 3이에요."],"variant_rule":{"alt":[{"stem":"곱셈구구를 이용해 35 ÷ 7의 몫을 구하면 얼마인가요?","options":[{"t":"5","correct":true},{"t":"7","mis":"M3-1-u3-X02"},{"t":"28","mis":"M3-1-u3-X07"},{"t":"6","mis":"M3-1-u3-X11"}],"explanation":["7 × □ = 35가 되는 □를 찾아요.","7단: … 7 × 5 = 35.","그래서 35 ÷ 7 = 5예요."],"asset":null},{"stem":"곱셈구구를 이용해 56 ÷ 7의 몫을 구하면 얼마인가요?","options":[{"t":"8","correct":true},{"t":"7","mis":"M3-1-u3-X02"},{"t":"49","mis":"M3-1-u3-X07"},{"t":"9","mis":"M3-1-u3-X11"}],"explanation":["7 × □ = 56이 되는 □를 찾아요.","7단: … 7 × 8 = 56.","그래서 56 ÷ 7 = 8이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#6','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',2,'sa','auto','□ ÷ 4 = 6 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u3-C6","difficulty":2,"kind":"sa","stem":"□ ÷ 4 = 6 — □에 알맞은 수를 쓰세요.","answer":["24"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 6 = 24예요.","□ = 24 — 24 ÷ 4 = 6으로 확인해요."],"variant_rule":{"alt":[{"stem":"□ ÷ 7 = 8 — □에 알맞은 수를 쓰세요.","answer":["56"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","7 × 8 = 56이에요.","□ = 56 — 56 ÷ 7 = 8로 확인해요."],"asset":null},{"stem":"□ ÷ 7 = 6 — □에 알맞은 수를 쓰세요.","answer":["42"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","7 × 6 = 42예요.","□ = 42 — 42 ÷ 7 = 6으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#7','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',2,'ox','auto','12 ÷ 3 = 4가 맞는지 4 × 12로 곱해 확인했어요. 바르게 확인한 거예요.',ARRAY['M3-1-u3-X12']::text[],true,'{"seq":7,"concept":"M3-1-u3-C6","difficulty":2,"kind":"ox","stem":"12 ÷ 3 = 4가 맞는지 4 × 12로 곱해 확인했어요. 바르게 확인한 거예요.","answer":"X","reason_options":[{"t":"나누는 수와 몫을 곱해야 해서","correct":true},{"t":"몫과 나누어지는 수를 곱하면 되어서","mis":"M3-1-u3-X12"}],"mis":"M3-1-u3-X12","explanation":["확인은 나누는 수 × 몫으로 해요.","3 × 4 = 12예요.","4 × 12는 확인하는 식이 아니에요."],"variant_rule":{"alt":[{"stem":"12 ÷ 2 = 6이 맞는지 6 × 12로 곱해 확인했어요. 바르게 확인한 거예요.","answer":"X","reason_options":[{"t":"나누는 수와 몫을 곱해야 해서","correct":true},{"t":"몫과 나누어지는 수를 곱하면 되어서","mis":"M3-1-u3-X12"}],"explanation":["확인은 나누는 수 × 몫으로 해요.","2 × 6 = 12예요.","6 × 12는 확인하는 식이 아니에요."],"asset":null},{"stem":"45 ÷ 9 = 5가 맞는지 5 × 45로 곱해 확인했어요. 바르게 확인한 거예요.","answer":"X","reason_options":[{"t":"나누는 수와 몫을 곱해야 해서","correct":true},{"t":"몫과 나누어지는 수를 곱하면 되어서","mis":"M3-1-u3-X12"}],"explanation":["확인은 나누는 수 × 몫으로 해요.","9 × 5 = 45예요.","5 × 45는 확인하는 식이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#8','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',2,'match','auto','나눗셈식과 몫을 알맞게 이으세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C6","difficulty":2,"kind":"match","stem":"나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"16 ÷ 4","r":"4"},{"l":"40 ÷ 8","r":"5"},{"l":"10 ÷ 5","r":"2"}],"mis":"M3-1-u3-X11","explanation":["나누는 수의 단에서 나누어지는 수를 찾아요.","4 × 4 = 16, 8 × 5 = 40, 5 × 2 = 10.","그래서 몫은 차례로 4, 5, 2."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"30 ÷ 5","r":"6"},{"l":"28 ÷ 7","r":"4"},{"l":"14 ÷ 2","r":"7"}],"explanation":["나누는 수의 단에서 나누어지는 수를 찾아요.","5 × 6 = 30, 7 × 4 = 28, 2 × 7 = 14.","그래서 몫은 차례로 6, 4, 7."],"asset":null},{"stem":"이번에는 다른 수예요. 나눗셈식과 몫을 알맞게 이으세요.","pairs":[{"l":"28 ÷ 4","r":"7"},{"l":"20 ÷ 4","r":"5"},{"l":"24 ÷ 6","r":"4"}],"explanation":["나누는 수의 단에서 나누어지는 수를 찾아요.","4 × 7 = 28, 4 × 5 = 20, 6 × 4 = 24.","그래서 몫은 차례로 7, 5, 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#9','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',2,'sa','auto','24 ÷ □ = 4 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u3-C6","difficulty":2,"kind":"sa","stem":"24 ÷ □ = 4 — □에 알맞은 수를 쓰세요.","answer":["6"],"explanation":["□ × 4 = 24가 되는 □를 찾아요.","6 × 4 = 24예요.","□ = 6 — 24 ÷ 6 = 4."],"variant_rule":{"alt":[{"stem":"35 ÷ □ = 7 — □에 알맞은 수를 쓰세요.","answer":["5"],"explanation":["□ × 7 = 35가 되는 □를 찾아요.","5 × 7 = 35예요.","□ = 5 — 35 ÷ 5 = 7."],"asset":null},{"stem":"8 ÷ □ = 4 — □에 알맞은 수를 쓰세요.","answer":["2"],"explanation":["□ × 4 = 8이 되는 □를 찾아요.","2 × 4 = 8이에요.","□ = 2 — 8 ÷ 2 = 4."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_basic#10','math',3,1,'u3','L06','g3_1_math_u3_L06_basic','lesson_basic','M3-1-u3-C6',3,'mc','auto','두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 28 ÷ 7 ○ 42 ÷ 7',ARRAY['M3-1-u3-X11','M3-1-u3-X15']::text[],true,'{"seq":10,"concept":"M3-1-u3-C6","difficulty":3,"kind":"mc","stem":"두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 28 ÷ 7 ○ 42 ÷ 7","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u3-X11"},{"t":"=","mis":"M3-1-u3-X11"},{"t":"알 수 없다","mis":"M3-1-u3-X15"}],"explanation":["28 ÷ 7 = 4예요.","42 ÷ 7 = 6이에요.","4 < 6 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 32 ÷ 4 ○ 63 ÷ 7","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u3-X11"},{"t":"=","mis":"M3-1-u3-X11"},{"t":"알 수 없다","mis":"M3-1-u3-X15"}],"explanation":["32 ÷ 4 = 8이에요.","63 ÷ 7 = 9예요.","8 < 9 — 알맞은 것은 <예요."],"asset":null},{"stem":"두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 63 ÷ 9 ○ 32 ÷ 8","options":[{"t":">","correct":true},{"t":"<","mis":"M3-1-u3-X11"},{"t":"=","mis":"M3-1-u3-X11"},{"t":"알 수 없다","mis":"M3-1-u3-X15"}],"explanation":["63 ÷ 9 = 7이에요.","32 ÷ 8 = 4예요.","7 > 4 — 알맞은 것은 >예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#1','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',2,'mc','auto','곱셈구구를 이용해 56 ÷ 8의 몫을 구하면 얼마인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":1,"concept":"M3-1-u3-C6","difficulty":2,"kind":"mc","stem":"곱셈구구를 이용해 56 ÷ 8의 몫을 구하면 얼마인가요?","options":[{"t":"7","correct":true},{"t":"8","mis":"M3-1-u3-X02"},{"t":"48","mis":"M3-1-u3-X07"},{"t":"6","mis":"M3-1-u3-X11"}],"explanation":["8 × □ = 56이 되는 □를 찾아요.","8단: … 8 × 7 = 56.","그래서 56 ÷ 8 = 7이에요."],"variant_rule":{"alt":[{"stem":"곱셈구구를 이용해 42 ÷ 7의 몫을 구하면 얼마인가요?","options":[{"t":"6","correct":true},{"t":"7","mis":"M3-1-u3-X02"},{"t":"35","mis":"M3-1-u3-X07"},{"t":"5","mis":"M3-1-u3-X11"}],"explanation":["7 × □ = 42가 되는 □를 찾아요.","7단: … 7 × 6 = 42.","그래서 42 ÷ 7 = 6이에요."],"asset":null},{"stem":"곱셈구구를 이용해 18 ÷ 9의 몫을 구하면 얼마인가요?","options":[{"t":"2","correct":true},{"t":"9","mis":"M3-1-u3-X02"},{"t":"3","mis":"M3-1-u3-X11"},{"t":"1","mis":"M3-1-u3-X11"}],"explanation":["9 × □ = 18이 되는 □를 찾아요.","9단: … 9 × 2 = 18.","그래서 18 ÷ 9 = 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#2','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',2,'sa','auto','곱셈표에서 색칠한 7단을 보고 56 ÷ 7의 몫을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C6","difficulty":2,"kind":"sa","stem":"곱셈표에서 색칠한 7단을 보고 56 ÷ 7의 몫을 구하세요. 숫자로 쓰세요.","answer":["8"],"explanation":["색칠한 7단에서 56을 찾아요.","56은 위쪽 8과 만나는 칸이에요 — 7 × 8 = 56.","그래서 몫은 8이에요."],"asset":{"type":"gugu_table","rows":[6,7,8],"cols":[1,2,3,4,5,6,7,8,9],"hrow":7},"variant_rule":{"alt":[{"stem":"곱셈표에서 색칠한 8단을 보고 72 ÷ 8의 몫을 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["색칠한 8단에서 72를 찾아요.","72는 위쪽 9와 만나는 칸이에요 — 8 × 9 = 72.","그래서 몫은 9예요."],"asset":{"type":"gugu_table","rows":[7,8,9],"cols":[1,2,3,4,5,6,7,8,9],"hrow":8}},{"stem":"곱셈표에서 색칠한 7단을 보고 14 ÷ 7의 몫을 구하세요. 숫자로 쓰세요.","answer":["2"],"explanation":["색칠한 7단에서 14를 찾아요.","14는 위쪽 2와 만나는 칸이에요 — 7 × 2 = 14.","그래서 몫은 2예요."],"asset":{"type":"gugu_table","rows":[6,7,8],"cols":[1,2,3,4,5,6,7,8,9],"hrow":7}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#3','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',3,'error','auto','20 ÷ 4의 몫을 구하고 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M3-1-u3-X10','M3-1-u3-X15']::text[],true,'{"seq":3,"concept":"M3-1-u3-C6","difficulty":3,"kind":"error","stem":"20 ÷ 4의 몫을 구하고 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지유 — 「20 × □ = 4에서 □를 찾아.」","correct":true,"mis_target":"M3-1-u3-X10"},{"t":"서윤 — 「4 × □ = 20에서 □가 몫이야.」","mis":"M3-1-u3-X15"},{"t":"도윤 — 「4 × 5 = 20이니까 몫은 5야.」","mis":"M3-1-u3-X15"}],"explanation":["몫은 나누는 수 4의 단에서 찾아요.","4 × 5 = 20 — 몫은 5예요.","지유는 나누어지는 수 20의 단에서 찾으려 했어요 — 20 × □는 4가 될 수 없어요."],"variant_rule":{"alt":[{"stem":"54 ÷ 6의 몫을 구하고 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서윤 — 「54 × □ = 6에서 □를 찾아.」","correct":true,"mis_target":"M3-1-u3-X10"},{"t":"은우 — 「6 × □ = 54에서 □가 몫이야.」","mis":"M3-1-u3-X15"},{"t":"시우 — 「6 × 9 = 54니까 몫은 9야.」","mis":"M3-1-u3-X15"}],"explanation":["몫은 나누는 수 6의 단에서 찾아요.","6 × 9 = 54 — 몫은 9예요.","서윤은 나누어지는 수 54의 단에서 찾으려 했어요 — 54 × □는 6이 될 수 없어요."],"asset":null},{"stem":"18 ÷ 2의 몫을 구하고 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태오 — 「18 × □ = 2에서 □를 찾아.」","correct":true,"mis_target":"M3-1-u3-X10"},{"t":"지유 — 「2 × □ = 18에서 □가 몫이야.」","mis":"M3-1-u3-X15"},{"t":"은우 — 「2 × 9 = 18이니까 몫은 9야.」","mis":"M3-1-u3-X15"}],"explanation":["몫은 나누는 수 2의 단에서 찾아요.","2 × 9 = 18 — 몫은 9예요.","태오는 나누어지는 수 18의 단에서 찾으려 했어요 — 18 × □는 2가 될 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#4','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',3,'mc','auto','두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 54 ÷ 9 ○ 32 ÷ 4',ARRAY['M3-1-u3-X11','M3-1-u3-X15']::text[],true,'{"seq":4,"concept":"M3-1-u3-C6","difficulty":3,"kind":"mc","stem":"두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 54 ÷ 9 ○ 32 ÷ 4","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u3-X11"},{"t":"=","mis":"M3-1-u3-X11"},{"t":"알 수 없다","mis":"M3-1-u3-X15"}],"explanation":["54 ÷ 9 = 6이에요.","32 ÷ 4 = 8이에요.","6 < 8 — 알맞은 것은 <예요."],"variant_rule":{"alt":[{"stem":"두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 36 ÷ 9 ○ 35 ÷ 5","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u3-X11"},{"t":"=","mis":"M3-1-u3-X11"},{"t":"알 수 없다","mis":"M3-1-u3-X15"}],"explanation":["36 ÷ 9 = 4예요.","35 ÷ 5 = 7이에요.","4 < 7 — 알맞은 것은 <예요."],"asset":null},{"stem":"두 식의 몫을 견주어 ○ 안에 알맞은 것을 고르세요. 15 ÷ 5 ○ 15 ÷ 3","options":[{"t":"<","correct":true},{"t":">","mis":"M3-1-u3-X11"},{"t":"=","mis":"M3-1-u3-X11"},{"t":"알 수 없다","mis":"M3-1-u3-X15"}],"explanation":["15 ÷ 5 = 3이에요.","15 ÷ 3 = 5예요.","3 < 5 — 알맞은 것은 <예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#5','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',3,'sa','auto','48 ÷ □ = 6 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C6","difficulty":3,"kind":"sa","stem":"48 ÷ □ = 6 — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["□ × 6 = 48이 되는 □를 찾아요.","8 × 6 = 48이에요.","□ = 8 — 48 ÷ 8 = 6."],"variant_rule":{"alt":[{"stem":"32 ÷ □ = 4 — □에 알맞은 수를 쓰세요.","answer":["8"],"explanation":["□ × 4 = 32가 되는 □를 찾아요.","8 × 4 = 32예요.","□ = 8 — 32 ÷ 8 = 4."],"asset":null},{"stem":"15 ÷ □ = 5 — □에 알맞은 수를 쓰세요.","answer":["3"],"explanation":["□ × 5 = 15가 되는 □를 찾아요.","3 × 5 = 15예요.","□ = 3 — 15 ÷ 3 = 5."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#6','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',3,'sa','auto','□ ÷ 9 = 7 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M3-1-u3-C6","difficulty":3,"kind":"sa","stem":"□ ÷ 9 = 7 — □에 알맞은 수를 쓰세요.","answer":["63"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","9 × 7 = 63이에요.","□ = 63 — 63 ÷ 9 = 7로 확인해요."],"variant_rule":{"alt":[{"stem":"□ ÷ 4 = 9 — □에 알맞은 수를 쓰세요.","answer":["36"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 9 = 36이에요.","□ = 36 — 36 ÷ 4 = 9로 확인해요."],"asset":null},{"stem":"□ ÷ 4 = 6 — □에 알맞은 수를 쓰세요.","answer":["24"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 6 = 24예요.","□ = 24 — 24 ÷ 4 = 6으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#7','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',3,'mc','auto','42 ÷ 7 = 6이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M3-1-u3-X12','M3-1-u3-X13']::text[],true,'{"seq":7,"concept":"M3-1-u3-C6","difficulty":3,"kind":"mc","stem":"42 ÷ 7 = 6이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"7 × 6 = 42","correct":true},{"t":"6 × 42 = □","mis":"M3-1-u3-X12"},{"t":"42 × 7 = □","mis":"M3-1-u3-X12"},{"t":"7 + 6 = 13","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","7 × 6 = 42예요.","그래서 42 ÷ 7 = 6은 맞아요."],"variant_rule":{"alt":[{"stem":"24 ÷ 4 = 6이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"4 × 6 = 24","correct":true},{"t":"6 × 24 = □","mis":"M3-1-u3-X12"},{"t":"24 × 4 = □","mis":"M3-1-u3-X12"},{"t":"4 + 6 = 10","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","4 × 6 = 24예요.","그래서 24 ÷ 4 = 6은 맞아요."],"asset":null},{"stem":"45 ÷ 5 = 9가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"5 × 9 = 45","correct":true},{"t":"9 × 45 = □","mis":"M3-1-u3-X12"},{"t":"45 × 5 = □","mis":"M3-1-u3-X12"},{"t":"5 + 9 = 14","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","5 × 9 = 45예요.","그래서 45 ÷ 5 = 9는 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#8','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',4,'essay','teacher','24 ÷ 4의 몫을 곱셈구구로 구하는 방법을 쓰고, 구한 몫이 맞는지 곱셈으로 확인해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u3-C6","difficulty":4,"kind":"essay","stem":"24 ÷ 4의 몫을 곱셈구구로 구하는 방법을 쓰고, 구한 몫이 맞는지 곱셈으로 확인해 보세요.","answer_guide":{"answer":"예: 24 ÷ 4는 4 × □ = 24가 되는 □를 찾는다. 4단에서 4 × 6 = 24이므로 몫은 6이다. 확인: 나누는 수 4와 몫 6을 곱하면 4 × 6 = 24로 나누어지는 수가 되므로 맞다.","scoring_points":["4 × □ = 24로 바꾸었는가","4단에서 몫 6을 찾았는가","4 × 6 = 24로 확인했는가"]},"explanation":["4 × □ = 24.","4 × 6 = 24 — 몫은 6.","확인 4 × 6 = 24 ✓"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#9','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',4,'essay','teacher','도윤이는 32 ÷ 4 = 7이라고 했어요. 곱셈으로 확인해 맞는지 판단하고, 바른 몫을 구해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u3-C6","difficulty":4,"kind":"essay","stem":"도윤이는 32 ÷ 4 = 7이라고 했어요. 곱셈으로 확인해 맞는지 판단하고, 바른 몫을 구해 보세요.","answer_guide":{"answer":"예: 나누는 수 4와 몫 7을 곱하면 4 × 7 = 28로 32가 아니므로 틀렸다. 4단에서 4 × 8 = 32이므로 바른 몫은 8이다.","scoring_points":["4 × 7 = 28로 확인했는가","32가 아니라 틀렸다고 판단했는가","바른 몫 8을 구했는가"]},"explanation":["4 × 7 = 28 ≠ 32.","4 × 8 = 32.","바른 몫은 8이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L06_challenge#10','math',3,1,'u3','L06','g3_1_math_u3_L06_challenge','lesson_challenge','M3-1-u3-C6',4,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":10,"concept":"M3-1-u3-C6","difficulty":4,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"36 ÷ 4","correct":true},{"t":"40 ÷ 8","mis":"M3-1-u3-X13"},{"t":"18 ÷ 3","mis":"M3-1-u3-X11"},{"t":"20 ÷ 5","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","40 ÷ 8 = 5, 18 ÷ 3 = 6, 20 ÷ 5 = 4, 36 ÷ 4 = 9.","몫이 가장 큰 것은 36 ÷ 4 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"40 ÷ 5","correct":true},{"t":"32 ÷ 8","mis":"M3-1-u3-X11"},{"t":"54 ÷ 9","mis":"M3-1-u3-X13"},{"t":"10 ÷ 2","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","32 ÷ 8 = 4, 40 ÷ 5 = 8, 54 ÷ 9 = 6, 10 ÷ 2 = 5.","몫이 가장 큰 것은 40 ÷ 5 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"18 ÷ 2","correct":true},{"t":"56 ÷ 8","mis":"M3-1-u3-X13"},{"t":"21 ÷ 7","mis":"M3-1-u3-X11"},{"t":"6 ÷ 3","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","56 ÷ 8 = 7, 21 ÷ 7 = 3, 18 ÷ 2 = 9, 6 ÷ 3 = 2.","몫이 가장 큰 것은 18 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#1','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C7',1,'mc','auto','나눔 장터에서 공책 15권을 5명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.',ARRAY['M3-1-u3-X03','M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":1,"concept":"M3-1-u3-C7","difficulty":1,"kind":"mc","stem":"나눔 장터에서 공책 15권을 5명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"15 ÷ 5 = 3, 3권씩","correct":true},{"t":"15 ÷ 3 = 5, 5권씩","mis":"M3-1-u3-X03"},{"t":"15 − 5 = 10, 10권씩","mis":"M3-1-u3-X13"},{"t":"15 ÷ 5 = 4, 4권씩","mis":"M3-1-u3-X11"}],"explanation":["5명에게 똑같이 나누니 나누는 수는 사람 수 5예요.","15 ÷ 5 — 5 × 3 = 15.","한 명이 3권씩 받아요."],"variant_rule":{"alt":[{"stem":"나눔 장터에서 연필 16자루를 8명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"16 ÷ 8 = 2, 2자루씩","correct":true},{"t":"16 ÷ 2 = 8, 8자루씩","mis":"M3-1-u3-X03"},{"t":"16 − 8 = 8, 8자루씩","mis":"M3-1-u3-X13"},{"t":"16 ÷ 8 = 3, 3자루씩","mis":"M3-1-u3-X11"}],"explanation":["8명에게 똑같이 나누니 나누는 수는 사람 수 8이에요.","16 ÷ 8 — 8 × 2 = 16.","한 명이 2자루씩 받아요."],"asset":null},{"stem":"나눔 장터에서 색종이 18장을 3명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"18 ÷ 3 = 6, 6장씩","correct":true},{"t":"18 ÷ 6 = 3, 3장씩","mis":"M3-1-u3-X03"},{"t":"18 − 3 = 15, 15장씩","mis":"M3-1-u3-X13"},{"t":"18 ÷ 3 = 7, 7장씩","mis":"M3-1-u3-X11"}],"explanation":["3명에게 똑같이 나누니 나누는 수는 사람 수 3이에요.","18 ÷ 3 — 3 × 6 = 18.","한 명이 6장씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#2','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C7',1,'sa','auto','구슬 20개를 한 봉지에 4개씩 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M3-1-u3-C7","difficulty":1,"kind":"sa","stem":"구슬 20개를 한 봉지에 4개씩 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["5"],"explanation":["20개에서 4개씩 덜어 내요.","4 × □ = 20에서 □ = 5 — 5번 덜어 낼 수 있어요.","그래서 5봉지예요."],"variant_rule":{"alt":[{"stem":"구슬 28개를 봉지 7개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["28개를 봉지 7개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","7묶음으로 똑같이 나누니 7 × □ = 28에서 □ = 4예요.","한 봉지에 4개예요."],"asset":null},{"stem":"지우개 15개를 한 접시에 5개씩 담으면 몇 접시가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["15개에서 5개씩 덜어 내요.","5 × □ = 15에서 □ = 3 — 3번 덜어 낼 수 있어요.","그래서 3접시예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#3','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C7',1,'mc','auto','사탕 21개를 한 상자에 3개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":3,"concept":"M3-1-u3-C7","difficulty":1,"kind":"mc","stem":"사탕 21개를 한 상자에 3개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?","options":[{"t":"7상자","correct":true},{"t":"3상자","mis":"M3-1-u3-X02"},{"t":"18상자","mis":"M3-1-u3-X07"},{"t":"8상자","mis":"M3-1-u3-X11"}],"explanation":["한 상자에 3개씩 — 몇 번 담을 수 있는지 구해요.","21 ÷ 3 = 7 (3 × 7 = 21).","7상자가 필요해요."],"variant_rule":{"alt":[{"stem":"쿠키 32개를 한 접시에 8개씩 담아 나눔 장터에 내놓으려고 해요. 몇 접시가 필요한가요?","options":[{"t":"4접시","correct":true},{"t":"8접시","mis":"M3-1-u3-X02"},{"t":"24접시","mis":"M3-1-u3-X07"},{"t":"5접시","mis":"M3-1-u3-X11"}],"explanation":["한 접시에 8개씩 — 몇 번 담을 수 있는지 구해요.","32 ÷ 8 = 4 (8 × 4 = 32).","4접시가 필요해요."],"asset":null},{"stem":"딸기 35개를 한 바구니에 5개씩 담아 나눔 장터에 내놓으려고 해요. 몇 바구니가 필요한가요?","options":[{"t":"7바구니","correct":true},{"t":"5바구니","mis":"M3-1-u3-X02"},{"t":"30바구니","mis":"M3-1-u3-X07"},{"t":"8바구니","mis":"M3-1-u3-X11"}],"explanation":["한 바구니에 5개씩 — 몇 번 담을 수 있는지 구해요.","35 ÷ 5 = 7 (5 × 7 = 35).","7바구니가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#4','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C8',1,'mc','auto','사탕 12개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":4,"concept":"M3-1-u3-C8","difficulty":1,"kind":"mc","stem":"사탕 12개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"6명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"3명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"2명에게 6개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 12가 있으면 남김없이 나눌 수 있어요.","6명에게 2개씩, 3명에게 4개씩, 2명에게 6개씩 — 모두 곱셈구구로 12가 돼요.","5단에는 12가 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"사탕 18개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"3명에게 6개씩","mis":"M3-1-u3-X15"},{"t":"9명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"6명에게 3개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 18이 있으면 남김없이 나눌 수 있어요.","3명에게 6개씩, 9명에게 2개씩, 6명에게 3개씩 — 모두 곱셈구구로 18이 돼요.","5단에는 18이 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null},{"stem":"사탕 16개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"6명에게 똑같이","correct":true},{"t":"4명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"8명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"2명에게 8개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 16이 있으면 남김없이 나눌 수 있어요.","4명에게 4개씩, 8명에게 2개씩, 2명에게 8개씩 — 모두 곱셈구구로 16이 돼요.","6단에는 16이 없어서 6명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#5','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C7',2,'mc','auto','지우개 24개를 한 컵에 6개씩 담으면 몇 컵이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":5,"concept":"M3-1-u3-C7","difficulty":2,"kind":"mc","stem":"지우개 24개를 한 컵에 6개씩 담으면 몇 컵이 되나요?","options":[{"t":"4컵","correct":true},{"t":"6컵","mis":"M3-1-u3-X02"},{"t":"18컵","mis":"M3-1-u3-X07"},{"t":"5컵","mis":"M3-1-u3-X11"}],"explanation":["24개에서 6개씩 덜어 내요.","6 × □ = 24에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4컵이에요."],"variant_rule":{"alt":[{"stem":"지우개 8개를 접시 2개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요?","options":[{"t":"4개","correct":true},{"t":"2개","mis":"M3-1-u3-X02"},{"t":"6개","mis":"M3-1-u3-X07"},{"t":"5개","mis":"M3-1-u3-X11"}],"explanation":["8개를 접시 2개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","2묶음으로 똑같이 나누니 2 × □ = 8에서 □ = 4예요.","한 접시에 4개예요."],"asset":null},{"stem":"귤 14개를 한 봉지에 2개씩 담으면 몇 봉지가 되나요?","options":[{"t":"7봉지","correct":true},{"t":"2봉지","mis":"M3-1-u3-X02"},{"t":"12봉지","mis":"M3-1-u3-X07"},{"t":"8봉지","mis":"M3-1-u3-X11"}],"explanation":["14개에서 2개씩 덜어 내요.","2 × □ = 14에서 □ = 7 — 7번 덜어 낼 수 있어요.","그래서 7봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#6','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C7',2,'ox','auto','클립 12개를 4명에게 똑같이 나누는 것과 4개씩 묶는 것은 묻는 것이 같은 상황이에요.',ARRAY['M3-1-u3-X03']::text[],true,'{"seq":6,"concept":"M3-1-u3-C7","difficulty":2,"kind":"ox","stem":"클립 12개를 4명에게 똑같이 나누는 것과 4개씩 묶는 것은 묻는 것이 같은 상황이에요.","answer":"X","reason_options":[{"t":"하나는 한 명이 받는 수를, 하나는 묶음 수를 물어서","correct":true},{"t":"둘 다 4를 쓰니까 같은 상황이라서","mis":"M3-1-u3-X03"}],"mis":"M3-1-u3-X03","explanation":["4명에게 똑같이 나누면 한 명에게 3개씩이에요.","4개씩 묶으면 3묶음이에요.","식은 둘 다 12 ÷ 4지만 묻는 것과 답의 뜻이 달라요."],"variant_rule":{"alt":[{"stem":"귤 56개를 7명에게 똑같이 나누는 것과 7개씩 묶는 것은 묻는 것이 같은 상황이에요.","answer":"X","reason_options":[{"t":"하나는 한 명이 받는 수를, 하나는 묶음 수를 물어서","correct":true},{"t":"둘 다 7을 쓰니까 같은 상황이라서","mis":"M3-1-u3-X03"}],"explanation":["7명에게 똑같이 나누면 한 명에게 8개씩이에요.","7개씩 묶으면 8묶음이에요.","식은 둘 다 56 ÷ 7이지만 묻는 것과 답의 뜻이 달라요."],"asset":null},{"stem":"공책 72권을 8명에게 똑같이 나누는 것과 8권씩 묶는 것은 묻는 것이 같은 상황이에요.","answer":"X","reason_options":[{"t":"하나는 한 명이 받는 수를, 하나는 묶음 수를 물어서","correct":true},{"t":"둘 다 8을 쓰니까 같은 상황이라서","mis":"M3-1-u3-X03"}],"explanation":["8명에게 똑같이 나누면 한 명에게 9권씩이에요.","8권씩 묶으면 9묶음이에요.","식은 둘 다 72 ÷ 8이지만 묻는 것과 답의 뜻이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#7','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C8',2,'sa','auto','구슬 12개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M3-1-u3-C8","difficulty":2,"kind":"sa","stem":"구슬 12개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["곱셈구구에서 곱이 12가 되는 식을 찾아요.","2 × 6, 3 × 4, 4 × 3, 6 × 2 = 12.","사람 수가 2명·3명·4명·6명 — 모두 4가지예요."],"variant_rule":{"alt":[{"stem":"구슬 18개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["곱셈구구에서 곱이 18이 되는 식을 찾아요.","2 × 9, 3 × 6, 6 × 3, 9 × 2 = 18.","사람 수가 2명·3명·6명·9명 — 모두 4가지예요."],"asset":null},{"stem":"구슬 16개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["곱셈구구에서 곱이 16이 되는 식을 찾아요.","2 × 8, 4 × 4, 8 × 2 = 16.","사람 수가 2명·4명·8명 — 모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#8','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C7',2,'mc','auto','풍선 32개를 한 컵에 4개씩 담아 나눔 장터에 내놓으려고 해요. 몇 컵이 필요한가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":8,"concept":"M3-1-u3-C7","difficulty":2,"kind":"mc","stem":"풍선 32개를 한 컵에 4개씩 담아 나눔 장터에 내놓으려고 해요. 몇 컵이 필요한가요?","options":[{"t":"8컵","correct":true},{"t":"4컵","mis":"M3-1-u3-X02"},{"t":"28컵","mis":"M3-1-u3-X07"},{"t":"9컵","mis":"M3-1-u3-X11"}],"explanation":["한 컵에 4개씩 — 몇 번 담을 수 있는지 구해요.","32 ÷ 4 = 8 (4 × 8 = 32).","8컵이 필요해요."],"variant_rule":{"alt":[{"stem":"별 스티커 9장을 한 주머니에 3장씩 담아 나눔 장터에 내놓으려고 해요. 몇 주머니가 필요한가요?","options":[{"t":"3주머니","correct":true},{"t":"6주머니","mis":"M3-1-u3-X07"},{"t":"4주머니","mis":"M3-1-u3-X11"},{"t":"2주머니","mis":"M3-1-u3-X11"}],"explanation":["한 주머니에 3장씩 — 몇 번 담을 수 있는지 구해요.","9 ÷ 3 = 3 (3 × 3 = 9).","3주머니가 필요해요."],"asset":null},{"stem":"컵케이크 16개를 한 봉지에 2개씩 담아 나눔 장터에 내놓으려고 해요. 몇 봉지가 필요한가요?","options":[{"t":"8봉지","correct":true},{"t":"2봉지","mis":"M3-1-u3-X02"},{"t":"14봉지","mis":"M3-1-u3-X07"},{"t":"9봉지","mis":"M3-1-u3-X11"}],"explanation":["한 봉지에 2개씩 — 몇 번 담을 수 있는지 구해요.","16 ÷ 2 = 8 (2 × 8 = 16).","8봉지가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#9','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C8',2,'match','auto','구슬 12개를 남김없이 똑같이 나누어요. 사람 수와 한 명이 받는 수를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M3-1-u3-C8","difficulty":2,"kind":"match","stem":"구슬 12개를 남김없이 똑같이 나누어요. 사람 수와 한 명이 받는 수를 알맞게 이으세요.","pairs":[{"l":"2명","r":"6개씩"},{"l":"3명","r":"4개씩"},{"l":"4명","r":"3개씩"}],"mis":"M3-1-u3-X11","explanation":["사람 수 × 한 명이 받는 수 = 12가 되어야 해요.","2 × 6 = 12, 3 × 4 = 12, 4 × 3 = 12.","곱셈구구로 짝을 찾아요."],"variant_rule":{"alt":[{"stem":"구슬 24개를 남김없이 똑같이 나누어요. 사람 수와 한 명이 받는 수를 알맞게 이으세요.","pairs":[{"l":"3명","r":"8개씩"},{"l":"4명","r":"6개씩"},{"l":"6명","r":"4개씩"}],"explanation":["사람 수 × 한 명이 받는 수 = 24가 되어야 해요.","3 × 8 = 24, 4 × 6 = 24, 6 × 4 = 24.","곱셈구구로 짝을 찾아요."],"asset":null},{"stem":"구슬 18개를 남김없이 똑같이 나누어요. 사람 수와 한 명이 받는 수를 알맞게 이으세요.","pairs":[{"l":"2명","r":"9개씩"},{"l":"3명","r":"6개씩"},{"l":"6명","r":"3개씩"}],"explanation":["사람 수 × 한 명이 받는 수 = 18이 되어야 해요.","2 × 9 = 18, 3 × 6 = 18, 6 × 3 = 18.","곱셈구구로 짝을 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_basic#10','math',3,1,'u3','L07','g3_1_math_u3_L07_basic','lesson_basic','M3-1-u3-C7',3,'sa','auto','연필 24자루를 3명에게 똑같이 나누어 주었어요. 한 명이 받은 연필을 다시 2자루씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u3-C7","difficulty":3,"kind":"sa","stem":"연필 24자루를 3명에게 똑같이 나누어 주었어요. 한 명이 받은 연필을 다시 2자루씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 한 명이 받은 수: 24 ÷ 3 = 8.","그다음 8을 2자루씩 담아요: 8 ÷ 2 = 4.","그래서 4봉지예요."],"variant_rule":{"alt":[{"stem":"색종이 24장을 4명에게 똑같이 나누어 주었어요. 한 명이 받은 색종이를 다시 3장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 한 명이 받은 수: 24 ÷ 4 = 6.","그다음 6을 3장씩 담아요: 6 ÷ 3 = 2.","그래서 2봉지예요."],"asset":null},{"stem":"귤 18개를 2명에게 똑같이 나누어 주었어요. 한 명이 받은 귤을 다시 3개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 18 ÷ 2 = 9.","그다음 9를 3개씩 담아요: 9 ÷ 3 = 3.","그래서 3봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#1','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C7',2,'mc','auto','나눔 장터에서 클립 28개를 7명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.',ARRAY['M3-1-u3-X03','M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":1,"concept":"M3-1-u3-C7","difficulty":2,"kind":"mc","stem":"나눔 장터에서 클립 28개를 7명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"28 ÷ 7 = 4, 4개씩","correct":true},{"t":"28 ÷ 4 = 7, 7개씩","mis":"M3-1-u3-X03"},{"t":"28 − 7 = 21, 21개씩","mis":"M3-1-u3-X13"},{"t":"28 ÷ 7 = 5, 5개씩","mis":"M3-1-u3-X11"}],"explanation":["7명에게 똑같이 나누니 나누는 수는 사람 수 7이에요.","28 ÷ 7 — 7 × 4 = 28.","한 명이 4개씩 받아요."],"variant_rule":{"alt":[{"stem":"나눔 장터에서 귤 63개를 7명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"63 ÷ 7 = 9, 9개씩","correct":true},{"t":"63 ÷ 9 = 7, 7개씩","mis":"M3-1-u3-X03"},{"t":"63 − 7 = 56, 56개씩","mis":"M3-1-u3-X13"},{"t":"63 ÷ 7 = 10, 10개씩","mis":"M3-1-u3-X11"}],"explanation":["7명에게 똑같이 나누니 나누는 수는 사람 수 7이에요.","63 ÷ 7 — 7 × 9 = 63.","한 명이 9개씩 받아요."],"asset":null},{"stem":"나눔 장터에서 공책 18권을 3명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"18 ÷ 3 = 6, 6권씩","correct":true},{"t":"18 ÷ 6 = 3, 3권씩","mis":"M3-1-u3-X03"},{"t":"18 − 3 = 15, 15권씩","mis":"M3-1-u3-X13"},{"t":"18 ÷ 3 = 7, 7권씩","mis":"M3-1-u3-X11"}],"explanation":["3명에게 똑같이 나누니 나누는 수는 사람 수 3이에요.","18 ÷ 3 — 3 × 6 = 18.","한 명이 6권씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#2','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C8',2,'mc','auto','사탕 24개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":2,"concept":"M3-1-u3-C8","difficulty":2,"kind":"mc","stem":"사탕 24개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"6명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"3명에게 8개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 6개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 24가 있으면 남김없이 나눌 수 있어요.","6명에게 4개씩, 3명에게 8개씩, 4명에게 6개씩 — 모두 곱셈구구로 24가 돼요.","5단에는 24가 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"사탕 36개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"6명에게 6개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 9개씩","mis":"M3-1-u3-X15"},{"t":"9명에게 4개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 36이 있으면 남김없이 나눌 수 있어요.","6명에게 6개씩, 4명에게 9개씩, 9명에게 4개씩 — 모두 곱셈구구로 36이 돼요.","5단에는 36이 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null},{"stem":"사탕 18개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"7명에게 똑같이","correct":true},{"t":"2명에게 9개씩","mis":"M3-1-u3-X15"},{"t":"6명에게 3개씩","mis":"M3-1-u3-X15"},{"t":"9명에게 2개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 18이 있으면 남김없이 나눌 수 있어요.","2명에게 9개씩, 6명에게 3개씩, 9명에게 2개씩 — 모두 곱셈구구로 18이 돼요.","7단에는 18이 없어서 7명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#3','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C7',3,'error','auto','클립 30개를 한 바구니에 6개씩 담으면 몇 바구니가 되는지 친구들이 식을 세웠어요. 잘못 세운 친구는 누구인가요?',ARRAY['M3-1-u3-X13','M3-1-u3-X15']::text[],true,'{"seq":3,"concept":"M3-1-u3-C7","difficulty":3,"kind":"error","stem":"클립 30개를 한 바구니에 6개씩 담으면 몇 바구니가 되는지 친구들이 식을 세웠어요. 잘못 세운 친구는 누구인가요?","options":[{"t":"서윤 — 「30 × 6」","correct":true,"mis_target":"M3-1-u3-X13"},{"t":"하랑 — 「30 ÷ 6」","mis":"M3-1-u3-X15"},{"t":"지유 — 「6 × □ = 30」","mis":"M3-1-u3-X15"}],"explanation":["30개에서 6개씩 덜어 내니 나눗셈이에요.","30 ÷ 6 = 5 — 6 × □ = 30으로 몫을 구해도 돼요.","서윤은 나눗셈 상황에 곱셈을 골랐어요."],"variant_rule":{"alt":[{"stem":"귤 12개를 한 컵에 4개씩 담으면 몇 컵이 되는지 친구들이 식을 세웠어요. 잘못 세운 친구는 누구인가요?","options":[{"t":"하랑 — 「12 × 4」","correct":true,"mis_target":"M3-1-u3-X13"},{"t":"서윤 — 「12 ÷ 4」","mis":"M3-1-u3-X15"},{"t":"태오 — 「4 × □ = 12」","mis":"M3-1-u3-X15"}],"explanation":["12개에서 4개씩 덜어 내니 나눗셈이에요.","12 ÷ 4 = 3 — 4 × □ = 12로 몫을 구해도 돼요.","하랑은 나눗셈 상황에 곱셈을 골랐어요."],"asset":null},{"stem":"공책 6권을 한 주머니에 3권씩 담으면 몇 주머니가 되는지 친구들이 식을 세웠어요. 잘못 세운 친구는 누구인가요?","options":[{"t":"지유 — 「6 × 3」","correct":true,"mis_target":"M3-1-u3-X13"},{"t":"시우 — 「6 ÷ 3」","mis":"M3-1-u3-X15"},{"t":"하랑 — 「3 × □ = 6」","mis":"M3-1-u3-X15"}],"explanation":["6권에서 3권씩 덜어 내니 나눗셈이에요.","6 ÷ 3 = 2 — 3 × □ = 6으로 몫을 구해도 돼요.","지유는 나눗셈 상황에 곱셈을 골랐어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#4','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C8',3,'sa','auto','구슬 18개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M3-1-u3-C8","difficulty":3,"kind":"sa","stem":"구슬 18개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["곱셈구구에서 곱이 18이 되는 식을 찾아요.","2 × 9, 3 × 6, 6 × 3, 9 × 2 = 18.","사람 수가 2명·3명·6명·9명 — 모두 4가지예요."],"variant_rule":{"alt":[{"stem":"구슬 12개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["곱셈구구에서 곱이 12가 되는 식을 찾아요.","2 × 6, 3 × 4, 4 × 3, 6 × 2 = 12.","사람 수가 2명·3명·4명·6명 — 모두 4가지예요."],"asset":null},{"stem":"구슬 16개를 2명 이상에게 남김없이 똑같이 나누어 주려고 해요. 한 명이 2개 이상 받는다면 나누어 줄 수 있는 사람 수는 모두 몇 가지인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["곱셈구구에서 곱이 16이 되는 식을 찾아요.","2 × 8, 4 × 4, 8 × 2 = 16.","사람 수가 2명·4명·8명 — 모두 3가지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#5','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C7',3,'sa','auto','카드 32장을 4명에게 똑같이 나누어 주었어요. 한 명이 받은 카드를 다시 2장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C7","difficulty":3,"kind":"sa","stem":"카드 32장을 4명에게 똑같이 나누어 주었어요. 한 명이 받은 카드를 다시 2장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 한 명이 받은 수: 32 ÷ 4 = 8.","그다음 8을 2장씩 담아요: 8 ÷ 2 = 4.","그래서 4봉지예요."],"variant_rule":{"alt":[{"stem":"귤 18개를 3명에게 똑같이 나누어 주었어요. 한 명이 받은 귤을 다시 2개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 18 ÷ 3 = 6.","그다음 6을 2개씩 담아요: 6 ÷ 2 = 3.","그래서 3봉지예요."],"asset":null},{"stem":"귤 40개를 5명에게 똑같이 나누어 주었어요. 한 명이 받은 귤을 다시 4개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 한 명이 받은 수: 40 ÷ 5 = 8.","그다음 8을 4개씩 담아요: 8 ÷ 4 = 2.","그래서 2봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#6','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C7',3,'mc','auto','도넛 56개를 한 상자에 8개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":6,"concept":"M3-1-u3-C7","difficulty":3,"kind":"mc","stem":"도넛 56개를 한 상자에 8개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?","options":[{"t":"7상자","correct":true},{"t":"8상자","mis":"M3-1-u3-X02"},{"t":"48상자","mis":"M3-1-u3-X07"},{"t":"6상자","mis":"M3-1-u3-X11"}],"explanation":["한 상자에 8개씩 — 몇 번 담을 수 있는지 구해요.","56 ÷ 8 = 7 (8 × 7 = 56).","7상자가 필요해요."],"variant_rule":{"alt":[{"stem":"사과 14개를 한 접시에 7개씩 담아 나눔 장터에 내놓으려고 해요. 몇 접시가 필요한가요?","options":[{"t":"2접시","correct":true},{"t":"7접시","mis":"M3-1-u3-X02"},{"t":"3접시","mis":"M3-1-u3-X11"},{"t":"1접시","mis":"M3-1-u3-X11"}],"explanation":["한 접시에 7개씩 — 몇 번 담을 수 있는지 구해요.","14 ÷ 7 = 2 (7 × 2 = 14).","2접시가 필요해요."],"asset":null},{"stem":"당근 45개를 한 바구니에 9개씩 담아 나눔 장터에 내놓으려고 해요. 몇 바구니가 필요한가요?","options":[{"t":"5바구니","correct":true},{"t":"9바구니","mis":"M3-1-u3-X02"},{"t":"36바구니","mis":"M3-1-u3-X07"},{"t":"6바구니","mis":"M3-1-u3-X11"}],"explanation":["한 바구니에 9개씩 — 몇 번 담을 수 있는지 구해요.","45 ÷ 9 = 5 (9 × 5 = 45).","5바구니가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#7','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C7',3,'mc','auto','구슬 72개를 한 컵에 9개씩 담으면 몇 컵이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":7,"concept":"M3-1-u3-C7","difficulty":3,"kind":"mc","stem":"구슬 72개를 한 컵에 9개씩 담으면 몇 컵이 되나요?","options":[{"t":"8컵","correct":true},{"t":"9컵","mis":"M3-1-u3-X02"},{"t":"63컵","mis":"M3-1-u3-X07"},{"t":"7컵","mis":"M3-1-u3-X11"}],"explanation":["72개에서 9개씩 덜어 내요.","9 × □ = 72에서 □ = 8 — 8번 덜어 낼 수 있어요.","그래서 8컵이에요."],"variant_rule":{"alt":[{"stem":"구슬 10개를 접시 2개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M3-1-u3-X02"},{"t":"8개","mis":"M3-1-u3-X07"},{"t":"6개","mis":"M3-1-u3-X11"}],"explanation":["10개를 접시 2개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","2묶음으로 똑같이 나누니 2 × □ = 10에서 □ = 5예요.","한 접시에 5개예요."],"asset":null},{"stem":"지우개 36개를 한 봉지에 9개씩 담으면 몇 봉지가 되나요?","options":[{"t":"4봉지","correct":true},{"t":"9봉지","mis":"M3-1-u3-X02"},{"t":"27봉지","mis":"M3-1-u3-X07"},{"t":"5봉지","mis":"M3-1-u3-X11"}],"explanation":["36개에서 9개씩 덜어 내요.","9 × □ = 36에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#8','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C7',4,'essay','teacher','나눗셈식 28 ÷ 4 = 7에 알맞은 나눔 장터 이야기를 하나 만들고, 몫 7이 무엇을 뜻하는지 써 보세요.','{}'::text[],false,'{"seq":8,"concept":"M3-1-u3-C7","difficulty":4,"kind":"essay","stem":"나눗셈식 28 ÷ 4 = 7에 알맞은 나눔 장터 이야기를 하나 만들고, 몫 7이 무엇을 뜻하는지 써 보세요.","answer_guide":{"answer":"예: 「귤 28개를 4명에게 똑같이 나누어 주면 한 명이 몇 개씩 받을까요?」 — 몫 7은 한 명이 받는 귤 수(7개씩)이다. (또는 「귤 28개를 4개씩 봉지에 담으면 몇 봉지?」 — 몫 7은 봉지 수)","scoring_points":["28과 4가 들어간 똑같이 나누는 이야기를 만들었는가","이야기에 맞게 몫 7의 뜻을 썼는가","4 × 7 = 28과 맞는지 확인했는가"]},"explanation":["28을 4명에게(또는 4개씩) 나누는 이야기를 만들어요.","몫 7은 한 명 몫(또는 봉지 수)이에요.","4 × 7 = 28로 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#9','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C8',4,'essay','teacher','사탕 24개를 남김없이 똑같이 나누는 방법을 곱셈구구로 세 가지 이상 찾고, 5명에게는 왜 똑같이 나눌 수 없는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M3-1-u3-C8","difficulty":4,"kind":"essay","stem":"사탕 24개를 남김없이 똑같이 나누는 방법을 곱셈구구로 세 가지 이상 찾고, 5명에게는 왜 똑같이 나눌 수 없는지 써 보세요.","answer_guide":{"answer":"예: 3명에게 8개씩(3 × 8), 4명에게 6개씩(4 × 6), 6명에게 4개씩(6 × 4), 8명에게 3개씩(8 × 3). 5단에는 24가 없으므로(5 × 4 = 20, 5 × 5 = 25) 5명에게는 남김없이 똑같이 나눌 수 없다.","scoring_points":["곱이 24인 곱셈구구로 세 가지 이상 찾았는가","방법마다 사람 수와 한 명 몫을 썼는가","5단에 24가 없어서라고 설명했는가"]},"explanation":["곱이 24인 곱셈구구를 찾아요.","3×8, 4×6, 6×4, 8×3.","5단에는 24가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_L07_challenge#10','math',3,1,'u3','L07','g3_1_math_u3_L07_challenge','lesson_challenge','M3-1-u3-C7',4,'sa','auto','공책 36권을 6명에게 똑같이 나누어 주었어요. 한 명이 받은 공책을 다시 2권씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M3-1-u3-C7","difficulty":4,"kind":"sa","stem":"공책 36권을 6명에게 똑같이 나누어 주었어요. 한 명이 받은 공책을 다시 2권씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 36 ÷ 6 = 6.","그다음 6을 2권씩 담아요: 6 ÷ 2 = 3.","그래서 3봉지예요."],"variant_rule":{"alt":[{"stem":"클립 16개를 2명에게 똑같이 나누어 주었어요. 한 명이 받은 클립을 다시 4개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 한 명이 받은 수: 16 ÷ 2 = 8.","그다음 8을 4개씩 담아요: 8 ÷ 4 = 2.","그래서 2봉지예요."],"asset":null},{"stem":"지우개 36개를 4명에게 똑같이 나누어 주었어요. 한 명이 받은 지우개를 다시 3개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 36 ÷ 4 = 9.","그다음 9를 3개씩 담아요: 9 ÷ 3 = 3.","그래서 3봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#1','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C1',1,'mc','auto','풍선 18개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":1,"concept":"M3-1-u3-C1","difficulty":1,"kind":"mc","stem":"풍선 18개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"6명에게 3개씩","correct":true},{"t":"6명에게 5·4·1·2·3·3개","mis":"M3-1-u3-X01"},{"t":"7명에게 4·3·3·3·3·3·2개","mis":"M3-1-u3-X01"},{"t":"5명에게 3·4·3·1·7개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","6명이 모두 3개씩 받으면 6 × 3 = 18개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"variant_rule":{"alt":[{"stem":"별 스티커 35장을 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"7명에게 5장씩","correct":true},{"t":"7명에게 6·6·4·5·7·5·2장","mis":"M3-1-u3-X01"},{"t":"8명에게 5·4·4·2·2·1·9·8장","mis":"M3-1-u3-X01"},{"t":"6명에게 4·7·7·8·3·6장","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","7명이 모두 5장씩 받으면 7 × 5 = 35장 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null},{"stem":"컵케이크 40개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"8명에게 5개씩","correct":true},{"t":"8명에게 7·3·2·3·6·7·7·5개","mis":"M3-1-u3-X01"},{"t":"9명에게 4·7·2·9·1·4·6·6·1개","mis":"M3-1-u3-X01"},{"t":"7명에게 1·8·8·6·5·6·6개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","8명이 모두 5개씩 받으면 8 × 5 = 40개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#2','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C2',1,'mc','auto','풍선 12개를 모둠 2개에 똑같이 나누었어요. 한 모둠에 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":2,"concept":"M3-1-u3-C2","difficulty":1,"kind":"mc","stem":"풍선 12개를 모둠 2개에 똑같이 나누었어요. 한 모둠에 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"2개","mis":"M3-1-u3-X02"},{"t":"10개","mis":"M3-1-u3-X07"},{"t":"7개","mis":"M3-1-u3-X11"}],"explanation":["풍선 12개를 모둠 2개에 하나씩 번갈아 놓았어요.","묶음마다 6개씩 똑같이 있어요.","그래서 한 모둠에 6개예요."],"asset":{"type":"mul_groups","item":"🎈","k":6,"n":2},"variant_rule":{"alt":[{"stem":"별 스티커 6장을 봉지 3개에 똑같이 나누었어요. 한 봉지에 몇 장씩인가요?","options":[{"t":"2장","correct":true},{"t":"3장","mis":"M3-1-u3-X02"},{"t":"1장","mis":"M3-1-u3-X11"},{"t":"6장","mis":"M3-1-u3-X06"}],"explanation":["별 스티커 6장을 봉지 3개에 하나씩 번갈아 놓았어요.","묶음마다 2장씩 똑같이 있어요.","그래서 한 봉지에 2장이에요."],"asset":{"type":"mul_groups","item":"⭐","k":2,"n":3}},{"stem":"컵케이크 10개를 상자 2개에 똑같이 나누었어요. 한 상자에 몇 개씩인가요?","options":[{"t":"5개","correct":true},{"t":"2개","mis":"M3-1-u3-X02"},{"t":"8개","mis":"M3-1-u3-X07"},{"t":"6개","mis":"M3-1-u3-X11"}],"explanation":["컵케이크 10개를 상자 2개에 하나씩 번갈아 놓았어요.","묶음마다 5개씩 똑같이 있어요.","그래서 한 상자에 5개예요."],"asset":{"type":"mul_groups","item":"🧁","k":5,"n":2}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#3','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C2',1,'sa','auto','공책 20권을 상자 5개에 똑같이 나누어 담으면 한 상자에 몇 권씩인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C2","difficulty":1,"kind":"sa","stem":"공책 20권을 상자 5개에 똑같이 나누어 담으면 한 상자에 몇 권씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["20권을 상자 5개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","5묶음으로 똑같이 나누니 5 × □ = 20에서 □ = 4예요.","한 상자에 4권이에요."],"variant_rule":{"alt":[{"stem":"연필 25자루를 바구니 5개에 똑같이 나누어 담으면 한 바구니에 몇 자루씩인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["25자루를 바구니 5개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","5묶음으로 똑같이 나누니 5 × □ = 25에서 □ = 5예요.","한 바구니에 5자루예요."],"asset":null},{"stem":"색종이 21장을 친구 7명에게 똑같이 나누어 주면 한 명에게 몇 장씩인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["21장을 친구 7명에게 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","7묶음으로 똑같이 나누니 7 × □ = 21에서 □ = 3이에요.","한 명에게 3장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#4','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C3',1,'mc','auto','사탕 40개를 5개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":4,"concept":"M3-1-u3-C3","difficulty":1,"kind":"mc","stem":"사탕 40개를 5개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"8묶음","correct":true},{"t":"5묶음","mis":"M3-1-u3-X02"},{"t":"35묶음","mis":"M3-1-u3-X07"},{"t":"9묶음","mis":"M3-1-u3-X11"}],"explanation":["5개씩 묶은 테두리를 세어요.","5씩 8번 덜어 내면 40개 모두 덜어 내져요 — 5 × 8 = 40.","그래서 8묶음이에요."],"asset":{"type":"mul_groups","item":"🍬","k":5,"n":8},"variant_rule":{"alt":[{"stem":"쿠키 18개를 3개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"6묶음","correct":true},{"t":"3묶음","mis":"M3-1-u3-X02"},{"t":"15묶음","mis":"M3-1-u3-X07"},{"t":"7묶음","mis":"M3-1-u3-X11"}],"explanation":["3개씩 묶은 테두리를 세어요.","3씩 6번 덜어 내면 18개 모두 덜어 내져요 — 3 × 6 = 18.","그래서 6묶음이에요."],"asset":{"type":"mul_groups","item":"🍪","k":3,"n":6}},{"stem":"딸기 12개를 3개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"4묶음","correct":true},{"t":"3묶음","mis":"M3-1-u3-X02"},{"t":"9묶음","mis":"M3-1-u3-X07"},{"t":"5묶음","mis":"M3-1-u3-X11"}],"explanation":["3개씩 묶은 테두리를 세어요.","3씩 4번 덜어 내면 12개 모두 덜어 내져요 — 3 × 4 = 12.","그래서 4묶음이에요."],"asset":{"type":"mul_groups","item":"🍓","k":3,"n":4}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#5','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C3',1,'sa','auto','10 − 5 − 5 = 0에서 5를 몇 번 뺐나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C3","difficulty":1,"kind":"sa","stem":"10 − 5 − 5 = 0에서 5를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["2"],"explanation":["빼는 수 5가 몇 개인지 세어요.","10 − 5를 2번 하면 0이 돼요.","10은 5씩 2묶음으로 덜어 낼 수 있어요."],"variant_rule":{"alt":[{"stem":"18 − 2 − 2 − 2 − 2 − 2 − 2 − 2 − 2 − 2 = 0에서 2를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["9"],"explanation":["빼는 수 2가 몇 개인지 세어요.","18 − 2를 9번 하면 0이 돼요.","18은 2씩 9묶음으로 덜어 낼 수 있어요."],"asset":null},{"stem":"16 − 4 − 4 − 4 − 4 = 0에서 4를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["4"],"explanation":["빼는 수 4가 몇 개인지 세어요.","16 − 4를 4번 하면 0이 돼요.","16은 4씩 4묶음으로 덜어 낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#6','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C4',1,'mc','auto','32 ÷ 4를 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-1-u3-X07','M3-1-u3-X05']::text[],true,'{"seq":6,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"32 ÷ 4를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"32 나누기 4","correct":true},{"t":"32 곱하기 4","mis":"M3-1-u3-X07"},{"t":"4 나누기 32","mis":"M3-1-u3-X05"},{"t":"32 빼기 4","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 32 나누기 4.","32 ÷ 4 = 8은 「32 나누기 4는 8」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"21 ÷ 7을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"21 나누기 7","correct":true},{"t":"21 곱하기 7","mis":"M3-1-u3-X07"},{"t":"7 나누기 21","mis":"M3-1-u3-X05"},{"t":"21 빼기 7","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 21 나누기 7.","21 ÷ 7 = 3은 「21 나누기 7은 3」이라고 읽어요."],"asset":null},{"stem":"63 ÷ 7을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"63 나누기 7","correct":true},{"t":"63 곱하기 7","mis":"M3-1-u3-X07"},{"t":"7 나누기 63","mis":"M3-1-u3-X05"},{"t":"63 빼기 7","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 63 나누기 7.","63 ÷ 7 = 9는 「63 나누기 7은 9」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#7','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C4',1,'mc','auto','48 ÷ 8 = 6에서 몫은 어느 것인가요?',ARRAY['M3-1-u3-X06']::text[],true,'{"seq":7,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"48 ÷ 8 = 6에서 몫은 어느 것인가요?","options":[{"t":"6","correct":true},{"t":"48","mis":"M3-1-u3-X06"},{"t":"8","mis":"M3-1-u3-X06"},{"t":"48과 8","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","48은 나누어지는 수, 8은 나누는 수예요.","= 뒤의 6이 몫이에요."],"variant_rule":{"alt":[{"stem":"63 ÷ 9 = 7에서 몫은 어느 것인가요?","options":[{"t":"7","correct":true},{"t":"63","mis":"M3-1-u3-X06"},{"t":"9","mis":"M3-1-u3-X06"},{"t":"63과 9","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","63은 나누어지는 수, 9는 나누는 수예요.","= 뒤의 7이 몫이에요."],"asset":null},{"stem":"42 ÷ 6 = 7에서 몫은 어느 것인가요?","options":[{"t":"7","correct":true},{"t":"42","mis":"M3-1-u3-X06"},{"t":"6","mis":"M3-1-u3-X06"},{"t":"42와 6","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","42는 나누어지는 수, 6은 나누는 수예요.","= 뒤의 7이 몫이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#8','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C6',1,'sa','auto','곱셈구구를 이용해 15 ÷ 3의 몫을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C6","difficulty":1,"kind":"sa","stem":"곱셈구구를 이용해 15 ÷ 3의 몫을 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["3 × □ = 15가 되는 □를 찾아요.","3단: … 3 × 5 = 15.","그래서 15 ÷ 3 = 5예요."],"variant_rule":{"alt":[{"stem":"곱셈구구를 이용해 6 ÷ 2의 몫을 구하세요. 숫자로 쓰세요.","answer":["3"],"explanation":["2 × □ = 6이 되는 □를 찾아요.","2단: … 2 × 3 = 6.","그래서 6 ÷ 2 = 3이에요."],"asset":null},{"stem":"곱셈구구를 이용해 27 ÷ 3의 몫을 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["3 × □ = 27이 되는 □를 찾아요.","3단: … 3 × 9 = 27.","그래서 27 ÷ 3 = 9예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#9','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C1',2,'ox','auto','색종이 8장을 4명에게 차례로 1·2·3·2장을 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":9,"concept":"M3-1-u3-C1","difficulty":2,"kind":"ox","stem":"색종이 8장을 4명에게 차례로 1·2·3·2장을 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"mis":"M3-1-u3-X01","explanation":["모두 더하면 8장 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 1·2·3·2장으로 달라요.","똑같이 나누려면 4명 모두 2장씩 받아야 해요."],"variant_rule":{"alt":[{"stem":"구슬 20개를 4명에게 차례로 4·6·5·5개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 20개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 4·6·5·5개로 달라요.","똑같이 나누려면 4명 모두 5개씩 받아야 해요."],"asset":null},{"stem":"카드 10장을 2명에게 차례로 4·6장을 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 10장 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 4·6장으로 달라요.","똑같이 나누려면 2명 모두 5장씩 받아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#10','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C2',2,'mc','auto','카드 10장을 상자 2개에 똑같이 나누어 담으면 한 상자에 몇 장씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":10,"concept":"M3-1-u3-C2","difficulty":2,"kind":"mc","stem":"카드 10장을 상자 2개에 똑같이 나누어 담으면 한 상자에 몇 장씩인가요?","options":[{"t":"5장","correct":true},{"t":"2장","mis":"M3-1-u3-X02"},{"t":"8장","mis":"M3-1-u3-X07"},{"t":"6장","mis":"M3-1-u3-X11"}],"explanation":["10장을 상자 2개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","2묶음으로 똑같이 나누니 2 × □ = 10에서 □ = 5예요.","한 상자에 5장이에요."],"variant_rule":{"alt":[{"stem":"지우개 28개를 바구니 4개에 똑같이 나누어 담으면 한 바구니에 몇 개씩인가요?","options":[{"t":"7개","correct":true},{"t":"4개","mis":"M3-1-u3-X02"},{"t":"24개","mis":"M3-1-u3-X07"},{"t":"8개","mis":"M3-1-u3-X11"}],"explanation":["28개를 바구니 4개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","4묶음으로 똑같이 나누니 4 × □ = 28에서 □ = 7이에요.","한 바구니에 7개예요."],"asset":null},{"stem":"클립 48개를 친구 8명에게 똑같이 나누어 주면 한 명에게 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"8개","mis":"M3-1-u3-X02"},{"t":"40개","mis":"M3-1-u3-X07"},{"t":"7개","mis":"M3-1-u3-X11"}],"explanation":["48개를 친구 8명에게 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","8묶음으로 똑같이 나누니 8 × □ = 48에서 □ = 6이에요.","한 명에게 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#11','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C3',2,'mc','auto','색종이 10장을 한 바구니에 2장씩 담으면 몇 바구니가 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":11,"concept":"M3-1-u3-C3","difficulty":2,"kind":"mc","stem":"색종이 10장을 한 바구니에 2장씩 담으면 몇 바구니가 되나요?","options":[{"t":"5바구니","correct":true},{"t":"2바구니","mis":"M3-1-u3-X02"},{"t":"8바구니","mis":"M3-1-u3-X07"},{"t":"6바구니","mis":"M3-1-u3-X11"}],"explanation":["10장에서 2장씩 덜어 내요.","2 × □ = 10에서 □ = 5 — 5번 덜어 낼 수 있어요.","그래서 5바구니예요."],"variant_rule":{"alt":[{"stem":"구슬 20개를 한 컵에 5개씩 담으면 몇 컵이 되나요?","options":[{"t":"4컵","correct":true},{"t":"5컵","mis":"M3-1-u3-X02"},{"t":"15컵","mis":"M3-1-u3-X07"},{"t":"3컵","mis":"M3-1-u3-X11"}],"explanation":["20개에서 5개씩 덜어 내요.","5 × □ = 20에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4컵이에요."],"asset":null},{"stem":"카드 18장을 한 주머니에 9장씩 담으면 몇 주머니가 되나요?","options":[{"t":"2주머니","correct":true},{"t":"9주머니","mis":"M3-1-u3-X02"},{"t":"3주머니","mis":"M3-1-u3-X11"},{"t":"1주머니","mis":"M3-1-u3-X11"}],"explanation":["18장에서 9장씩 덜어 내요.","9 × □ = 18에서 □ = 2 — 2번 덜어 낼 수 있어요.","그래서 2주머니예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#12','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C4',2,'mc','auto','지우개 40개를 5명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X03','M3-1-u3-X13']::text[],true,'{"seq":12,"concept":"M3-1-u3-C4","difficulty":2,"kind":"mc","stem":"지우개 40개를 5명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"40 ÷ 5","correct":true},{"t":"5 ÷ 40","mis":"M3-1-u3-X05"},{"t":"40 ÷ 8","mis":"M3-1-u3-X03"},{"t":"40 × 5","mis":"M3-1-u3-X13"}],"explanation":["전체 40개를 5명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 40 ÷ 5.","40 ÷ 5 = 8 — 한 명이 8개씩 받아요."],"variant_rule":{"alt":[{"stem":"클립 21개를 7명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"21 ÷ 7","correct":true},{"t":"7 ÷ 21","mis":"M3-1-u3-X05"},{"t":"21 ÷ 3","mis":"M3-1-u3-X03"},{"t":"21 × 7","mis":"M3-1-u3-X13"}],"explanation":["전체 21개를 7명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 21 ÷ 7.","21 ÷ 7 = 3 — 한 명이 3개씩 받아요."],"asset":null},{"stem":"귤 27개를 3명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"27 ÷ 3","correct":true},{"t":"3 ÷ 27","mis":"M3-1-u3-X05"},{"t":"27 ÷ 9","mis":"M3-1-u3-X03"},{"t":"27 × 3","mis":"M3-1-u3-X13"}],"explanation":["전체 27개를 3명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 27 ÷ 3.","27 ÷ 3 = 9 — 한 명이 9개씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#13','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C5',2,'mc','auto','7 × 2 = 14를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X08']::text[],true,'{"seq":13,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"7 × 2 = 14를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"14 ÷ 7 = 2","correct":true},{"t":"7 ÷ 14 = 2","mis":"M3-1-u3-X05"},{"t":"14 ÷ 7 = 7","mis":"M3-1-u3-X08"},{"t":"14 ÷ 8 = 2","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 7 × 2 = 14에서 곱 14가 나누어지는 수가 돼요.","14를 7로 나누면 2 — 14 ÷ 7 = 2.","같은 세 수 7, 2, 14만 써요."],"variant_rule":{"alt":[{"stem":"9 × 6 = 54를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"54 ÷ 9 = 6","correct":true},{"t":"9 ÷ 54 = 6","mis":"M3-1-u3-X05"},{"t":"54 ÷ 9 = 45","mis":"M3-1-u3-X08"},{"t":"54 ÷ 10 = 6","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 9 × 6 = 54에서 곱 54가 나누어지는 수가 돼요.","54를 9로 나누면 6 — 54 ÷ 9 = 6.","같은 세 수 9, 6, 54만 써요."],"asset":null},{"stem":"5 × 2 = 10을 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"10 ÷ 5 = 2","correct":true},{"t":"5 ÷ 10 = 2","mis":"M3-1-u3-X05"},{"t":"10 ÷ 5 = 5","mis":"M3-1-u3-X08"},{"t":"10 ÷ 6 = 2","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 5 × 2 = 10에서 곱 10이 나누어지는 수가 돼요.","10을 5로 나누면 2 — 10 ÷ 5 = 2.","같은 세 수 5, 2, 10만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#14','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C5',2,'mc','auto','풍선을 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?',ARRAY['M3-1-u3-X09','M3-1-u3-X11','M3-1-u3-X13']::text[],true,'{"seq":14,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"풍선을 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 7 = 14","correct":true},{"t":"2 × 8 = 16","mis":"M3-1-u3-X09"},{"t":"2 × 7 = 16","mis":"M3-1-u3-X11"},{"t":"2 + 7 = 9","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2개씩, 줄은 7줄이에요.","2씩 7줄이니 2 × 7.","2 × 7 = 14 — 모두 14개."],"asset":{"type":"mul_groups","item":"🎈","k":2,"n":7,"look":"rows"},"variant_rule":{"alt":[{"stem":"별 스티커를 한 줄에 3장씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"3 × 8 = 24","correct":true},{"t":"3 × 9 = 27","mis":"M3-1-u3-X09"},{"t":"3 × 8 = 27","mis":"M3-1-u3-X11"},{"t":"3 + 8 = 11","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 3장씩, 줄은 8줄이에요.","3씩 8줄이니 3 × 8.","3 × 8 = 24 — 모두 24장."],"asset":{"type":"mul_groups","item":"⭐","k":3,"n":8,"look":"rows"}},{"stem":"컵케이크를 한 줄에 6개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"6 × 3 = 18","correct":true},{"t":"6 × 4 = 24","mis":"M3-1-u3-X09"},{"t":"6 × 3 = 24","mis":"M3-1-u3-X11"},{"t":"6 + 3 = 9","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 6개씩, 줄은 3줄이에요.","6씩 3줄이니 6 × 3.","6 × 3 = 18 — 모두 18개."],"asset":{"type":"mul_groups","item":"🧁","k":6,"n":3,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#15','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C6',2,'mc','auto','42 ÷ 7 = 6이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M3-1-u3-X12','M3-1-u3-X13']::text[],true,'{"seq":15,"concept":"M3-1-u3-C6","difficulty":2,"kind":"mc","stem":"42 ÷ 7 = 6이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"7 × 6 = 42","correct":true},{"t":"6 × 42 = □","mis":"M3-1-u3-X12"},{"t":"42 × 7 = □","mis":"M3-1-u3-X12"},{"t":"7 + 6 = 13","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","7 × 6 = 42예요.","그래서 42 ÷ 7 = 6은 맞아요."],"variant_rule":{"alt":[{"stem":"12 ÷ 3 = 4가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"3 × 4 = 12","correct":true},{"t":"4 × 12 = □","mis":"M3-1-u3-X12"},{"t":"12 × 3 = □","mis":"M3-1-u3-X12"},{"t":"3 + 4 = 7","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","3 × 4 = 12예요.","그래서 12 ÷ 3 = 4는 맞아요."],"asset":null},{"stem":"27 ÷ 9 = 3이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"9 × 3 = 27","correct":true},{"t":"3 × 27 = □","mis":"M3-1-u3-X12"},{"t":"27 × 9 = □","mis":"M3-1-u3-X12"},{"t":"9 + 3 = 12","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","9 × 3 = 27이에요.","그래서 27 ÷ 9 = 3은 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#16','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C7',2,'mc','auto','당근 20개를 한 상자에 5개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":16,"concept":"M3-1-u3-C7","difficulty":2,"kind":"mc","stem":"당근 20개를 한 상자에 5개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?","options":[{"t":"4상자","correct":true},{"t":"5상자","mis":"M3-1-u3-X02"},{"t":"15상자","mis":"M3-1-u3-X07"},{"t":"3상자","mis":"M3-1-u3-X11"}],"explanation":["한 상자에 5개씩 — 몇 번 담을 수 있는지 구해요.","20 ÷ 5 = 4 (5 × 4 = 20).","4상자가 필요해요."],"variant_rule":{"alt":[{"stem":"물고기 14마리를 한 접시에 2마리씩 담아 나눔 장터에 내놓으려고 해요. 몇 접시가 필요한가요?","options":[{"t":"7접시","correct":true},{"t":"2접시","mis":"M3-1-u3-X02"},{"t":"12접시","mis":"M3-1-u3-X07"},{"t":"8접시","mis":"M3-1-u3-X11"}],"explanation":["한 접시에 2마리씩 — 몇 번 담을 수 있는지 구해요.","14 ÷ 2 = 7 (2 × 7 = 14).","7접시가 필요해요."],"asset":null},{"stem":"사탕 36개를 한 바구니에 9개씩 담아 나눔 장터에 내놓으려고 해요. 몇 바구니가 필요한가요?","options":[{"t":"4바구니","correct":true},{"t":"9바구니","mis":"M3-1-u3-X02"},{"t":"27바구니","mis":"M3-1-u3-X07"},{"t":"5바구니","mis":"M3-1-u3-X11"}],"explanation":["한 바구니에 9개씩 — 몇 번 담을 수 있는지 구해요.","36 ÷ 9 = 4 (9 × 4 = 36).","4바구니가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#17','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C3',3,'sa','auto','6에서 2씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 2씩 몇 번 뛰었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M3-1-u3-C3","difficulty":3,"kind":"sa","stem":"6에서 2씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 2씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["화살표 하나가 2씩 한 번 덜어 낸 거예요.","화살표를 세면 3개 — ?는 0이에요.","6은 2씩 3번 덜어 내면 0 — 3묶음이에요."],"asset":{"type":"jump_row","cells":[6,4,2,null],"step":2,"dir":"down"},"variant_rule":{"alt":[{"stem":"12에서 3씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 3씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 3씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","12는 3씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[12,9,6,3,null],"step":3,"dir":"down"}},{"stem":"15에서 3씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 3씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["5"],"explanation":["화살표 하나가 3씩 한 번 덜어 낸 거예요.","화살표를 세면 5개 — ?는 0이에요.","15는 3씩 5번 덜어 내면 0 — 5묶음이에요."],"asset":{"type":"jump_row","cells":[15,12,9,6,3,null],"step":3,"dir":"down"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#18','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C4',3,'ox','auto','15 ÷ 3과 3 ÷ 15는 같은 식이에요.',ARRAY['M3-1-u3-X05']::text[],true,'{"seq":18,"concept":"M3-1-u3-C4","difficulty":3,"kind":"ox","stem":"15 ÷ 3과 3 ÷ 15는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"mis":"M3-1-u3-X05","explanation":["15 ÷ 3은 「15를 3으로 나누기」예요.","3 ÷ 15는 작은 3을 큰 15로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"variant_rule":{"alt":[{"stem":"63 ÷ 9와 9 ÷ 63은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["63 ÷ 9는 「63을 9로 나누기」예요.","9 ÷ 63은 작은 9를 큰 63으로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null},{"stem":"12 ÷ 3과 3 ÷ 12는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["12 ÷ 3은 「12를 3으로 나누기」예요.","3 ÷ 12는 작은 3을 큰 12로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#19','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C5',3,'mc','auto','6 × 7 = 42와 한 가족인 식이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":19,"concept":"M3-1-u3-C5","difficulty":3,"kind":"mc","stem":"6 × 7 = 42와 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"48 ÷ 6 = 8","correct":true},{"t":"7 × 6 = 42","mis":"M3-1-u3-X15"},{"t":"42 ÷ 6 = 7","mis":"M3-1-u3-X15"},{"t":"42 ÷ 7 = 6","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 6, 7, 42로 만든 식이에요.","곱셈 2개(6 × 7, 7 × 6), 나눗셈 2개(42 ÷ 6, 42 ÷ 7).","48 ÷ 6 = 8은 다른 수가 들어 있어 한 가족이 아니에요."],"variant_rule":{"alt":[{"stem":"7 × 9 = 63과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"70 ÷ 7 = 10","correct":true},{"t":"9 × 7 = 63","mis":"M3-1-u3-X15"},{"t":"63 ÷ 7 = 9","mis":"M3-1-u3-X15"},{"t":"63 ÷ 9 = 7","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 7, 9, 63으로 만든 식이에요.","곱셈 2개(7 × 9, 9 × 7), 나눗셈 2개(63 ÷ 7, 63 ÷ 9).","70 ÷ 7 = 10은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null},{"stem":"2 × 8 = 16과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"16 ÷ 4 = 4","correct":true},{"t":"8 × 2 = 16","mis":"M3-1-u3-X15"},{"t":"16 ÷ 2 = 8","mis":"M3-1-u3-X15"},{"t":"16 ÷ 8 = 2","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 2, 8, 16으로 만든 식이에요.","곱셈 2개(2 × 8, 8 × 2), 나눗셈 2개(16 ÷ 2, 16 ÷ 8).","16 ÷ 4 = 4는 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#20','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C6',3,'sa','auto','□ ÷ 9 = 5 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-1-u3-C6","difficulty":3,"kind":"sa","stem":"□ ÷ 9 = 5 — □에 알맞은 수를 쓰세요.","answer":["45"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","9 × 5 = 45예요.","□ = 45 — 45 ÷ 9 = 5로 확인해요."],"variant_rule":{"alt":[{"stem":"□ ÷ 4 = 6 — □에 알맞은 수를 쓰세요.","answer":["24"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 6 = 24예요.","□ = 24 — 24 ÷ 4 = 6으로 확인해요."],"asset":null},{"stem":"□ ÷ 6 = 8 — □에 알맞은 수를 쓰세요.","answer":["48"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","6 × 8 = 48이에요.","□ = 48 — 48 ÷ 6 = 8로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#21','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C7',3,'mc','auto','나눔 장터에서 공책 72권을 9명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.',ARRAY['M3-1-u3-X03','M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":21,"concept":"M3-1-u3-C7","difficulty":3,"kind":"mc","stem":"나눔 장터에서 공책 72권을 9명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"72 ÷ 9 = 8, 8권씩","correct":true},{"t":"72 ÷ 8 = 9, 9권씩","mis":"M3-1-u3-X03"},{"t":"72 − 9 = 63, 63권씩","mis":"M3-1-u3-X13"},{"t":"72 ÷ 9 = 9, 9권씩","mis":"M3-1-u3-X11"}],"explanation":["9명에게 똑같이 나누니 나누는 수는 사람 수 9예요.","72 ÷ 9 — 9 × 8 = 72.","한 명이 8권씩 받아요."],"variant_rule":{"alt":[{"stem":"나눔 장터에서 연필 48자루를 6명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"48 ÷ 6 = 8, 8자루씩","correct":true},{"t":"48 ÷ 8 = 6, 6자루씩","mis":"M3-1-u3-X03"},{"t":"48 − 6 = 42, 42자루씩","mis":"M3-1-u3-X13"},{"t":"48 ÷ 6 = 9, 9자루씩","mis":"M3-1-u3-X11"}],"explanation":["6명에게 똑같이 나누니 나누는 수는 사람 수 6이에요.","48 ÷ 6 — 6 × 8 = 48.","한 명이 8자루씩 받아요."],"asset":null},{"stem":"나눔 장터에서 색종이 40장을 8명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"40 ÷ 8 = 5, 5장씩","correct":true},{"t":"40 ÷ 5 = 8, 8장씩","mis":"M3-1-u3-X03"},{"t":"40 − 8 = 32, 32장씩","mis":"M3-1-u3-X13"},{"t":"40 ÷ 8 = 6, 6장씩","mis":"M3-1-u3-X11"}],"explanation":["8명에게 똑같이 나누니 나누는 수는 사람 수 8이에요.","40 ÷ 8 — 8 × 5 = 40.","한 명이 5장씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#22','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C8',3,'mc','auto','사탕 12개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":22,"concept":"M3-1-u3-C8","difficulty":3,"kind":"mc","stem":"사탕 12개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"6명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"3명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"2명에게 6개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 12가 있으면 남김없이 나눌 수 있어요.","6명에게 2개씩, 3명에게 4개씩, 2명에게 6개씩 — 모두 곱셈구구로 12가 돼요.","5단에는 12가 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"사탕 18개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"3명에게 6개씩","mis":"M3-1-u3-X15"},{"t":"9명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"6명에게 3개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 18이 있으면 남김없이 나눌 수 있어요.","3명에게 6개씩, 9명에게 2개씩, 6명에게 3개씩 — 모두 곱셈구구로 18이 돼요.","5단에는 18이 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null},{"stem":"사탕 16개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"6명에게 똑같이","correct":true},{"t":"4명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"8명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"2명에게 8개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 16이 있으면 남김없이 나눌 수 있어요.","4명에게 4개씩, 8명에게 2개씩, 2명에게 8개씩 — 모두 곱셈구구로 16이 돼요.","6단에는 16이 없어서 6명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#23','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C6',4,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":23,"concept":"M3-1-u3-C6","difficulty":4,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"18 ÷ 2","correct":true},{"t":"54 ÷ 9","mis":"M3-1-u3-X13"},{"t":"8 ÷ 2","mis":"M3-1-u3-X11"},{"t":"48 ÷ 6","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","54 ÷ 9 = 6, 8 ÷ 2 = 4, 18 ÷ 2 = 9, 48 ÷ 6 = 8.","몫이 가장 큰 것은 18 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"21 ÷ 3","correct":true},{"t":"54 ÷ 9","mis":"M3-1-u3-X13"},{"t":"14 ÷ 7","mis":"M3-1-u3-X11"},{"t":"12 ÷ 3","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","54 ÷ 9 = 6, 14 ÷ 7 = 2, 12 ÷ 3 = 4, 21 ÷ 3 = 7.","몫이 가장 큰 것은 21 ÷ 3 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"56 ÷ 7","correct":true},{"t":"18 ÷ 6","mis":"M3-1-u3-X11"},{"t":"8 ÷ 2","mis":"M3-1-u3-X11"},{"t":"35 ÷ 5","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","18 ÷ 6 = 3, 8 ÷ 2 = 4, 35 ÷ 5 = 7, 56 ÷ 7 = 8.","몫이 가장 큰 것은 56 ÷ 7 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#24','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C7',4,'sa','auto','연필 24자루를 3명에게 똑같이 나누어 주었어요. 한 명이 받은 연필을 다시 2자루씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-1-u3-C7","difficulty":4,"kind":"sa","stem":"연필 24자루를 3명에게 똑같이 나누어 주었어요. 한 명이 받은 연필을 다시 2자루씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 한 명이 받은 수: 24 ÷ 3 = 8.","그다음 8을 2자루씩 담아요: 8 ÷ 2 = 4.","그래서 4봉지예요."],"variant_rule":{"alt":[{"stem":"색종이 24장을 4명에게 똑같이 나누어 주었어요. 한 명이 받은 색종이를 다시 3장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 한 명이 받은 수: 24 ÷ 4 = 6.","그다음 6을 3장씩 담아요: 6 ÷ 3 = 2.","그래서 2봉지예요."],"asset":null},{"stem":"귤 18개를 2명에게 똑같이 나누어 주었어요. 한 명이 받은 귤을 다시 3개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 18 ÷ 2 = 9.","그다음 9를 3개씩 담아요: 9 ÷ 3 = 3.","그래서 3봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_a#25','math',3,1,'u3','','g3_1_math_u3_review_a','unit_review','M3-1-u3-C7',4,'essay','teacher','나눔 장터에서 공책 32권을 한 모둠에 8권씩 나누어 주려고 해요. 나눗셈식을 세워 몇 모둠에 줄 수 있는지 구하고, 곱셈으로 확인해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u3-C7","difficulty":4,"kind":"essay","stem":"나눔 장터에서 공책 32권을 한 모둠에 8권씩 나누어 주려고 해요. 나눗셈식을 세워 몇 모둠에 줄 수 있는지 구하고, 곱셈으로 확인해 보세요.","answer_guide":{"answer":"예: 32권에서 8권씩 덜어 내므로 32 ÷ 8이다. 8 × 4 = 32이므로 몫은 4, 4모둠에 줄 수 있다. 확인: 8 × 4 = 32.","scoring_points":["32 ÷ 8로 식을 세웠는가","몫 4(4모둠)를 구했는가","8 × 4 = 32로 확인했는가"]},"explanation":["8권씩 덜어 내니 32 ÷ 8.","8 × 4 = 32 — 4모둠.","확인 8 × 4 = 32."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#1','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C1',1,'mc','auto','별 스티커 10장을 나누었어요. 똑같이 나눈 것은 어느 것인가요?',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":1,"concept":"M3-1-u3-C1","difficulty":1,"kind":"mc","stem":"별 스티커 10장을 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"2명에게 5장씩","correct":true},{"t":"2명에게 8·2장","mis":"M3-1-u3-X01"},{"t":"3명에게 3·2·5장","mis":"M3-1-u3-X01"},{"t":"4명에게 3·4·1·2장","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","2명이 모두 5장씩 받으면 2 × 5 = 10장 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"variant_rule":{"alt":[{"stem":"컵케이크 45개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"9명에게 5개씩","correct":true},{"t":"9명에게 7·5·4·6·1·7·8·5·2개","mis":"M3-1-u3-X01"},{"t":"8명에게 4·1·9·4·9·8·2·8개","mis":"M3-1-u3-X01"},{"t":"8명에게 2·4·2·6·8·9·8·6개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","9명이 모두 5개씩 받으면 9 × 5 = 45개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null},{"stem":"도넛 56개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"8명에게 7개씩","correct":true},{"t":"8명에게 7·2·8·8·8·6·9·8개","mis":"M3-1-u3-X01"},{"t":"9명에게 8·8·5·7·3·7·6·3·9개","mis":"M3-1-u3-X01"},{"t":"7명에게 7·9·9·9·8·6·8개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","8명이 모두 7개씩 받으면 8 × 7 = 56개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#2','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C2',1,'mc','auto','별 스티커 24장을 접시 4개에 똑같이 나누었어요. 한 접시에 몇 장씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":2,"concept":"M3-1-u3-C2","difficulty":1,"kind":"mc","stem":"별 스티커 24장을 접시 4개에 똑같이 나누었어요. 한 접시에 몇 장씩인가요?","options":[{"t":"6장","correct":true},{"t":"4장","mis":"M3-1-u3-X02"},{"t":"20장","mis":"M3-1-u3-X07"},{"t":"7장","mis":"M3-1-u3-X11"}],"explanation":["별 스티커 24장을 접시 4개에 하나씩 번갈아 놓았어요.","묶음마다 6장씩 똑같이 있어요.","그래서 한 접시에 6장이에요."],"asset":{"type":"mul_groups","item":"⭐","k":6,"n":4},"variant_rule":{"alt":[{"stem":"컵케이크 24개를 모둠 6개에 똑같이 나누었어요. 한 모둠에 몇 개씩인가요?","options":[{"t":"4개","correct":true},{"t":"6개","mis":"M3-1-u3-X02"},{"t":"18개","mis":"M3-1-u3-X07"},{"t":"5개","mis":"M3-1-u3-X11"}],"explanation":["컵케이크 24개를 모둠 6개에 하나씩 번갈아 놓았어요.","묶음마다 4개씩 똑같이 있어요.","그래서 한 모둠에 4개예요."],"asset":{"type":"mul_groups","item":"🧁","k":4,"n":6}},{"stem":"도넛 42개를 봉지 7개에 똑같이 나누었어요. 한 봉지에 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"7개","mis":"M3-1-u3-X02"},{"t":"35개","mis":"M3-1-u3-X07"},{"t":"5개","mis":"M3-1-u3-X11"}],"explanation":["도넛 42개를 봉지 7개에 하나씩 번갈아 놓았어요.","묶음마다 6개씩 똑같이 있어요.","그래서 한 봉지에 6개예요."],"asset":{"type":"mul_groups","item":"🍩","k":6,"n":7}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#3','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C2',1,'sa','auto','연필 35자루를 봉지 7개에 똑같이 나누어 담으면 한 봉지에 몇 자루씩인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C2","difficulty":1,"kind":"sa","stem":"연필 35자루를 봉지 7개에 똑같이 나누어 담으면 한 봉지에 몇 자루씩인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["35자루를 봉지 7개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","7묶음으로 똑같이 나누니 7 × □ = 35에서 □ = 5예요.","한 봉지에 5자루예요."],"variant_rule":{"alt":[{"stem":"색종이 24장을 상자 6개에 똑같이 나누어 담으면 한 상자에 몇 장씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["24장을 상자 6개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","6묶음으로 똑같이 나누니 6 × □ = 24에서 □ = 4예요.","한 상자에 4장이에요."],"asset":null},{"stem":"구슬 16개를 바구니 8개에 똑같이 나누어 담으면 한 바구니에 몇 개씩인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["16개를 바구니 8개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","8묶음으로 똑같이 나누니 8 × □ = 16에서 □ = 2예요.","한 바구니에 2개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#4','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C3',1,'mc','auto','쿠키 8개를 2개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":4,"concept":"M3-1-u3-C3","difficulty":1,"kind":"mc","stem":"쿠키 8개를 2개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"4묶음","correct":true},{"t":"2묶음","mis":"M3-1-u3-X02"},{"t":"6묶음","mis":"M3-1-u3-X07"},{"t":"5묶음","mis":"M3-1-u3-X11"}],"explanation":["2개씩 묶은 테두리를 세어요.","2씩 4번 덜어 내면 8개 모두 덜어 내져요 — 2 × 4 = 8.","그래서 4묶음이에요."],"asset":{"type":"mul_groups","item":"🍪","k":2,"n":4},"variant_rule":{"alt":[{"stem":"딸기 30개를 5개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"6묶음","correct":true},{"t":"5묶음","mis":"M3-1-u3-X02"},{"t":"25묶음","mis":"M3-1-u3-X07"},{"t":"7묶음","mis":"M3-1-u3-X11"}],"explanation":["5개씩 묶은 테두리를 세어요.","5씩 6번 덜어 내면 30개 모두 덜어 내져요 — 5 × 6 = 30.","그래서 6묶음이에요."],"asset":{"type":"mul_groups","item":"🍓","k":5,"n":6}},{"stem":"풍선 42개를 7개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"6묶음","correct":true},{"t":"7묶음","mis":"M3-1-u3-X02"},{"t":"35묶음","mis":"M3-1-u3-X07"},{"t":"5묶음","mis":"M3-1-u3-X11"}],"explanation":["7개씩 묶은 테두리를 세어요.","7씩 6번 덜어 내면 42개 모두 덜어 내져요 — 7 × 6 = 42.","그래서 6묶음이에요."],"asset":{"type":"mul_groups","item":"🎈","k":7,"n":6}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#5','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C3',1,'sa','auto','27 − 3 − 3 − 3 − 3 − 3 − 3 − 3 − 3 − 3 = 0에서 3을 몇 번 뺐나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C3","difficulty":1,"kind":"sa","stem":"27 − 3 − 3 − 3 − 3 − 3 − 3 − 3 − 3 − 3 = 0에서 3을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["9"],"explanation":["빼는 수 3이 몇 개인지 세어요.","27 − 3을 9번 하면 0이 돼요.","27은 3씩 9묶음으로 덜어 낼 수 있어요."],"variant_rule":{"alt":[{"stem":"28 − 7 − 7 − 7 − 7 = 0에서 7을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["4"],"explanation":["빼는 수 7이 몇 개인지 세어요.","28 − 7을 4번 하면 0이 돼요.","28은 7씩 4묶음으로 덜어 낼 수 있어요."],"asset":null},{"stem":"16 − 2 − 2 − 2 − 2 − 2 − 2 − 2 − 2 = 0에서 2를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["8"],"explanation":["빼는 수 2가 몇 개인지 세어요.","16 − 2를 8번 하면 0이 돼요.","16은 2씩 8묶음으로 덜어 낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#6','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C4',1,'mc','auto','35 ÷ 5를 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-1-u3-X07','M3-1-u3-X05']::text[],true,'{"seq":6,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"35 ÷ 5를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"35 나누기 5","correct":true},{"t":"35 곱하기 5","mis":"M3-1-u3-X07"},{"t":"5 나누기 35","mis":"M3-1-u3-X05"},{"t":"35 빼기 5","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 35 나누기 5.","35 ÷ 5 = 7은 「35 나누기 5는 7」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"24 ÷ 4를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"24 나누기 4","correct":true},{"t":"24 곱하기 4","mis":"M3-1-u3-X07"},{"t":"4 나누기 24","mis":"M3-1-u3-X05"},{"t":"24 빼기 4","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 24 나누기 4.","24 ÷ 4 = 6은 「24 나누기 4는 6」이라고 읽어요."],"asset":null},{"stem":"8 ÷ 2를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"8 나누기 2","correct":true},{"t":"8 곱하기 2","mis":"M3-1-u3-X07"},{"t":"2 나누기 8","mis":"M3-1-u3-X05"},{"t":"8 빼기 2","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 8 나누기 2.","8 ÷ 2 = 4는 「8 나누기 2는 4」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#7','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C4',1,'mc','auto','28 ÷ 7 = 4에서 몫은 어느 것인가요?',ARRAY['M3-1-u3-X06']::text[],true,'{"seq":7,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"28 ÷ 7 = 4에서 몫은 어느 것인가요?","options":[{"t":"4","correct":true},{"t":"28","mis":"M3-1-u3-X06"},{"t":"7","mis":"M3-1-u3-X06"},{"t":"28과 7","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","28은 나누어지는 수, 7은 나누는 수예요.","= 뒤의 4가 몫이에요."],"variant_rule":{"alt":[{"stem":"32 ÷ 8 = 4에서 몫은 어느 것인가요?","options":[{"t":"4","correct":true},{"t":"32","mis":"M3-1-u3-X06"},{"t":"8","mis":"M3-1-u3-X06"},{"t":"32와 8","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","32는 나누어지는 수, 8은 나누는 수예요.","= 뒤의 4가 몫이에요."],"asset":null},{"stem":"16 ÷ 8 = 2에서 몫은 어느 것인가요?","options":[{"t":"2","correct":true},{"t":"16","mis":"M3-1-u3-X06"},{"t":"8","mis":"M3-1-u3-X06"},{"t":"16과 8","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","16은 나누어지는 수, 8은 나누는 수예요.","= 뒤의 2가 몫이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#8','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C6',1,'sa','auto','곱셈구구를 이용해 30 ÷ 6의 몫을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C6","difficulty":1,"kind":"sa","stem":"곱셈구구를 이용해 30 ÷ 6의 몫을 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["6 × □ = 30이 되는 □를 찾아요.","6단: … 6 × 5 = 30.","그래서 30 ÷ 6 = 5예요."],"variant_rule":{"alt":[{"stem":"곱셈구구를 이용해 72 ÷ 9의 몫을 구하세요. 숫자로 쓰세요.","answer":["8"],"explanation":["9 × □ = 72가 되는 □를 찾아요.","9단: … 9 × 8 = 72.","그래서 72 ÷ 9 = 8이에요."],"asset":null},{"stem":"곱셈구구를 이용해 8 ÷ 4의 몫을 구하세요. 숫자로 쓰세요.","answer":["2"],"explanation":["4 × □ = 8이 되는 □를 찾아요.","4단: … 4 × 2 = 8.","그래서 8 ÷ 4 = 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#9','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C1',2,'ox','auto','구슬 18개를 6명에게 차례로 2·3·3·3·3·4개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":9,"concept":"M3-1-u3-C1","difficulty":2,"kind":"ox","stem":"구슬 18개를 6명에게 차례로 2·3·3·3·3·4개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"mis":"M3-1-u3-X01","explanation":["모두 더하면 18개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 2·3·3·3·3·4개로 달라요.","똑같이 나누려면 6명 모두 3개씩 받아야 해요."],"variant_rule":{"alt":[{"stem":"카드 54장을 6명에게 차례로 9·8·9·10·9·9장을 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 54장 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 9·8·9·10·9·9장으로 달라요.","똑같이 나누려면 6명 모두 9장씩 받아야 해요."],"asset":null},{"stem":"지우개 10개를 2명에게 차례로 4·6개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 10개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 4·6개로 달라요.","똑같이 나누려면 2명 모두 5개씩 받아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#10','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C2',2,'mc','auto','지우개 12개를 봉지 6개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X11']::text[],true,'{"seq":10,"concept":"M3-1-u3-C2","difficulty":2,"kind":"mc","stem":"지우개 12개를 봉지 6개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요?","options":[{"t":"2개","correct":true},{"t":"6개","mis":"M3-1-u3-X02"},{"t":"3개","mis":"M3-1-u3-X11"},{"t":"1개","mis":"M3-1-u3-X11"}],"explanation":["12개를 봉지 6개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","6묶음으로 똑같이 나누니 6 × □ = 12에서 □ = 2예요.","한 봉지에 2개예요."],"variant_rule":{"alt":[{"stem":"클립 32개를 상자 8개에 똑같이 나누어 담으면 한 상자에 몇 개씩인가요?","options":[{"t":"4개","correct":true},{"t":"8개","mis":"M3-1-u3-X02"},{"t":"24개","mis":"M3-1-u3-X07"},{"t":"5개","mis":"M3-1-u3-X11"}],"explanation":["32개를 상자 8개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","8묶음으로 똑같이 나누니 8 × □ = 32에서 □ = 4예요.","한 상자에 4개예요."],"asset":null},{"stem":"귤 54개를 바구니 9개에 똑같이 나누어 담으면 한 바구니에 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"9개","mis":"M3-1-u3-X02"},{"t":"45개","mis":"M3-1-u3-X07"},{"t":"7개","mis":"M3-1-u3-X11"}],"explanation":["54개를 바구니 9개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","9묶음으로 똑같이 나누니 9 × □ = 54에서 □ = 6이에요.","한 바구니에 6개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#11','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C3',2,'mc','auto','구슬 35개를 한 접시에 5개씩 담으면 몇 접시가 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":11,"concept":"M3-1-u3-C3","difficulty":2,"kind":"mc","stem":"구슬 35개를 한 접시에 5개씩 담으면 몇 접시가 되나요?","options":[{"t":"7접시","correct":true},{"t":"5접시","mis":"M3-1-u3-X02"},{"t":"30접시","mis":"M3-1-u3-X07"},{"t":"8접시","mis":"M3-1-u3-X11"}],"explanation":["35개에서 5개씩 덜어 내요.","5 × □ = 35에서 □ = 7 — 7번 덜어 낼 수 있어요.","그래서 7접시예요."],"variant_rule":{"alt":[{"stem":"카드 16장을 한 바구니에 2장씩 담으면 몇 바구니가 되나요?","options":[{"t":"8바구니","correct":true},{"t":"2바구니","mis":"M3-1-u3-X02"},{"t":"14바구니","mis":"M3-1-u3-X07"},{"t":"9바구니","mis":"M3-1-u3-X11"}],"explanation":["16장에서 2장씩 덜어 내요.","2 × □ = 16에서 □ = 8 — 8번 덜어 낼 수 있어요.","그래서 8바구니예요."],"asset":null},{"stem":"지우개 14개를 한 컵에 7개씩 담으면 몇 컵이 되나요?","options":[{"t":"2컵","correct":true},{"t":"7컵","mis":"M3-1-u3-X02"},{"t":"3컵","mis":"M3-1-u3-X11"},{"t":"1컵","mis":"M3-1-u3-X11"}],"explanation":["14개에서 7개씩 덜어 내요.","7 × □ = 14에서 □ = 2 — 2번 덜어 낼 수 있어요.","그래서 2컵이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#12','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C4',2,'mc','auto','공책 48권을 한 주머니에 8권씩 담으려고 해요. 몇 주머니가 되는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X03','M3-1-u3-X13']::text[],true,'{"seq":12,"concept":"M3-1-u3-C4","difficulty":2,"kind":"mc","stem":"공책 48권을 한 주머니에 8권씩 담으려고 해요. 몇 주머니가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"48 ÷ 8","correct":true},{"t":"8 ÷ 48","mis":"M3-1-u3-X05"},{"t":"48 ÷ 6","mis":"M3-1-u3-X03"},{"t":"48 − 8","mis":"M3-1-u3-X13"}],"explanation":["48권에서 8권씩 덜어 내는 상황이에요.","전체 48을 앞에, 한 주머니 개수 8을 뒤에 — 48 ÷ 8.","48 ÷ 8 = 6 — 6주머니예요."],"variant_rule":{"alt":[{"stem":"연필 32자루를 한 봉지에 4자루씩 담으려고 해요. 몇 봉지가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"32 ÷ 4","correct":true},{"t":"4 ÷ 32","mis":"M3-1-u3-X05"},{"t":"32 ÷ 8","mis":"M3-1-u3-X03"},{"t":"32 − 4","mis":"M3-1-u3-X13"}],"explanation":["32자루에서 4자루씩 덜어 내는 상황이에요.","전체 32를 앞에, 한 봉지 개수 4를 뒤에 — 32 ÷ 4.","32 ÷ 4 = 8 — 8봉지예요."],"asset":null},{"stem":"색종이 48장을 한 상자에 6장씩 담으려고 해요. 몇 상자가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"48 ÷ 6","correct":true},{"t":"6 ÷ 48","mis":"M3-1-u3-X05"},{"t":"48 ÷ 8","mis":"M3-1-u3-X03"},{"t":"48 − 6","mis":"M3-1-u3-X13"}],"explanation":["48장에서 6장씩 덜어 내는 상황이에요.","전체 48을 앞에, 한 상자 개수 6을 뒤에 — 48 ÷ 6.","48 ÷ 6 = 8 — 8상자예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#13','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C5',2,'mc','auto','2 × 7 = 14를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X08']::text[],true,'{"seq":13,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"2 × 7 = 14를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"14 ÷ 2 = 7","correct":true},{"t":"2 ÷ 14 = 7","mis":"M3-1-u3-X05"},{"t":"14 ÷ 2 = 12","mis":"M3-1-u3-X08"},{"t":"14 ÷ 3 = 7","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 2 × 7 = 14에서 곱 14가 나누어지는 수가 돼요.","14를 2로 나누면 7 — 14 ÷ 2 = 7.","같은 세 수 2, 7, 14만 써요."],"variant_rule":{"alt":[{"stem":"9 × 6 = 54를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"54 ÷ 9 = 6","correct":true},{"t":"9 ÷ 54 = 6","mis":"M3-1-u3-X05"},{"t":"54 ÷ 9 = 45","mis":"M3-1-u3-X08"},{"t":"54 ÷ 10 = 6","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 9 × 6 = 54에서 곱 54가 나누어지는 수가 돼요.","54를 9로 나누면 6 — 54 ÷ 9 = 6.","같은 세 수 9, 6, 54만 써요."],"asset":null},{"stem":"5 × 3 = 15를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"15 ÷ 5 = 3","correct":true},{"t":"5 ÷ 15 = 3","mis":"M3-1-u3-X05"},{"t":"15 ÷ 5 = 10","mis":"M3-1-u3-X08"},{"t":"15 ÷ 6 = 3","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 5 × 3 = 15에서 곱 15가 나누어지는 수가 돼요.","15를 5로 나누면 3 — 15 ÷ 5 = 3.","같은 세 수 5, 3, 15만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#14','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C5',2,'mc','auto','별 스티커를 한 줄에 2장씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?',ARRAY['M3-1-u3-X09','M3-1-u3-X11','M3-1-u3-X13']::text[],true,'{"seq":14,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"별 스티커를 한 줄에 2장씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 9 = 18","correct":true},{"t":"2 × 10 = 20","mis":"M3-1-u3-X09"},{"t":"2 × 9 = 20","mis":"M3-1-u3-X11"},{"t":"2 + 9 = 11","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2장씩, 줄은 9줄이에요.","2씩 9줄이니 2 × 9.","2 × 9 = 18 — 모두 18장."],"asset":{"type":"mul_groups","item":"⭐","k":2,"n":9,"look":"rows"},"variant_rule":{"alt":[{"stem":"컵케이크를 한 줄에 3개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"3 × 6 = 18","correct":true},{"t":"3 × 7 = 21","mis":"M3-1-u3-X09"},{"t":"3 × 6 = 21","mis":"M3-1-u3-X11"},{"t":"3 + 6 = 9","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 3개씩, 줄은 6줄이에요.","3씩 6줄이니 3 × 6.","3 × 6 = 18 — 모두 18개."],"asset":{"type":"mul_groups","item":"🧁","k":3,"n":6,"look":"rows"}},{"stem":"도넛을 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 3 = 6","correct":true},{"t":"2 × 4 = 8","mis":"M3-1-u3-X09"},{"t":"2 × 3 = 8","mis":"M3-1-u3-X11"},{"t":"2 + 3 = 5","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2개씩, 줄은 3줄이에요.","2씩 3줄이니 2 × 3.","2 × 3 = 6 — 모두 6개."],"asset":{"type":"mul_groups","item":"🍩","k":2,"n":3,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#15','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C6',2,'mc','auto','56 ÷ 7 = 8이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M3-1-u3-X12','M3-1-u3-X13']::text[],true,'{"seq":15,"concept":"M3-1-u3-C6","difficulty":2,"kind":"mc","stem":"56 ÷ 7 = 8이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"7 × 8 = 56","correct":true},{"t":"8 × 56 = □","mis":"M3-1-u3-X12"},{"t":"56 × 7 = □","mis":"M3-1-u3-X12"},{"t":"7 + 8 = 15","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","7 × 8 = 56이에요.","그래서 56 ÷ 7 = 8은 맞아요."],"variant_rule":{"alt":[{"stem":"32 ÷ 4 = 8이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"4 × 8 = 32","correct":true},{"t":"8 × 32 = □","mis":"M3-1-u3-X12"},{"t":"32 × 4 = □","mis":"M3-1-u3-X12"},{"t":"4 + 8 = 12","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","4 × 8 = 32예요.","그래서 32 ÷ 4 = 8은 맞아요."],"asset":null},{"stem":"16 ÷ 8 = 2가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"8 × 2 = 16","correct":true},{"t":"2 × 16 = □","mis":"M3-1-u3-X12"},{"t":"16 × 8 = □","mis":"M3-1-u3-X12"},{"t":"8 + 2 = 10","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","8 × 2 = 16이에요.","그래서 16 ÷ 8 = 2는 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#16','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C7',2,'mc','auto','물고기 18마리를 한 봉지에 9마리씩 담아 나눔 장터에 내놓으려고 해요. 몇 봉지가 필요한가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X11']::text[],true,'{"seq":16,"concept":"M3-1-u3-C7","difficulty":2,"kind":"mc","stem":"물고기 18마리를 한 봉지에 9마리씩 담아 나눔 장터에 내놓으려고 해요. 몇 봉지가 필요한가요?","options":[{"t":"2봉지","correct":true},{"t":"9봉지","mis":"M3-1-u3-X02"},{"t":"3봉지","mis":"M3-1-u3-X11"},{"t":"1봉지","mis":"M3-1-u3-X11"}],"explanation":["한 봉지에 9마리씩 — 몇 번 담을 수 있는지 구해요.","18 ÷ 9 = 2 (9 × 2 = 18).","2봉지가 필요해요."],"variant_rule":{"alt":[{"stem":"사탕 45개를 한 상자에 9개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?","options":[{"t":"5상자","correct":true},{"t":"9상자","mis":"M3-1-u3-X02"},{"t":"36상자","mis":"M3-1-u3-X07"},{"t":"6상자","mis":"M3-1-u3-X11"}],"explanation":["한 상자에 9개씩 — 몇 번 담을 수 있는지 구해요.","45 ÷ 9 = 5 (9 × 5 = 45).","5상자가 필요해요."],"asset":null},{"stem":"쿠키 56개를 한 접시에 8개씩 담아 나눔 장터에 내놓으려고 해요. 몇 접시가 필요한가요?","options":[{"t":"7접시","correct":true},{"t":"8접시","mis":"M3-1-u3-X02"},{"t":"48접시","mis":"M3-1-u3-X07"},{"t":"6접시","mis":"M3-1-u3-X11"}],"explanation":["한 접시에 8개씩 — 몇 번 담을 수 있는지 구해요.","56 ÷ 8 = 7 (8 × 7 = 56).","7접시가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#17','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C3',3,'sa','auto','8에서 2씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 2씩 몇 번 뛰었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M3-1-u3-C3","difficulty":3,"kind":"sa","stem":"8에서 2씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 2씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 2씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","8은 2씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[8,6,4,2,null],"step":2,"dir":"down"},"variant_rule":{"alt":[{"stem":"10에서 5씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 5씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["2"],"explanation":["화살표 하나가 5씩 한 번 덜어 낸 거예요.","화살표를 세면 2개 — ?는 0이에요.","10은 5씩 2번 덜어 내면 0 — 2묶음이에요."],"asset":{"type":"jump_row","cells":[10,5,null],"step":5,"dir":"down"}},{"stem":"20에서 5씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 5씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 5씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","20은 5씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[20,15,10,5,null],"step":5,"dir":"down"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#18','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C4',3,'ox','auto','27 ÷ 9와 9 ÷ 27은 같은 식이에요.',ARRAY['M3-1-u3-X05']::text[],true,'{"seq":18,"concept":"M3-1-u3-C4","difficulty":3,"kind":"ox","stem":"27 ÷ 9와 9 ÷ 27은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"mis":"M3-1-u3-X05","explanation":["27 ÷ 9는 「27을 9로 나누기」예요.","9 ÷ 27은 작은 9를 큰 27로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"variant_rule":{"alt":[{"stem":"12 ÷ 3과 3 ÷ 12는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["12 ÷ 3은 「12를 3으로 나누기」예요.","3 ÷ 12는 작은 3을 큰 12로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null},{"stem":"36 ÷ 9와 9 ÷ 36은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["36 ÷ 9는 「36을 9로 나누기」예요.","9 ÷ 36은 작은 9를 큰 36으로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#19','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C5',3,'mc','auto','2 × 9 = 18과 한 가족인 식이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":19,"concept":"M3-1-u3-C5","difficulty":3,"kind":"mc","stem":"2 × 9 = 18과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"18 ÷ 3 = 6","correct":true},{"t":"9 × 2 = 18","mis":"M3-1-u3-X15"},{"t":"18 ÷ 2 = 9","mis":"M3-1-u3-X15"},{"t":"18 ÷ 9 = 2","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 2, 9, 18로 만든 식이에요.","곱셈 2개(2 × 9, 9 × 2), 나눗셈 2개(18 ÷ 2, 18 ÷ 9).","18 ÷ 3 = 6은 다른 수가 들어 있어 한 가족이 아니에요."],"variant_rule":{"alt":[{"stem":"7 × 3 = 21과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"28 ÷ 7 = 4","correct":true},{"t":"3 × 7 = 21","mis":"M3-1-u3-X15"},{"t":"21 ÷ 7 = 3","mis":"M3-1-u3-X15"},{"t":"21 ÷ 3 = 7","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 7, 3, 21로 만든 식이에요.","곱셈 2개(7 × 3, 3 × 7), 나눗셈 2개(21 ÷ 7, 21 ÷ 3).","28 ÷ 7 = 4는 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null},{"stem":"9 × 6 = 54와 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"63 ÷ 9 = 7","correct":true},{"t":"6 × 9 = 54","mis":"M3-1-u3-X15"},{"t":"54 ÷ 9 = 6","mis":"M3-1-u3-X15"},{"t":"54 ÷ 6 = 9","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 9, 6, 54로 만든 식이에요.","곱셈 2개(9 × 6, 6 × 9), 나눗셈 2개(54 ÷ 9, 54 ÷ 6).","63 ÷ 9 = 7은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#20','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C6',3,'sa','auto','□ ÷ 3 = 6 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-1-u3-C6","difficulty":3,"kind":"sa","stem":"□ ÷ 3 = 6 — □에 알맞은 수를 쓰세요.","answer":["18"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","3 × 6 = 18이에요.","□ = 18 — 18 ÷ 3 = 6으로 확인해요."],"variant_rule":{"alt":[{"stem":"□ ÷ 3 = 9 — □에 알맞은 수를 쓰세요.","answer":["27"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","3 × 9 = 27이에요.","□ = 27 — 27 ÷ 3 = 9로 확인해요."],"asset":null},{"stem":"□ ÷ 4 = 3 — □에 알맞은 수를 쓰세요.","answer":["12"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 3 = 12예요.","□ = 12 — 12 ÷ 4 = 3으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#21','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C7',3,'mc','auto','나눔 장터에서 연필 36자루를 9명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.',ARRAY['M3-1-u3-X03','M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":21,"concept":"M3-1-u3-C7","difficulty":3,"kind":"mc","stem":"나눔 장터에서 연필 36자루를 9명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"36 ÷ 9 = 4, 4자루씩","correct":true},{"t":"36 ÷ 4 = 9, 9자루씩","mis":"M3-1-u3-X03"},{"t":"36 − 9 = 27, 27자루씩","mis":"M3-1-u3-X13"},{"t":"36 ÷ 9 = 5, 5자루씩","mis":"M3-1-u3-X11"}],"explanation":["9명에게 똑같이 나누니 나누는 수는 사람 수 9예요.","36 ÷ 9 — 9 × 4 = 36.","한 명이 4자루씩 받아요."],"variant_rule":{"alt":[{"stem":"나눔 장터에서 색종이 18장을 9명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"18 ÷ 9 = 2, 2장씩","correct":true},{"t":"18 ÷ 2 = 9, 9장씩","mis":"M3-1-u3-X03"},{"t":"18 − 9 = 9, 9장씩","mis":"M3-1-u3-X13"},{"t":"18 ÷ 9 = 3, 3장씩","mis":"M3-1-u3-X11"}],"explanation":["9명에게 똑같이 나누니 나누는 수는 사람 수 9예요.","18 ÷ 9 — 9 × 2 = 18.","한 명이 2장씩 받아요."],"asset":null},{"stem":"나눔 장터에서 구슬 10개를 2명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"10 ÷ 2 = 5, 5개씩","correct":true},{"t":"10 ÷ 5 = 2, 2개씩","mis":"M3-1-u3-X03"},{"t":"10 − 2 = 8, 8개씩","mis":"M3-1-u3-X13"},{"t":"10 ÷ 2 = 6, 6개씩","mis":"M3-1-u3-X11"}],"explanation":["2명에게 똑같이 나누니 나누는 수는 사람 수 2예요.","10 ÷ 2 — 2 × 5 = 10.","한 명이 5개씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#22','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C8',3,'mc','auto','사탕 24개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":22,"concept":"M3-1-u3-C8","difficulty":3,"kind":"mc","stem":"사탕 24개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"6명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"3명에게 8개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 6개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 24가 있으면 남김없이 나눌 수 있어요.","6명에게 4개씩, 3명에게 8개씩, 4명에게 6개씩 — 모두 곱셈구구로 24가 돼요.","5단에는 24가 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"사탕 36개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"6명에게 6개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 9개씩","mis":"M3-1-u3-X15"},{"t":"9명에게 4개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 36이 있으면 남김없이 나눌 수 있어요.","6명에게 6개씩, 4명에게 9개씩, 9명에게 4개씩 — 모두 곱셈구구로 36이 돼요.","5단에는 36이 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null},{"stem":"사탕 18개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"7명에게 똑같이","correct":true},{"t":"2명에게 9개씩","mis":"M3-1-u3-X15"},{"t":"6명에게 3개씩","mis":"M3-1-u3-X15"},{"t":"9명에게 2개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 18이 있으면 남김없이 나눌 수 있어요.","2명에게 9개씩, 6명에게 3개씩, 9명에게 2개씩 — 모두 곱셈구구로 18이 돼요.","7단에는 18이 없어서 7명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#23','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C6',4,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":23,"concept":"M3-1-u3-C6","difficulty":4,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"48 ÷ 6","correct":true},{"t":"49 ÷ 7","mis":"M3-1-u3-X13"},{"t":"20 ÷ 4","mis":"M3-1-u3-X11"},{"t":"18 ÷ 9","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","49 ÷ 7 = 7, 20 ÷ 4 = 5, 18 ÷ 9 = 2, 48 ÷ 6 = 8.","몫이 가장 큰 것은 48 ÷ 6 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"45 ÷ 5","correct":true},{"t":"48 ÷ 6","mis":"M3-1-u3-X13"},{"t":"8 ÷ 2","mis":"M3-1-u3-X11"},{"t":"14 ÷ 7","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","48 ÷ 6 = 8, 8 ÷ 2 = 4, 14 ÷ 7 = 2, 45 ÷ 5 = 9.","몫이 가장 큰 것은 45 ÷ 5 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"18 ÷ 2","correct":true},{"t":"48 ÷ 8","mis":"M3-1-u3-X13"},{"t":"35 ÷ 5","mis":"M3-1-u3-X11"},{"t":"12 ÷ 6","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","48 ÷ 8 = 6, 18 ÷ 2 = 9, 35 ÷ 5 = 7, 12 ÷ 6 = 2.","몫이 가장 큰 것은 18 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#24','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C7',4,'sa','auto','카드 32장을 4명에게 똑같이 나누어 주었어요. 한 명이 받은 카드를 다시 2장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-1-u3-C7","difficulty":4,"kind":"sa","stem":"카드 32장을 4명에게 똑같이 나누어 주었어요. 한 명이 받은 카드를 다시 2장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["먼저 한 명이 받은 수: 32 ÷ 4 = 8.","그다음 8을 2장씩 담아요: 8 ÷ 2 = 4.","그래서 4봉지예요."],"variant_rule":{"alt":[{"stem":"귤 18개를 3명에게 똑같이 나누어 주었어요. 한 명이 받은 귤을 다시 2개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 18 ÷ 3 = 6.","그다음 6을 2개씩 담아요: 6 ÷ 2 = 3.","그래서 3봉지예요."],"asset":null},{"stem":"귤 40개를 5명에게 똑같이 나누어 주었어요. 한 명이 받은 귤을 다시 4개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 한 명이 받은 수: 40 ÷ 5 = 8.","그다음 8을 4개씩 담아요: 8 ÷ 4 = 2.","그래서 2봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_b#25','math',3,1,'u3','','g3_1_math_u3_review_b','unit_review','M3-1-u3-C5',4,'essay','teacher','한 줄에 6개씩 4줄로 놓인 쿠키 배열을 보고 곱셈식 2개와 나눗셈식 2개를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u3-C5","difficulty":4,"kind":"essay","stem":"한 줄에 6개씩 4줄로 놓인 쿠키 배열을 보고 곱셈식 2개와 나눗셈식 2개를 써 보세요.","answer_guide":{"answer":"예: 6 × 4 = 24, 4 × 6 = 24, 24 ÷ 6 = 4, 24 ÷ 4 = 6.","scoring_points":["곱셈식 2개를 썼는가","나눗셈식 2개를 썼는가","같은 세 수 4, 6, 24로 썼는가"]},"explanation":["6씩 4줄 = 24.","곱셈 6 × 4, 4 × 6.","나눗셈 24 ÷ 6, 24 ÷ 4."],"asset":{"type":"mul_groups","item":"🍪","k":6,"n":4,"look":"rows"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#1','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C1',1,'mc','auto','컵케이크 14개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":1,"concept":"M3-1-u3-C1","difficulty":1,"kind":"mc","stem":"컵케이크 14개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"2명에게 7개씩","correct":true},{"t":"2명에게 9·5개","mis":"M3-1-u3-X01"},{"t":"3명에게 7·4·3개","mis":"M3-1-u3-X01"},{"t":"4명에게 4·4·2·4개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","2명이 모두 7개씩 받으면 2 × 7 = 14개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"variant_rule":{"alt":[{"stem":"도넛 24개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"8명에게 3개씩","correct":true},{"t":"8명에게 3·2·3·6·3·5·1·1개","mis":"M3-1-u3-X01"},{"t":"9명에게 4·4·1·1·7·1·3·1·2개","mis":"M3-1-u3-X01"},{"t":"7명에게 2·2·6·2·2·1·9개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","8명이 모두 3개씩 받으면 8 × 3 = 24개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null},{"stem":"사과 14개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"7명에게 2개씩","correct":true},{"t":"7명에게 1·2·5·1·1·2·2개","mis":"M3-1-u3-X01"},{"t":"8명에게 3·2·2·2·2·2·2·1개","mis":"M3-1-u3-X01"},{"t":"6명에게 2·1·5·1·4·1개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","7명이 모두 2개씩 받으면 7 × 2 = 14개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#2','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C2',1,'mc','auto','컵케이크 16개를 친구 2명에게 똑같이 나누었어요. 한 명에게 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":2,"concept":"M3-1-u3-C2","difficulty":1,"kind":"mc","stem":"컵케이크 16개를 친구 2명에게 똑같이 나누었어요. 한 명에게 몇 개씩인가요?","options":[{"t":"8개","correct":true},{"t":"2개","mis":"M3-1-u3-X02"},{"t":"14개","mis":"M3-1-u3-X07"},{"t":"9개","mis":"M3-1-u3-X11"}],"explanation":["컵케이크 16개를 친구 2명에게 하나씩 번갈아 놓았어요.","묶음마다 8개씩 똑같이 있어요.","그래서 한 명에게 8개예요."],"asset":{"type":"mul_groups","item":"🧁","k":8,"n":2},"variant_rule":{"alt":[{"stem":"도넛 12개를 접시 6개에 똑같이 나누었어요. 한 접시에 몇 개씩인가요?","options":[{"t":"2개","correct":true},{"t":"6개","mis":"M3-1-u3-X02"},{"t":"3개","mis":"M3-1-u3-X11"},{"t":"1개","mis":"M3-1-u3-X11"}],"explanation":["도넛 12개를 접시 6개에 하나씩 번갈아 놓았어요.","묶음마다 2개씩 똑같이 있어요.","그래서 한 접시에 2개예요."],"asset":{"type":"mul_groups","item":"🍩","k":2,"n":6}},{"stem":"사과 12개를 모둠 2개에 똑같이 나누었어요. 한 모둠에 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"2개","mis":"M3-1-u3-X02"},{"t":"10개","mis":"M3-1-u3-X07"},{"t":"7개","mis":"M3-1-u3-X11"}],"explanation":["사과 12개를 모둠 2개에 하나씩 번갈아 놓았어요.","묶음마다 6개씩 똑같이 있어요.","그래서 한 모둠에 6개예요."],"asset":{"type":"mul_groups","item":"🍎","k":6,"n":2}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#3','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C2',1,'sa','auto','색종이 21장을 모둠 7개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C2","difficulty":1,"kind":"sa","stem":"색종이 21장을 모둠 7개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["21장을 모둠 7개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","7묶음으로 똑같이 나누니 7 × □ = 21에서 □ = 3이에요.","한 모둠에 3장이에요."],"variant_rule":{"alt":[{"stem":"구슬 30개를 봉지 5개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["30개를 봉지 5개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","5묶음으로 똑같이 나누니 5 × □ = 30에서 □ = 6이에요.","한 봉지에 6개예요."],"asset":null},{"stem":"카드 24장을 상자 6개에 똑같이 나누어 담으면 한 상자에 몇 장씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["24장을 상자 6개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","6묶음으로 똑같이 나누니 6 × □ = 24에서 □ = 4예요.","한 상자에 4장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#4','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C3',1,'mc','auto','딸기 45개를 9개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":4,"concept":"M3-1-u3-C3","difficulty":1,"kind":"mc","stem":"딸기 45개를 9개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"5묶음","correct":true},{"t":"9묶음","mis":"M3-1-u3-X02"},{"t":"36묶음","mis":"M3-1-u3-X07"},{"t":"6묶음","mis":"M3-1-u3-X11"}],"explanation":["9개씩 묶은 테두리를 세어요.","9씩 5번 덜어 내면 45개 모두 덜어 내져요 — 9 × 5 = 45.","그래서 5묶음이에요."],"asset":{"type":"mul_groups","item":"🍓","k":9,"n":5},"variant_rule":{"alt":[{"stem":"풍선 8개를 2개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"4묶음","correct":true},{"t":"2묶음","mis":"M3-1-u3-X02"},{"t":"6묶음","mis":"M3-1-u3-X07"},{"t":"5묶음","mis":"M3-1-u3-X11"}],"explanation":["2개씩 묶은 테두리를 세어요.","2씩 4번 덜어 내면 8개 모두 덜어 내져요 — 2 × 4 = 8.","그래서 4묶음이에요."],"asset":{"type":"mul_groups","item":"🎈","k":2,"n":4}},{"stem":"별 스티커 14장을 2장씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"7묶음","correct":true},{"t":"2묶음","mis":"M3-1-u3-X02"},{"t":"12묶음","mis":"M3-1-u3-X07"},{"t":"8묶음","mis":"M3-1-u3-X11"}],"explanation":["2장씩 묶은 테두리를 세어요.","2씩 7번 덜어 내면 14장 모두 덜어 내져요 — 2 × 7 = 14.","그래서 7묶음이에요."],"asset":{"type":"mul_groups","item":"⭐","k":2,"n":7}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#5','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C3',1,'sa','auto','30 − 6 − 6 − 6 − 6 − 6 = 0에서 6을 몇 번 뺐나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C3","difficulty":1,"kind":"sa","stem":"30 − 6 − 6 − 6 − 6 − 6 = 0에서 6을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["5"],"explanation":["빼는 수 6이 몇 개인지 세어요.","30 − 6을 5번 하면 0이 돼요.","30은 6씩 5묶음으로 덜어 낼 수 있어요."],"variant_rule":{"alt":[{"stem":"12 − 3 − 3 − 3 − 3 = 0에서 3을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["4"],"explanation":["빼는 수 3이 몇 개인지 세어요.","12 − 3을 4번 하면 0이 돼요.","12는 3씩 4묶음으로 덜어 낼 수 있어요."],"asset":null},{"stem":"12 − 4 − 4 − 4 = 0에서 4를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["3"],"explanation":["빼는 수 4가 몇 개인지 세어요.","12 − 4를 3번 하면 0이 돼요.","12는 4씩 3묶음으로 덜어 낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#6','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C4',1,'mc','auto','72 ÷ 9를 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-1-u3-X07','M3-1-u3-X05']::text[],true,'{"seq":6,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"72 ÷ 9를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"72 나누기 9","correct":true},{"t":"72 곱하기 9","mis":"M3-1-u3-X07"},{"t":"9 나누기 72","mis":"M3-1-u3-X05"},{"t":"72 빼기 9","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 72 나누기 9.","72 ÷ 9 = 8은 「72 나누기 9는 8」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"16 ÷ 2를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"16 나누기 2","correct":true},{"t":"16 곱하기 2","mis":"M3-1-u3-X07"},{"t":"2 나누기 16","mis":"M3-1-u3-X05"},{"t":"16 빼기 2","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 16 나누기 2.","16 ÷ 2 = 8은 「16 나누기 2는 8」이라고 읽어요."],"asset":null},{"stem":"18 ÷ 9를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"18 나누기 9","correct":true},{"t":"18 곱하기 9","mis":"M3-1-u3-X07"},{"t":"9 나누기 18","mis":"M3-1-u3-X05"},{"t":"18 빼기 9","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 18 나누기 9.","18 ÷ 9 = 2는 「18 나누기 9는 2」라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#7','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C4',1,'mc','auto','28 ÷ 4 = 7에서 몫은 어느 것인가요?',ARRAY['M3-1-u3-X06']::text[],true,'{"seq":7,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"28 ÷ 4 = 7에서 몫은 어느 것인가요?","options":[{"t":"7","correct":true},{"t":"28","mis":"M3-1-u3-X06"},{"t":"4","mis":"M3-1-u3-X06"},{"t":"28과 4","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","28은 나누어지는 수, 4는 나누는 수예요.","= 뒤의 7이 몫이에요."],"variant_rule":{"alt":[{"stem":"15 ÷ 5 = 3에서 몫은 어느 것인가요?","options":[{"t":"3","correct":true},{"t":"15","mis":"M3-1-u3-X06"},{"t":"5","mis":"M3-1-u3-X06"},{"t":"15와 5","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","15는 나누어지는 수, 5는 나누는 수예요.","= 뒤의 3이 몫이에요."],"asset":null},{"stem":"18 ÷ 9 = 2에서 몫은 어느 것인가요?","options":[{"t":"2","correct":true},{"t":"18","mis":"M3-1-u3-X06"},{"t":"9","mis":"M3-1-u3-X06"},{"t":"18과 9","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","18은 나누어지는 수, 9는 나누는 수예요.","= 뒤의 2가 몫이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#8','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C6',1,'sa','auto','곱셈구구를 이용해 63 ÷ 7의 몫을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C6","difficulty":1,"kind":"sa","stem":"곱셈구구를 이용해 63 ÷ 7의 몫을 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["7 × □ = 63이 되는 □를 찾아요.","7단: … 7 × 9 = 63.","그래서 63 ÷ 7 = 9예요."],"variant_rule":{"alt":[{"stem":"곱셈구구를 이용해 15 ÷ 3의 몫을 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["3 × □ = 15가 되는 □를 찾아요.","3단: … 3 × 5 = 15.","그래서 15 ÷ 3 = 5예요."],"asset":null},{"stem":"곱셈구구를 이용해 56 ÷ 7의 몫을 구하세요. 숫자로 쓰세요.","answer":["8"],"explanation":["7 × □ = 56이 되는 □를 찾아요.","7단: … 7 × 8 = 56.","그래서 56 ÷ 7 = 8이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#9','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C1',2,'ox','auto','카드 36장을 6명에게 차례로 7·6·6·5·6·6장을 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":9,"concept":"M3-1-u3-C1","difficulty":2,"kind":"ox","stem":"카드 36장을 6명에게 차례로 7·6·6·5·6·6장을 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"mis":"M3-1-u3-X01","explanation":["모두 더하면 36장 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 7·6·6·5·6·6장으로 달라요.","똑같이 나누려면 6명 모두 6장씩 받아야 해요."],"variant_rule":{"alt":[{"stem":"지우개 10개를 2명에게 차례로 6·4개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 10개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 6·4개로 달라요.","똑같이 나누려면 2명 모두 5개씩 받아야 해요."],"asset":null},{"stem":"클립 35개를 7명에게 차례로 4·5·5·6·5·5·5개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 35개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 4·5·5·6·5·5·5개로 달라요.","똑같이 나누려면 7명 모두 5개씩 받아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#10','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C2',2,'mc','auto','연필 8자루를 접시 4개에 똑같이 나누어 담으면 한 접시에 몇 자루씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X11']::text[],true,'{"seq":10,"concept":"M3-1-u3-C2","difficulty":2,"kind":"mc","stem":"연필 8자루를 접시 4개에 똑같이 나누어 담으면 한 접시에 몇 자루씩인가요?","options":[{"t":"2자루","correct":true},{"t":"4자루","mis":"M3-1-u3-X02"},{"t":"3자루","mis":"M3-1-u3-X11"},{"t":"1자루","mis":"M3-1-u3-X11"}],"explanation":["8자루를 접시 4개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","4묶음으로 똑같이 나누니 4 × □ = 8에서 □ = 2예요.","한 접시에 2자루예요."],"variant_rule":{"alt":[{"stem":"색종이 10장을 모둠 2개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요?","options":[{"t":"5장","correct":true},{"t":"2장","mis":"M3-1-u3-X02"},{"t":"8장","mis":"M3-1-u3-X07"},{"t":"6장","mis":"M3-1-u3-X11"}],"explanation":["10장을 모둠 2개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","2묶음으로 똑같이 나누니 2 × □ = 10에서 □ = 5예요.","한 모둠에 5장이에요."],"asset":null},{"stem":"구슬 18개를 봉지 6개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M3-1-u3-X02"},{"t":"12개","mis":"M3-1-u3-X07"},{"t":"4개","mis":"M3-1-u3-X11"}],"explanation":["18개를 봉지 6개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","6묶음으로 똑같이 나누니 6 × □ = 18에서 □ = 3이에요.","한 봉지에 3개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#11','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C3',2,'mc','auto','카드 12장을 한 상자에 3장씩 담으면 몇 상자가 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":11,"concept":"M3-1-u3-C3","difficulty":2,"kind":"mc","stem":"카드 12장을 한 상자에 3장씩 담으면 몇 상자가 되나요?","options":[{"t":"4상자","correct":true},{"t":"3상자","mis":"M3-1-u3-X02"},{"t":"9상자","mis":"M3-1-u3-X07"},{"t":"5상자","mis":"M3-1-u3-X11"}],"explanation":["12장에서 3장씩 덜어 내요.","3 × □ = 12에서 □ = 4 — 4번 덜어 낼 수 있어요.","그래서 4상자예요."],"variant_rule":{"alt":[{"stem":"지우개 18개를 한 접시에 3개씩 담으면 몇 접시가 되나요?","options":[{"t":"6접시","correct":true},{"t":"3접시","mis":"M3-1-u3-X02"},{"t":"15접시","mis":"M3-1-u3-X07"},{"t":"7접시","mis":"M3-1-u3-X11"}],"explanation":["18개에서 3개씩 덜어 내요.","3 × □ = 18에서 □ = 6 — 6번 덜어 낼 수 있어요.","그래서 6접시예요."],"asset":null},{"stem":"클립 30개를 한 바구니에 5개씩 담으면 몇 바구니가 되나요?","options":[{"t":"6바구니","correct":true},{"t":"5바구니","mis":"M3-1-u3-X02"},{"t":"25바구니","mis":"M3-1-u3-X07"},{"t":"7바구니","mis":"M3-1-u3-X11"}],"explanation":["30개에서 5개씩 덜어 내요.","5 × □ = 30에서 □ = 6 — 6번 덜어 낼 수 있어요.","그래서 6바구니예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#12','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C4',2,'mc','auto','귤 28개를 7명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X03','M3-1-u3-X13']::text[],true,'{"seq":12,"concept":"M3-1-u3-C4","difficulty":2,"kind":"mc","stem":"귤 28개를 7명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"28 ÷ 7","correct":true},{"t":"7 ÷ 28","mis":"M3-1-u3-X05"},{"t":"28 ÷ 4","mis":"M3-1-u3-X03"},{"t":"28 × 7","mis":"M3-1-u3-X13"}],"explanation":["전체 28개를 7명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 28 ÷ 7.","28 ÷ 7 = 4 — 한 명이 4개씩 받아요."],"variant_rule":{"alt":[{"stem":"공책 6권을 2명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"6 ÷ 2","correct":true},{"t":"2 ÷ 6","mis":"M3-1-u3-X05"},{"t":"6 ÷ 3","mis":"M3-1-u3-X03"},{"t":"6 × 2","mis":"M3-1-u3-X13"}],"explanation":["전체 6권을 2명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 6 ÷ 2.","6 ÷ 2 = 3 — 한 명이 3권씩 받아요."],"asset":null},{"stem":"연필 32자루를 4명에게 똑같이 나누어 주려고 해요. 한 명이 받는 수를 구하는 식은 어느 것인가요?","options":[{"t":"32 ÷ 4","correct":true},{"t":"4 ÷ 32","mis":"M3-1-u3-X05"},{"t":"32 ÷ 8","mis":"M3-1-u3-X03"},{"t":"32 × 4","mis":"M3-1-u3-X13"}],"explanation":["전체 32자루를 4명에게 똑같이 나눠요.","나눗셈식은 전체를 앞에, 나누는 수를 뒤에 써요 — 32 ÷ 4.","32 ÷ 4 = 8 — 한 명이 8자루씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#13','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C5',2,'mc','auto','9 × 8 = 72를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X08']::text[],true,'{"seq":13,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"9 × 8 = 72를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"72 ÷ 9 = 8","correct":true},{"t":"9 ÷ 72 = 8","mis":"M3-1-u3-X05"},{"t":"72 ÷ 9 = 63","mis":"M3-1-u3-X08"},{"t":"72 ÷ 10 = 8","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 9 × 8 = 72에서 곱 72가 나누어지는 수가 돼요.","72를 9로 나누면 8 — 72 ÷ 9 = 8.","같은 세 수 9, 8, 72만 써요."],"variant_rule":{"alt":[{"stem":"7 × 4 = 28을 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"28 ÷ 7 = 4","correct":true},{"t":"7 ÷ 28 = 4","mis":"M3-1-u3-X05"},{"t":"28 ÷ 7 = 21","mis":"M3-1-u3-X08"},{"t":"28 ÷ 8 = 4","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 7 × 4 = 28에서 곱 28이 나누어지는 수가 돼요.","28을 7로 나누면 4 — 28 ÷ 7 = 4.","같은 세 수 7, 4, 28만 써요."],"asset":null},{"stem":"2 × 5 = 10을 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"10 ÷ 2 = 5","correct":true},{"t":"2 ÷ 10 = 5","mis":"M3-1-u3-X05"},{"t":"10 ÷ 2 = 8","mis":"M3-1-u3-X08"},{"t":"10 ÷ 3 = 5","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 2 × 5 = 10에서 곱 10이 나누어지는 수가 돼요.","10을 2로 나누면 5 — 10 ÷ 2 = 5.","같은 세 수 2, 5, 10만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#14','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C5',2,'mc','auto','컵케이크를 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?',ARRAY['M3-1-u3-X09','M3-1-u3-X11','M3-1-u3-X13']::text[],true,'{"seq":14,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"컵케이크를 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 5 = 10","correct":true},{"t":"2 × 6 = 12","mis":"M3-1-u3-X09"},{"t":"2 × 5 = 12","mis":"M3-1-u3-X11"},{"t":"2 + 5 = 7","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2개씩, 줄은 5줄이에요.","2씩 5줄이니 2 × 5.","2 × 5 = 10 — 모두 10개."],"asset":{"type":"mul_groups","item":"🧁","k":2,"n":5,"look":"rows"},"variant_rule":{"alt":[{"stem":"도넛을 한 줄에 7개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"7 × 5 = 35","correct":true},{"t":"7 × 6 = 42","mis":"M3-1-u3-X09"},{"t":"7 × 5 = 42","mis":"M3-1-u3-X11"},{"t":"7 + 5 = 12","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 7개씩, 줄은 5줄이에요.","7씩 5줄이니 7 × 5.","7 × 5 = 35 — 모두 35개."],"asset":{"type":"mul_groups","item":"🍩","k":7,"n":5,"look":"rows"}},{"stem":"사과를 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 7 = 14","correct":true},{"t":"2 × 8 = 16","mis":"M3-1-u3-X09"},{"t":"2 × 7 = 16","mis":"M3-1-u3-X11"},{"t":"2 + 7 = 9","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2개씩, 줄은 7줄이에요.","2씩 7줄이니 2 × 7.","2 × 7 = 14 — 모두 14개."],"asset":{"type":"mul_groups","item":"🍎","k":2,"n":7,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#15','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C6',2,'mc','auto','48 ÷ 6 = 8이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M3-1-u3-X12','M3-1-u3-X13']::text[],true,'{"seq":15,"concept":"M3-1-u3-C6","difficulty":2,"kind":"mc","stem":"48 ÷ 6 = 8이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"6 × 8 = 48","correct":true},{"t":"8 × 48 = □","mis":"M3-1-u3-X12"},{"t":"48 × 6 = □","mis":"M3-1-u3-X12"},{"t":"6 + 8 = 14","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","6 × 8 = 48이에요.","그래서 48 ÷ 6 = 8은 맞아요."],"variant_rule":{"alt":[{"stem":"45 ÷ 9 = 5가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"9 × 5 = 45","correct":true},{"t":"5 × 45 = □","mis":"M3-1-u3-X12"},{"t":"45 × 9 = □","mis":"M3-1-u3-X12"},{"t":"9 + 5 = 14","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","9 × 5 = 45예요.","그래서 45 ÷ 9 = 5는 맞아요."],"asset":null},{"stem":"56 ÷ 7 = 8이 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"7 × 8 = 56","correct":true},{"t":"8 × 56 = □","mis":"M3-1-u3-X12"},{"t":"56 × 7 = □","mis":"M3-1-u3-X12"},{"t":"7 + 8 = 15","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","7 × 8 = 56이에요.","그래서 56 ÷ 7 = 8은 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#16','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C7',2,'mc','auto','사탕 27개를 한 주머니에 9개씩 담아 나눔 장터에 내놓으려고 해요. 몇 주머니가 필요한가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":16,"concept":"M3-1-u3-C7","difficulty":2,"kind":"mc","stem":"사탕 27개를 한 주머니에 9개씩 담아 나눔 장터에 내놓으려고 해요. 몇 주머니가 필요한가요?","options":[{"t":"3주머니","correct":true},{"t":"9주머니","mis":"M3-1-u3-X02"},{"t":"18주머니","mis":"M3-1-u3-X07"},{"t":"4주머니","mis":"M3-1-u3-X11"}],"explanation":["한 주머니에 9개씩 — 몇 번 담을 수 있는지 구해요.","27 ÷ 9 = 3 (9 × 3 = 27).","3주머니가 필요해요."],"variant_rule":{"alt":[{"stem":"쿠키 63개를 한 봉지에 7개씩 담아 나눔 장터에 내놓으려고 해요. 몇 봉지가 필요한가요?","options":[{"t":"9봉지","correct":true},{"t":"7봉지","mis":"M3-1-u3-X02"},{"t":"56봉지","mis":"M3-1-u3-X07"},{"t":"10봉지","mis":"M3-1-u3-X11"}],"explanation":["한 봉지에 7개씩 — 몇 번 담을 수 있는지 구해요.","63 ÷ 7 = 9 (7 × 9 = 63).","9봉지가 필요해요."],"asset":null},{"stem":"딸기 10개를 한 상자에 2개씩 담아 나눔 장터에 내놓으려고 해요. 몇 상자가 필요한가요?","options":[{"t":"5상자","correct":true},{"t":"2상자","mis":"M3-1-u3-X02"},{"t":"8상자","mis":"M3-1-u3-X07"},{"t":"6상자","mis":"M3-1-u3-X11"}],"explanation":["한 상자에 2개씩 — 몇 번 담을 수 있는지 구해요.","10 ÷ 2 = 5 (2 × 5 = 10).","5상자가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#17','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C3',3,'sa','auto','12에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M3-1-u3-C3","difficulty":3,"kind":"sa","stem":"12에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["3"],"explanation":["화살표 하나가 4씩 한 번 덜어 낸 거예요.","화살표를 세면 3개 — ?는 0이에요.","12는 4씩 3번 덜어 내면 0 — 3묶음이에요."],"asset":{"type":"jump_row","cells":[12,8,4,null],"step":4,"dir":"down"},"variant_rule":{"alt":[{"stem":"16에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 4씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","16은 4씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[16,12,8,4,null],"step":4,"dir":"down"}},{"stem":"20에서 5씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 5씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 5씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","20은 5씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[20,15,10,5,null],"step":5,"dir":"down"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#18','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C4',3,'ox','auto','12 ÷ 6과 6 ÷ 12는 같은 식이에요.',ARRAY['M3-1-u3-X05']::text[],true,'{"seq":18,"concept":"M3-1-u3-C4","difficulty":3,"kind":"ox","stem":"12 ÷ 6과 6 ÷ 12는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"mis":"M3-1-u3-X05","explanation":["12 ÷ 6은 「12를 6으로 나누기」예요.","6 ÷ 12는 작은 6을 큰 12로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"variant_rule":{"alt":[{"stem":"24 ÷ 6과 6 ÷ 24는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["24 ÷ 6은 「24를 6으로 나누기」예요.","6 ÷ 24는 작은 6을 큰 24로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null},{"stem":"24 ÷ 3과 3 ÷ 24는 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["24 ÷ 3은 「24를 3으로 나누기」예요.","3 ÷ 24는 작은 3을 큰 24로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#19','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C5',3,'mc','auto','9 × 3 = 27과 한 가족인 식이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":19,"concept":"M3-1-u3-C5","difficulty":3,"kind":"mc","stem":"9 × 3 = 27과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"36 ÷ 9 = 4","correct":true},{"t":"3 × 9 = 27","mis":"M3-1-u3-X15"},{"t":"27 ÷ 9 = 3","mis":"M3-1-u3-X15"},{"t":"27 ÷ 3 = 9","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 9, 3, 27로 만든 식이에요.","곱셈 2개(9 × 3, 3 × 9), 나눗셈 2개(27 ÷ 9, 27 ÷ 3).","36 ÷ 9 = 4는 다른 수가 들어 있어 한 가족이 아니에요."],"variant_rule":{"alt":[{"stem":"7 × 3 = 21과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"28 ÷ 7 = 4","correct":true},{"t":"3 × 7 = 21","mis":"M3-1-u3-X15"},{"t":"21 ÷ 7 = 3","mis":"M3-1-u3-X15"},{"t":"21 ÷ 3 = 7","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 7, 3, 21로 만든 식이에요.","곱셈 2개(7 × 3, 3 × 7), 나눗셈 2개(21 ÷ 7, 21 ÷ 3).","28 ÷ 7 = 4는 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null},{"stem":"8 × 5 = 40과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"48 ÷ 8 = 6","correct":true},{"t":"5 × 8 = 40","mis":"M3-1-u3-X15"},{"t":"40 ÷ 8 = 5","mis":"M3-1-u3-X15"},{"t":"40 ÷ 5 = 8","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 8, 5, 40으로 만든 식이에요.","곱셈 2개(8 × 5, 5 × 8), 나눗셈 2개(40 ÷ 8, 40 ÷ 5).","48 ÷ 8 = 6은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#20','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C6',3,'sa','auto','□ ÷ 8 = 7 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-1-u3-C6","difficulty":3,"kind":"sa","stem":"□ ÷ 8 = 7 — □에 알맞은 수를 쓰세요.","answer":["56"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","8 × 7 = 56이에요.","□ = 56 — 56 ÷ 8 = 7로 확인해요."],"variant_rule":{"alt":[{"stem":"□ ÷ 8 = 4 — □에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","8 × 4 = 32예요.","□ = 32 — 32 ÷ 8 = 4로 확인해요."],"asset":null},{"stem":"□ ÷ 9 = 3 — □에 알맞은 수를 쓰세요.","answer":["27"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","9 × 3 = 27이에요.","□ = 27 — 27 ÷ 9 = 3으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#21','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C7',3,'mc','auto','나눔 장터에서 색종이 27장을 3명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.',ARRAY['M3-1-u3-X03','M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":21,"concept":"M3-1-u3-C7","difficulty":3,"kind":"mc","stem":"나눔 장터에서 색종이 27장을 3명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"27 ÷ 3 = 9, 9장씩","correct":true},{"t":"27 ÷ 9 = 3, 3장씩","mis":"M3-1-u3-X03"},{"t":"27 − 3 = 24, 24장씩","mis":"M3-1-u3-X13"},{"t":"27 ÷ 3 = 10, 10장씩","mis":"M3-1-u3-X11"}],"explanation":["3명에게 똑같이 나누니 나누는 수는 사람 수 3이에요.","27 ÷ 3 — 3 × 9 = 27.","한 명이 9장씩 받아요."],"variant_rule":{"alt":[{"stem":"나눔 장터에서 구슬 24개를 4명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"24 ÷ 4 = 6, 6개씩","correct":true},{"t":"24 ÷ 6 = 4, 4개씩","mis":"M3-1-u3-X03"},{"t":"24 − 4 = 20, 20개씩","mis":"M3-1-u3-X13"},{"t":"24 ÷ 4 = 7, 7개씩","mis":"M3-1-u3-X11"}],"explanation":["4명에게 똑같이 나누니 나누는 수는 사람 수 4예요.","24 ÷ 4 — 4 × 6 = 24.","한 명이 6개씩 받아요."],"asset":null},{"stem":"나눔 장터에서 카드 16장을 2명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"16 ÷ 2 = 8, 8장씩","correct":true},{"t":"16 ÷ 8 = 2, 2장씩","mis":"M3-1-u3-X03"},{"t":"16 − 2 = 14, 14장씩","mis":"M3-1-u3-X13"},{"t":"16 ÷ 2 = 9, 9장씩","mis":"M3-1-u3-X11"}],"explanation":["2명에게 똑같이 나누니 나누는 수는 사람 수 2예요.","16 ÷ 2 — 2 × 8 = 16.","한 명이 8장씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#22','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C8',3,'mc','auto','사탕 16개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":22,"concept":"M3-1-u3-C8","difficulty":3,"kind":"mc","stem":"사탕 16개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"8명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"2명에게 8개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 16이 있으면 남김없이 나눌 수 있어요.","8명에게 2개씩, 4명에게 4개씩, 2명에게 8개씩 — 모두 곱셈구구로 16이 돼요.","5단에는 16이 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"사탕 12개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"8명에게 똑같이","correct":true},{"t":"6명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"3명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 3개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 12가 있으면 남김없이 나눌 수 있어요.","6명에게 2개씩, 3명에게 4개씩, 4명에게 3개씩 — 모두 곱셈구구로 12가 돼요.","8단에는 12가 없어서 8명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null},{"stem":"사탕 24개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"5명에게 똑같이","correct":true},{"t":"8명에게 3개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 6개씩","mis":"M3-1-u3-X15"},{"t":"6명에게 4개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 24가 있으면 남김없이 나눌 수 있어요.","8명에게 3개씩, 4명에게 6개씩, 6명에게 4개씩 — 모두 곱셈구구로 24가 돼요.","5단에는 24가 없어서 5명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#23','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C6',4,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u3-X11','M3-1-u3-X13']::text[],true,'{"seq":23,"concept":"M3-1-u3-C6","difficulty":4,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"24 ÷ 4","correct":true},{"t":"8 ÷ 2","mis":"M3-1-u3-X11"},{"t":"12 ÷ 4","mis":"M3-1-u3-X11"},{"t":"40 ÷ 8","mis":"M3-1-u3-X13"}],"explanation":["하나씩 몫을 구해요.","8 ÷ 2 = 4, 12 ÷ 4 = 3, 24 ÷ 4 = 6, 40 ÷ 8 = 5.","몫이 가장 큰 것은 24 ÷ 4 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"12 ÷ 2","correct":true},{"t":"14 ÷ 7","mis":"M3-1-u3-X11"},{"t":"36 ÷ 9","mis":"M3-1-u3-X13"},{"t":"18 ÷ 6","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","14 ÷ 7 = 2, 36 ÷ 9 = 4, 12 ÷ 2 = 6, 18 ÷ 6 = 3.","몫이 가장 큰 것은 12 ÷ 2 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"32 ÷ 4","correct":true},{"t":"56 ÷ 8","mis":"M3-1-u3-X13"},{"t":"6 ÷ 2","mis":"M3-1-u3-X11"},{"t":"20 ÷ 4","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","56 ÷ 8 = 7, 6 ÷ 2 = 3, 20 ÷ 4 = 5, 32 ÷ 4 = 8.","몫이 가장 큰 것은 32 ÷ 4 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#24','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C7',4,'sa','auto','공책 36권을 6명에게 똑같이 나누어 주었어요. 한 명이 받은 공책을 다시 2권씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-1-u3-C7","difficulty":4,"kind":"sa","stem":"공책 36권을 6명에게 똑같이 나누어 주었어요. 한 명이 받은 공책을 다시 2권씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 36 ÷ 6 = 6.","그다음 6을 2권씩 담아요: 6 ÷ 2 = 3.","그래서 3봉지예요."],"variant_rule":{"alt":[{"stem":"클립 16개를 2명에게 똑같이 나누어 주었어요. 한 명이 받은 클립을 다시 4개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 한 명이 받은 수: 16 ÷ 2 = 8.","그다음 8을 4개씩 담아요: 8 ÷ 4 = 2.","그래서 2봉지예요."],"asset":null},{"stem":"지우개 36개를 4명에게 똑같이 나누어 주었어요. 한 명이 받은 지우개를 다시 3개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 36 ÷ 4 = 9.","그다음 9를 3개씩 담아요: 9 ÷ 3 = 3.","그래서 3봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_c#25','math',3,1,'u3','','g3_1_math_u3_review_c','unit_review','M3-1-u3-C3',4,'essay','teacher','색종이 20장을 「5명에게 똑같이 나누기」와 「5장씩 묶기」의 답을 각각 구하고, 무엇이 다른지 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u3-C3","difficulty":4,"kind":"essay","stem":"색종이 20장을 「5명에게 똑같이 나누기」와 「5장씩 묶기」의 답을 각각 구하고, 무엇이 다른지 설명해 보세요.","answer_guide":{"answer":"예: 5명에게 똑같이 나누면 20 ÷ 5 = 4, 한 명에게 4장씩이다. 5장씩 묶으면 20 ÷ 5 = 4, 4묶음이다. 식은 같지만 하나는 한 명이 받는 수, 하나는 묶음 수를 구한다.","scoring_points":["한 명에게 4장씩을 구했는가","4묶음을 구했는가","묻는 것(몫의 뜻)이 다르다고 썼는가"]},"explanation":["5명에게 → 4장씩.","5장씩 → 4묶음.","몫이 뜻하는 것이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#1','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C1',1,'mc','auto','도넛 14개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":1,"concept":"M3-1-u3-C1","difficulty":1,"kind":"mc","stem":"도넛 14개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"2명에게 7개씩","correct":true},{"t":"2명에게 8·6개","mis":"M3-1-u3-X01"},{"t":"3명에게 3·2·9개","mis":"M3-1-u3-X01"},{"t":"4명에게 6·4·3·1개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","2명이 모두 7개씩 받으면 2 × 7 = 14개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"variant_rule":{"alt":[{"stem":"사과 63개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"7명에게 9개씩","correct":true},{"t":"7명에게 10·9·9·9·9·9·8개","mis":"M3-1-u3-X01"},{"t":"8명에게 10·9·9·9·9·9·9·8개","mis":"M3-1-u3-X01"},{"t":"6명에게 10·9·9·9·9·8개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","7명이 모두 9개씩 받으면 7 × 9 = 63개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null},{"stem":"당근 45개를 나누었어요. 똑같이 나눈 것은 어느 것인가요?","options":[{"t":"9명에게 5개씩","correct":true},{"t":"9명에게 2·3·4·5·6·4·8·5·8개","mis":"M3-1-u3-X01"},{"t":"8명에게 3·6·7·9·1·9·9·1개","mis":"M3-1-u3-X01"},{"t":"8명에게 5·8·6·6·7·6·1·6개","mis":"M3-1-u3-X01"}],"explanation":["똑같이 나누면 묶음마다 개수가 같아요.","9명이 모두 5개씩 받으면 9 × 5 = 45개 — 남김없이 똑같이 나눴어요.","다른 것은 받은 개수가 들쭉날쭉해서 공평하지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#2','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C2',1,'mc','auto','도넛 18개를 바구니 3개에 똑같이 나누었어요. 한 바구니에 몇 개씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":2,"concept":"M3-1-u3-C2","difficulty":1,"kind":"mc","stem":"도넛 18개를 바구니 3개에 똑같이 나누었어요. 한 바구니에 몇 개씩인가요?","options":[{"t":"6개","correct":true},{"t":"3개","mis":"M3-1-u3-X02"},{"t":"15개","mis":"M3-1-u3-X07"},{"t":"7개","mis":"M3-1-u3-X11"}],"explanation":["도넛 18개를 바구니 3개에 하나씩 번갈아 놓았어요.","묶음마다 6개씩 똑같이 있어요.","그래서 한 바구니에 6개예요."],"asset":{"type":"mul_groups","item":"🍩","k":6,"n":3},"variant_rule":{"alt":[{"stem":"사과 45개를 친구 5명에게 똑같이 나누었어요. 한 명에게 몇 개씩인가요?","options":[{"t":"9개","correct":true},{"t":"5개","mis":"M3-1-u3-X02"},{"t":"40개","mis":"M3-1-u3-X07"},{"t":"10개","mis":"M3-1-u3-X11"}],"explanation":["사과 45개를 친구 5명에게 하나씩 번갈아 놓았어요.","묶음마다 9개씩 똑같이 있어요.","그래서 한 명에게 9개예요."],"asset":{"type":"mul_groups","item":"🍎","k":9,"n":5}},{"stem":"당근 12개를 접시 6개에 똑같이 나누었어요. 한 접시에 몇 개씩인가요?","options":[{"t":"2개","correct":true},{"t":"6개","mis":"M3-1-u3-X02"},{"t":"3개","mis":"M3-1-u3-X11"},{"t":"1개","mis":"M3-1-u3-X11"}],"explanation":["당근 12개를 접시 6개에 하나씩 번갈아 놓았어요.","묶음마다 2개씩 똑같이 있어요.","그래서 한 접시에 2개예요."],"asset":{"type":"mul_groups","item":"🥕","k":2,"n":6}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#3','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C2',1,'sa','auto','구슬 21개를 접시 3개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M3-1-u3-C2","difficulty":1,"kind":"sa","stem":"구슬 21개를 접시 3개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["21개를 접시 3개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","3묶음으로 똑같이 나누니 3 × □ = 21에서 □ = 7이에요.","한 접시에 7개예요."],"variant_rule":{"alt":[{"stem":"카드 32장을 모둠 8개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["32장을 모둠 8개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","8묶음으로 똑같이 나누니 8 × □ = 32에서 □ = 4예요.","한 모둠에 4장이에요."],"asset":null},{"stem":"지우개 24개를 봉지 3개에 똑같이 나누어 담으면 한 봉지에 몇 개씩인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["24개를 봉지 3개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","3묶음으로 똑같이 나누니 3 × □ = 24에서 □ = 8이에요.","한 봉지에 8개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#4','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C3',1,'mc','auto','풍선 32개를 4개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":4,"concept":"M3-1-u3-C3","difficulty":1,"kind":"mc","stem":"풍선 32개를 4개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"8묶음","correct":true},{"t":"4묶음","mis":"M3-1-u3-X02"},{"t":"28묶음","mis":"M3-1-u3-X07"},{"t":"9묶음","mis":"M3-1-u3-X11"}],"explanation":["4개씩 묶은 테두리를 세어요.","4씩 8번 덜어 내면 32개 모두 덜어 내져요 — 4 × 8 = 32.","그래서 8묶음이에요."],"asset":{"type":"mul_groups","item":"🎈","k":4,"n":8},"variant_rule":{"alt":[{"stem":"별 스티커 18장을 9장씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"2묶음","correct":true},{"t":"9묶음","mis":"M3-1-u3-X02"},{"t":"3묶음","mis":"M3-1-u3-X11"},{"t":"1묶음","mis":"M3-1-u3-X11"}],"explanation":["9장씩 묶은 테두리를 세어요.","9씩 2번 덜어 내면 18장 모두 덜어 내져요 — 9 × 2 = 18.","그래서 2묶음이에요."],"asset":{"type":"mul_groups","item":"⭐","k":9,"n":2}},{"stem":"컵케이크 28개를 7개씩 묶어 덜어 냈어요. 몇 묶음이 되나요?","options":[{"t":"4묶음","correct":true},{"t":"7묶음","mis":"M3-1-u3-X02"},{"t":"21묶음","mis":"M3-1-u3-X07"},{"t":"5묶음","mis":"M3-1-u3-X11"}],"explanation":["7개씩 묶은 테두리를 세어요.","7씩 4번 덜어 내면 28개 모두 덜어 내져요 — 7 × 4 = 28.","그래서 4묶음이에요."],"asset":{"type":"mul_groups","item":"🧁","k":7,"n":4}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#5','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C3',1,'sa','auto','24 − 4 − 4 − 4 − 4 − 4 − 4 = 0에서 4를 몇 번 뺐나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M3-1-u3-C3","difficulty":1,"kind":"sa","stem":"24 − 4 − 4 − 4 − 4 − 4 − 4 = 0에서 4를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["6"],"explanation":["빼는 수 4가 몇 개인지 세어요.","24 − 4를 6번 하면 0이 돼요.","24는 4씩 6묶음으로 덜어 낼 수 있어요."],"variant_rule":{"alt":[{"stem":"12 − 6 − 6 = 0에서 6을 몇 번 뺐나요? 숫자로 쓰세요.","answer":["2"],"explanation":["빼는 수 6이 몇 개인지 세어요.","12 − 6을 2번 하면 0이 돼요.","12는 6씩 2묶음으로 덜어 낼 수 있어요."],"asset":null},{"stem":"6 − 2 − 2 − 2 = 0에서 2를 몇 번 뺐나요? 숫자로 쓰세요.","answer":["3"],"explanation":["빼는 수 2가 몇 개인지 세어요.","6 − 2를 3번 하면 0이 돼요.","6은 2씩 3묶음으로 덜어 낼 수 있어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#6','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C4',1,'mc','auto','28 ÷ 4를 바르게 읽은 것은 어느 것인가요?',ARRAY['M3-1-u3-X07','M3-1-u3-X05']::text[],true,'{"seq":6,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"28 ÷ 4를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"28 나누기 4","correct":true},{"t":"28 곱하기 4","mis":"M3-1-u3-X07"},{"t":"4 나누기 28","mis":"M3-1-u3-X05"},{"t":"28 빼기 4","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 28 나누기 4.","28 ÷ 4 = 7은 「28 나누기 4는 7」이라고 읽어요."],"variant_rule":{"alt":[{"stem":"18 ÷ 3을 바르게 읽은 것은 어느 것인가요?","options":[{"t":"18 나누기 3","correct":true},{"t":"18 곱하기 3","mis":"M3-1-u3-X07"},{"t":"3 나누기 18","mis":"M3-1-u3-X05"},{"t":"18 빼기 3","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 18 나누기 3.","18 ÷ 3 = 6은 「18 나누기 3은 6」이라고 읽어요."],"asset":null},{"stem":"12 ÷ 4를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"12 나누기 4","correct":true},{"t":"12 곱하기 4","mis":"M3-1-u3-X07"},{"t":"4 나누기 12","mis":"M3-1-u3-X05"},{"t":"12 빼기 4","mis":"M3-1-u3-X07"}],"explanation":["÷는 「나누기」라고 읽어요.","앞의 수부터 차례로 — 12 나누기 4.","12 ÷ 4 = 3은 「12 나누기 4는 3」이라고 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#7','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C4',1,'mc','auto','27 ÷ 3 = 9에서 몫은 어느 것인가요?',ARRAY['M3-1-u3-X06']::text[],true,'{"seq":7,"concept":"M3-1-u3-C4","difficulty":1,"kind":"mc","stem":"27 ÷ 3 = 9에서 몫은 어느 것인가요?","options":[{"t":"9","correct":true},{"t":"27","mis":"M3-1-u3-X06"},{"t":"3","mis":"M3-1-u3-X06"},{"t":"27과 3","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","27은 나누어지는 수, 3은 나누는 수예요.","= 뒤의 9가 몫이에요."],"variant_rule":{"alt":[{"stem":"15 ÷ 5 = 3에서 몫은 어느 것인가요?","options":[{"t":"3","correct":true},{"t":"15","mis":"M3-1-u3-X06"},{"t":"5","mis":"M3-1-u3-X06"},{"t":"15와 5","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","15는 나누어지는 수, 5는 나누는 수예요.","= 뒤의 3이 몫이에요."],"asset":null},{"stem":"21 ÷ 7 = 3에서 몫은 어느 것인가요?","options":[{"t":"3","correct":true},{"t":"21","mis":"M3-1-u3-X06"},{"t":"7","mis":"M3-1-u3-X06"},{"t":"21과 7","mis":"M3-1-u3-X06"}],"explanation":["나눗셈식은 나누어지는 수 ÷ 나누는 수 = 몫이에요.","21은 나누어지는 수, 7은 나누는 수예요.","= 뒤의 3이 몫이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#8','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C6',1,'sa','auto','곱셈구구를 이용해 18 ÷ 2의 몫을 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M3-1-u3-C6","difficulty":1,"kind":"sa","stem":"곱셈구구를 이용해 18 ÷ 2의 몫을 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["2 × □ = 18이 되는 □를 찾아요.","2단: … 2 × 9 = 18.","그래서 18 ÷ 2 = 9예요."],"variant_rule":{"alt":[{"stem":"곱셈구구를 이용해 45 ÷ 9의 몫을 구하세요. 숫자로 쓰세요.","answer":["5"],"explanation":["9 × □ = 45가 되는 □를 찾아요.","9단: … 9 × 5 = 45.","그래서 45 ÷ 9 = 5예요."],"asset":null},{"stem":"곱셈구구를 이용해 6 ÷ 3의 몫을 구하세요. 숫자로 쓰세요.","answer":["2"],"explanation":["3 × □ = 6이 되는 □를 찾아요.","3단: … 3 × 2 = 6.","그래서 6 ÷ 3 = 2예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#9','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C1',2,'ox','auto','지우개 42개를 6명에게 차례로 7·6·7·8·7·7개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.',ARRAY['M3-1-u3-X01']::text[],true,'{"seq":9,"concept":"M3-1-u3-C1","difficulty":2,"kind":"ox","stem":"지우개 42개를 6명에게 차례로 7·6·7·8·7·7개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"mis":"M3-1-u3-X01","explanation":["모두 더하면 42개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 7·6·7·8·7·7개로 달라요.","똑같이 나누려면 6명 모두 7개씩 받아야 해요."],"variant_rule":{"alt":[{"stem":"클립 18개를 6명에게 차례로 3·3·3·3·2·4개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 18개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 3·3·3·3·2·4개로 달라요.","똑같이 나누려면 6명 모두 3개씩 받아야 해요."],"asset":null},{"stem":"귤 16개를 8명에게 차례로 2·3·2·1·2·2·2·2개를 나누어 주었어요. 남김없이 다 주었으니 똑같이 나눈 거예요.","answer":"X","reason_options":[{"t":"받은 개수가 서로 달라서","correct":true},{"t":"모두 나누어 주었으니 똑같이 나눈 것이어서","mis":"M3-1-u3-X01"}],"explanation":["모두 더하면 16개 — 다 나누어 준 것은 맞아요.","하지만 받은 개수가 2·3·2·1·2·2·2·2개로 달라요.","똑같이 나누려면 8명 모두 2개씩 받아야 해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#10','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C2',2,'mc','auto','색종이 36장을 친구 4명에게 똑같이 나누어 주면 한 명에게 몇 장씩인가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":10,"concept":"M3-1-u3-C2","difficulty":2,"kind":"mc","stem":"색종이 36장을 친구 4명에게 똑같이 나누어 주면 한 명에게 몇 장씩인가요?","options":[{"t":"9장","correct":true},{"t":"4장","mis":"M3-1-u3-X02"},{"t":"32장","mis":"M3-1-u3-X07"},{"t":"10장","mis":"M3-1-u3-X11"}],"explanation":["36장을 친구 4명에게 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","4묶음으로 똑같이 나누니 4 × □ = 36에서 □ = 9예요.","한 명에게 9장이에요."],"variant_rule":{"alt":[{"stem":"구슬 18개를 접시 6개에 똑같이 나누어 담으면 한 접시에 몇 개씩인가요?","options":[{"t":"3개","correct":true},{"t":"6개","mis":"M3-1-u3-X02"},{"t":"12개","mis":"M3-1-u3-X07"},{"t":"4개","mis":"M3-1-u3-X11"}],"explanation":["18개를 접시 6개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","6묶음으로 똑같이 나누니 6 × □ = 18에서 □ = 3이에요.","한 접시에 3개예요."],"asset":null},{"stem":"카드 21장을 모둠 7개에 똑같이 나누어 주면 한 모둠에 몇 장씩인가요?","options":[{"t":"3장","correct":true},{"t":"7장","mis":"M3-1-u3-X02"},{"t":"14장","mis":"M3-1-u3-X07"},{"t":"4장","mis":"M3-1-u3-X11"}],"explanation":["21장을 모둠 7개에 하나씩 번갈아 놓으면 똑같이 나눌 수 있어요.","7묶음으로 똑같이 나누니 7 × □ = 21에서 □ = 3이에요.","한 모둠에 3장이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#11','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C3',2,'mc','auto','지우개 12개를 한 봉지에 6개씩 담으면 몇 봉지가 되나요?',ARRAY['M3-1-u3-X02','M3-1-u3-X11']::text[],true,'{"seq":11,"concept":"M3-1-u3-C3","difficulty":2,"kind":"mc","stem":"지우개 12개를 한 봉지에 6개씩 담으면 몇 봉지가 되나요?","options":[{"t":"2봉지","correct":true},{"t":"6봉지","mis":"M3-1-u3-X02"},{"t":"3봉지","mis":"M3-1-u3-X11"},{"t":"1봉지","mis":"M3-1-u3-X11"}],"explanation":["12개에서 6개씩 덜어 내요.","6 × □ = 12에서 □ = 2 — 2번 덜어 낼 수 있어요.","그래서 2봉지예요."],"variant_rule":{"alt":[{"stem":"클립 6개를 한 상자에 3개씩 담으면 몇 상자가 되나요?","options":[{"t":"2상자","correct":true},{"t":"3상자","mis":"M3-1-u3-X02"},{"t":"1상자","mis":"M3-1-u3-X11"},{"t":"6상자","mis":"M3-1-u3-X06"}],"explanation":["6개에서 3개씩 덜어 내요.","3 × □ = 6에서 □ = 2 — 2번 덜어 낼 수 있어요.","그래서 2상자예요."],"asset":null},{"stem":"귤 21개를 한 접시에 7개씩 담으면 몇 접시가 되나요?","options":[{"t":"3접시","correct":true},{"t":"7접시","mis":"M3-1-u3-X02"},{"t":"14접시","mis":"M3-1-u3-X07"},{"t":"4접시","mis":"M3-1-u3-X11"}],"explanation":["21개에서 7개씩 덜어 내요.","7 × □ = 21에서 □ = 3 — 3번 덜어 낼 수 있어요.","그래서 3접시예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#12','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C4',2,'mc','auto','색종이 18장을 한 바구니에 9장씩 담으려고 해요. 몇 바구니가 되는지 구하는 식은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X03','M3-1-u3-X13']::text[],true,'{"seq":12,"concept":"M3-1-u3-C4","difficulty":2,"kind":"mc","stem":"색종이 18장을 한 바구니에 9장씩 담으려고 해요. 몇 바구니가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"18 ÷ 9","correct":true},{"t":"9 ÷ 18","mis":"M3-1-u3-X05"},{"t":"18 ÷ 2","mis":"M3-1-u3-X03"},{"t":"18 − 9","mis":"M3-1-u3-X13"}],"explanation":["18장에서 9장씩 덜어 내는 상황이에요.","전체 18을 앞에, 한 바구니 개수 9를 뒤에 — 18 ÷ 9.","18 ÷ 9 = 2 — 2바구니예요."],"variant_rule":{"alt":[{"stem":"구슬 27개를 한 컵에 3개씩 담으려고 해요. 몇 컵이 되는지 구하는 식은 어느 것인가요?","options":[{"t":"27 ÷ 3","correct":true},{"t":"3 ÷ 27","mis":"M3-1-u3-X05"},{"t":"27 ÷ 9","mis":"M3-1-u3-X03"},{"t":"27 − 3","mis":"M3-1-u3-X13"}],"explanation":["27개에서 3개씩 덜어 내는 상황이에요.","전체 27을 앞에, 한 컵 개수 3을 뒤에 — 27 ÷ 3.","27 ÷ 3 = 9 — 9컵이에요."],"asset":null},{"stem":"카드 6장을 한 주머니에 2장씩 담으려고 해요. 몇 주머니가 되는지 구하는 식은 어느 것인가요?","options":[{"t":"6 ÷ 2","correct":true},{"t":"2 ÷ 6","mis":"M3-1-u3-X05"},{"t":"6 ÷ 3","mis":"M3-1-u3-X03"},{"t":"6 − 2","mis":"M3-1-u3-X13"}],"explanation":["6장에서 2장씩 덜어 내는 상황이에요.","전체 6을 앞에, 한 주머니 개수 2를 뒤에 — 6 ÷ 2.","6 ÷ 2 = 3 — 3주머니예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#13','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C5',2,'mc','auto','8 × 4 = 32를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?',ARRAY['M3-1-u3-X05','M3-1-u3-X08']::text[],true,'{"seq":13,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"8 × 4 = 32를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"32 ÷ 8 = 4","correct":true},{"t":"8 ÷ 32 = 4","mis":"M3-1-u3-X05"},{"t":"32 ÷ 8 = 24","mis":"M3-1-u3-X08"},{"t":"32 ÷ 9 = 4","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 8 × 4 = 32에서 곱 32가 나누어지는 수가 돼요.","32를 8로 나누면 4 — 32 ÷ 8 = 4.","같은 세 수 8, 4, 32만 써요."],"variant_rule":{"alt":[{"stem":"8 × 9 = 72를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"72 ÷ 8 = 9","correct":true},{"t":"8 ÷ 72 = 9","mis":"M3-1-u3-X05"},{"t":"72 ÷ 8 = 64","mis":"M3-1-u3-X08"},{"t":"72 ÷ 9 = 9","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 8 × 9 = 72에서 곱 72가 나누어지는 수가 돼요.","72를 8로 나누면 9 — 72 ÷ 8 = 9.","같은 세 수 8, 9, 72만 써요."],"asset":null},{"stem":"6 × 2 = 12를 나눗셈식으로 바르게 바꾼 것은 어느 것인가요?","options":[{"t":"12 ÷ 6 = 2","correct":true},{"t":"6 ÷ 12 = 2","mis":"M3-1-u3-X05"},{"t":"12 ÷ 6 = 6","mis":"M3-1-u3-X08"},{"t":"12 ÷ 7 = 2","mis":"M3-1-u3-X08"}],"explanation":["곱셈식 6 × 2 = 12에서 곱 12가 나누어지는 수가 돼요.","12를 6으로 나누면 2 — 12 ÷ 6 = 2.","같은 세 수 6, 2, 12만 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#14','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C5',2,'mc','auto','도넛을 한 줄에 5개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?',ARRAY['M3-1-u3-X09','M3-1-u3-X11','M3-1-u3-X13']::text[],true,'{"seq":14,"concept":"M3-1-u3-C5","difficulty":2,"kind":"mc","stem":"도넛을 한 줄에 5개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"5 × 8 = 40","correct":true},{"t":"5 × 9 = 45","mis":"M3-1-u3-X09"},{"t":"5 × 8 = 45","mis":"M3-1-u3-X11"},{"t":"5 + 8 = 13","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 5개씩, 줄은 8줄이에요.","5씩 8줄이니 5 × 8.","5 × 8 = 40 — 모두 40개."],"asset":{"type":"mul_groups","item":"🍩","k":5,"n":8,"look":"rows"},"variant_rule":{"alt":[{"stem":"사과를 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 5 = 10","correct":true},{"t":"2 × 6 = 12","mis":"M3-1-u3-X09"},{"t":"2 × 5 = 12","mis":"M3-1-u3-X11"},{"t":"2 + 5 = 7","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2개씩, 줄은 5줄이에요.","2씩 5줄이니 2 × 5.","2 × 5 = 10 — 모두 10개."],"asset":{"type":"mul_groups","item":"🍎","k":2,"n":5,"look":"rows"}},{"stem":"당근을 한 줄에 2개씩 늘어놓았어요. 그림을 나타낸 곱셈식은 어느 것인가요?","options":[{"t":"2 × 6 = 12","correct":true},{"t":"2 × 7 = 14","mis":"M3-1-u3-X09"},{"t":"2 × 6 = 14","mis":"M3-1-u3-X11"},{"t":"2 + 6 = 8","mis":"M3-1-u3-X13"}],"explanation":["한 줄에 2개씩, 줄은 6줄이에요.","2씩 6줄이니 2 × 6.","2 × 6 = 12 — 모두 12개."],"asset":{"type":"mul_groups","item":"🥕","k":2,"n":6,"look":"rows"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#15','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C6',2,'mc','auto','8 ÷ 4 = 2가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?',ARRAY['M3-1-u3-X12','M3-1-u3-X13']::text[],true,'{"seq":15,"concept":"M3-1-u3-C6","difficulty":2,"kind":"mc","stem":"8 ÷ 4 = 2가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"4 × 2 = 8","correct":true},{"t":"2 × 8 = □","mis":"M3-1-u3-X12"},{"t":"8 × 4 = □","mis":"M3-1-u3-X12"},{"t":"4 + 2 = 6","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","4 × 2 = 8이에요.","그래서 8 ÷ 4 = 2는 맞아요."],"variant_rule":{"alt":[{"stem":"45 ÷ 5 = 9가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"5 × 9 = 45","correct":true},{"t":"9 × 45 = □","mis":"M3-1-u3-X12"},{"t":"45 × 5 = □","mis":"M3-1-u3-X12"},{"t":"5 + 9 = 14","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","5 × 9 = 45예요.","그래서 45 ÷ 5 = 9는 맞아요."],"asset":null},{"stem":"20 ÷ 4 = 5가 맞는지 곱셈으로 확인하려고 해요. 알맞은 식은 어느 것인가요?","options":[{"t":"4 × 5 = 20","correct":true},{"t":"5 × 20 = □","mis":"M3-1-u3-X12"},{"t":"20 × 4 = □","mis":"M3-1-u3-X12"},{"t":"4 + 5 = 9","mis":"M3-1-u3-X13"}],"explanation":["나누는 수 × 몫 = 나누어지는 수가 되면 맞아요.","4 × 5 = 20이에요.","그래서 20 ÷ 4 = 5는 맞아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#16','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C7',2,'mc','auto','쿠키 12개를 한 컵에 3개씩 담아 나눔 장터에 내놓으려고 해요. 몇 컵이 필요한가요?',ARRAY['M3-1-u3-X02','M3-1-u3-X07','M3-1-u3-X11']::text[],true,'{"seq":16,"concept":"M3-1-u3-C7","difficulty":2,"kind":"mc","stem":"쿠키 12개를 한 컵에 3개씩 담아 나눔 장터에 내놓으려고 해요. 몇 컵이 필요한가요?","options":[{"t":"4컵","correct":true},{"t":"3컵","mis":"M3-1-u3-X02"},{"t":"9컵","mis":"M3-1-u3-X07"},{"t":"5컵","mis":"M3-1-u3-X11"}],"explanation":["한 컵에 3개씩 — 몇 번 담을 수 있는지 구해요.","12 ÷ 3 = 4 (3 × 4 = 12).","4컵이 필요해요."],"variant_rule":{"alt":[{"stem":"딸기 40개를 한 주머니에 8개씩 담아 나눔 장터에 내놓으려고 해요. 몇 주머니가 필요한가요?","options":[{"t":"5주머니","correct":true},{"t":"8주머니","mis":"M3-1-u3-X02"},{"t":"32주머니","mis":"M3-1-u3-X07"},{"t":"6주머니","mis":"M3-1-u3-X11"}],"explanation":["한 주머니에 8개씩 — 몇 번 담을 수 있는지 구해요.","40 ÷ 8 = 5 (8 × 5 = 40).","5주머니가 필요해요."],"asset":null},{"stem":"풍선 20개를 한 봉지에 5개씩 담아 나눔 장터에 내놓으려고 해요. 몇 봉지가 필요한가요?","options":[{"t":"4봉지","correct":true},{"t":"5봉지","mis":"M3-1-u3-X02"},{"t":"15봉지","mis":"M3-1-u3-X07"},{"t":"3봉지","mis":"M3-1-u3-X11"}],"explanation":["한 봉지에 5개씩 — 몇 번 담을 수 있는지 구해요.","20 ÷ 5 = 4 (5 × 4 = 20).","4봉지가 필요해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#17','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C3',3,'sa','auto','8에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M3-1-u3-C3","difficulty":3,"kind":"sa","stem":"8에서 4씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 4씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["2"],"explanation":["화살표 하나가 4씩 한 번 덜어 낸 거예요.","화살표를 세면 2개 — ?는 0이에요.","8은 4씩 2번 덜어 내면 0 — 2묶음이에요."],"asset":{"type":"jump_row","cells":[8,4,null],"step":4,"dir":"down"},"variant_rule":{"alt":[{"stem":"20에서 5씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 5씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 5씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","20은 5씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[20,15,10,5,null],"step":5,"dir":"down"}},{"stem":"8에서 2씩 거꾸로 뛰어 세었더니 ?에서 0이 되었어요. 2씩 몇 번 뛰었나요? 숫자로 쓰세요.","answer":["4"],"explanation":["화살표 하나가 2씩 한 번 덜어 낸 거예요.","화살표를 세면 4개 — ?는 0이에요.","8은 2씩 4번 덜어 내면 0 — 4묶음이에요."],"asset":{"type":"jump_row","cells":[8,6,4,2,null],"step":2,"dir":"down"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#18','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C4',3,'ox','auto','6 ÷ 2와 2 ÷ 6은 같은 식이에요.',ARRAY['M3-1-u3-X05']::text[],true,'{"seq":18,"concept":"M3-1-u3-C4","difficulty":3,"kind":"ox","stem":"6 ÷ 2와 2 ÷ 6은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"mis":"M3-1-u3-X05","explanation":["6 ÷ 2는 「6을 2로 나누기」예요.","2 ÷ 6은 작은 2를 큰 6으로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"variant_rule":{"alt":[{"stem":"10 ÷ 2와 2 ÷ 10은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["10 ÷ 2는 「10을 2로 나누기」예요.","2 ÷ 10은 작은 2를 큰 10으로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null},{"stem":"48 ÷ 6과 6 ÷ 48은 같은 식이에요.","answer":"X","reason_options":[{"t":"나눗셈은 앞뒤를 바꾸면 뜻이 달라져서","correct":true},{"t":"덧셈·곱셈처럼 순서를 바꿔도 같아서","mis":"M3-1-u3-X05"}],"explanation":["48 ÷ 6은 「48을 6으로 나누기」예요.","6 ÷ 48은 작은 6을 큰 48로 나누는 것이라 전혀 달라요.","나눗셈식은 앞에 나누어지는 수(전체)를 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#19','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C5',3,'mc','auto','5 × 2 = 10과 한 가족인 식이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":19,"concept":"M3-1-u3-C5","difficulty":3,"kind":"mc","stem":"5 × 2 = 10과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"15 ÷ 5 = 3","correct":true},{"t":"2 × 5 = 10","mis":"M3-1-u3-X15"},{"t":"10 ÷ 5 = 2","mis":"M3-1-u3-X15"},{"t":"10 ÷ 2 = 5","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 5, 2, 10으로 만든 식이에요.","곱셈 2개(5 × 2, 2 × 5), 나눗셈 2개(10 ÷ 5, 10 ÷ 2).","15 ÷ 5 = 3은 다른 수가 들어 있어 한 가족이 아니에요."],"variant_rule":{"alt":[{"stem":"2 × 8 = 16과 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"16 ÷ 4 = 4","correct":true},{"t":"8 × 2 = 16","mis":"M3-1-u3-X15"},{"t":"16 ÷ 2 = 8","mis":"M3-1-u3-X15"},{"t":"16 ÷ 8 = 2","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 2, 8, 16으로 만든 식이에요.","곱셈 2개(2 × 8, 8 × 2), 나눗셈 2개(16 ÷ 2, 16 ÷ 8).","16 ÷ 4 = 4는 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null},{"stem":"7 × 5 = 35와 한 가족인 식이 아닌 것은 어느 것인가요?","options":[{"t":"42 ÷ 7 = 6","correct":true},{"t":"5 × 7 = 35","mis":"M3-1-u3-X15"},{"t":"35 ÷ 7 = 5","mis":"M3-1-u3-X15"},{"t":"35 ÷ 5 = 7","mis":"M3-1-u3-X15"}],"explanation":["식 가족은 같은 세 수 7, 5, 35로 만든 식이에요.","곱셈 2개(7 × 5, 5 × 7), 나눗셈 2개(35 ÷ 7, 35 ÷ 5).","42 ÷ 7 = 6은 다른 수가 들어 있어 한 가족이 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#20','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C6',3,'sa','auto','□ ÷ 4 = 8 — □에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":20,"concept":"M3-1-u3-C6","difficulty":3,"kind":"sa","stem":"□ ÷ 4 = 8 — □에 알맞은 수를 쓰세요.","answer":["32"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 8 = 32예요.","□ = 32 — 32 ÷ 4 = 8로 확인해요."],"variant_rule":{"alt":[{"stem":"□ ÷ 5 = 3 — □에 알맞은 수를 쓰세요.","answer":["15"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","5 × 3 = 15예요.","□ = 15 — 15 ÷ 5 = 3으로 확인해요."],"asset":null},{"stem":"□ ÷ 4 = 3 — □에 알맞은 수를 쓰세요.","answer":["12"],"explanation":["나누는 수 × 몫 = 나누어지는 수예요.","4 × 3 = 12예요.","□ = 12 — 12 ÷ 4 = 3으로 확인해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#21','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C7',3,'mc','auto','나눔 장터에서 구슬 28개를 7명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.',ARRAY['M3-1-u3-X03','M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":21,"concept":"M3-1-u3-C7","difficulty":3,"kind":"mc","stem":"나눔 장터에서 구슬 28개를 7명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"28 ÷ 7 = 4, 4개씩","correct":true},{"t":"28 ÷ 4 = 7, 7개씩","mis":"M3-1-u3-X03"},{"t":"28 − 7 = 21, 21개씩","mis":"M3-1-u3-X13"},{"t":"28 ÷ 7 = 5, 5개씩","mis":"M3-1-u3-X11"}],"explanation":["7명에게 똑같이 나누니 나누는 수는 사람 수 7이에요.","28 ÷ 7 — 7 × 4 = 28.","한 명이 4개씩 받아요."],"variant_rule":{"alt":[{"stem":"나눔 장터에서 카드 30장을 6명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"30 ÷ 6 = 5, 5장씩","correct":true},{"t":"30 ÷ 5 = 6, 6장씩","mis":"M3-1-u3-X03"},{"t":"30 − 6 = 24, 24장씩","mis":"M3-1-u3-X13"},{"t":"30 ÷ 6 = 6, 6장씩","mis":"M3-1-u3-X11"}],"explanation":["6명에게 똑같이 나누니 나누는 수는 사람 수 6이에요.","30 ÷ 6 — 6 × 5 = 30.","한 명이 5장씩 받아요."],"asset":null},{"stem":"나눔 장터에서 지우개 54개를 6명에게 똑같이 나누어 주려고 해요. 알맞은 식과 답을 고르세요.","options":[{"t":"54 ÷ 6 = 9, 9개씩","correct":true},{"t":"54 ÷ 9 = 6, 6개씩","mis":"M3-1-u3-X03"},{"t":"54 − 6 = 48, 48개씩","mis":"M3-1-u3-X13"},{"t":"54 ÷ 6 = 10, 10개씩","mis":"M3-1-u3-X11"}],"explanation":["6명에게 똑같이 나누니 나누는 수는 사람 수 6이에요.","54 ÷ 6 — 6 × 9 = 54.","한 명이 9개씩 받아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#22','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C8',3,'mc','auto','사탕 36개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?',ARRAY['M3-1-u3-X15']::text[],true,'{"seq":22,"concept":"M3-1-u3-C8","difficulty":3,"kind":"mc","stem":"사탕 36개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"8명에게 똑같이","correct":true},{"t":"4명에게 9개씩","mis":"M3-1-u3-X15"},{"t":"9명에게 4개씩","mis":"M3-1-u3-X15"},{"t":"6명에게 6개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 36이 있으면 남김없이 나눌 수 있어요.","4명에게 9개씩, 9명에게 4개씩, 6명에게 6개씩 — 모두 곱셈구구로 36이 돼요.","8단에는 36이 없어서 8명에게는 남김없이 똑같이 나눌 수 없어요."],"variant_rule":{"alt":[{"stem":"사탕 24개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"7명에게 똑같이","correct":true},{"t":"4명에게 6개씩","mis":"M3-1-u3-X15"},{"t":"3명에게 8개씩","mis":"M3-1-u3-X15"},{"t":"8명에게 3개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 24가 있으면 남김없이 나눌 수 있어요.","4명에게 6개씩, 3명에게 8개씩, 8명에게 3개씩 — 모두 곱셈구구로 24가 돼요.","7단에는 24가 없어서 7명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null},{"stem":"사탕 12개를 남김없이 똑같이 나누는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"9명에게 똑같이","correct":true},{"t":"6명에게 2개씩","mis":"M3-1-u3-X15"},{"t":"2명에게 6개씩","mis":"M3-1-u3-X15"},{"t":"4명에게 3개씩","mis":"M3-1-u3-X15"}],"explanation":["나누는 수의 단에 12가 있으면 남김없이 나눌 수 있어요.","6명에게 2개씩, 2명에게 6개씩, 4명에게 3개씩 — 모두 곱셈구구로 12가 돼요.","9단에는 12가 없어서 9명에게는 남김없이 똑같이 나눌 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#23','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C6',4,'mc','auto','몫이 가장 큰 것은 어느 것인가요?',ARRAY['M3-1-u3-X13','M3-1-u3-X11']::text[],true,'{"seq":23,"concept":"M3-1-u3-C6","difficulty":4,"kind":"mc","stem":"몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"63 ÷ 7","correct":true},{"t":"64 ÷ 8","mis":"M3-1-u3-X13"},{"t":"20 ÷ 5","mis":"M3-1-u3-X11"},{"t":"24 ÷ 8","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","64 ÷ 8 = 8, 20 ÷ 5 = 4, 24 ÷ 8 = 3, 63 ÷ 7 = 9.","몫이 가장 큰 것은 63 ÷ 7 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"63 ÷ 7","correct":true},{"t":"72 ÷ 9","mis":"M3-1-u3-X13"},{"t":"21 ÷ 3","mis":"M3-1-u3-X11"},{"t":"28 ÷ 7","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","72 ÷ 9 = 8, 21 ÷ 3 = 7, 28 ÷ 7 = 4, 63 ÷ 7 = 9.","몫이 가장 큰 것은 63 ÷ 7 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null},{"stem":"이번에는 다른 수예요. 몫이 가장 큰 것은 어느 것인가요?","options":[{"t":"42 ÷ 6","correct":true},{"t":"48 ÷ 8","mis":"M3-1-u3-X13"},{"t":"15 ÷ 3","mis":"M3-1-u3-X11"},{"t":"27 ÷ 9","mis":"M3-1-u3-X11"}],"explanation":["하나씩 몫을 구해요.","48 ÷ 8 = 6, 15 ÷ 3 = 5, 27 ÷ 9 = 3, 42 ÷ 6 = 7.","몫이 가장 큰 것은 42 ÷ 6 — 나누어지는 수가 크다고 몫이 큰 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#24','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C7',4,'sa','auto','색종이 27장을 3명에게 똑같이 나누어 주었어요. 한 명이 받은 색종이를 다시 3장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M3-1-u3-C7","difficulty":4,"kind":"sa","stem":"색종이 27장을 3명에게 똑같이 나누어 주었어요. 한 명이 받은 색종이를 다시 3장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 27 ÷ 3 = 9.","그다음 9를 3장씩 담아요: 9 ÷ 3 = 3.","그래서 3봉지예요."],"variant_rule":{"alt":[{"stem":"지우개 30개를 5명에게 똑같이 나누어 주었어요. 한 명이 받은 지우개를 다시 2개씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["3"],"explanation":["먼저 한 명이 받은 수: 30 ÷ 5 = 6.","그다음 6을 2개씩 담아요: 6 ÷ 2 = 3.","그래서 3봉지예요."],"asset":null},{"stem":"카드 12장을 2명에게 똑같이 나누어 주었어요. 한 명이 받은 카드를 다시 3장씩 봉지에 담으면 몇 봉지가 되나요? 숫자로 쓰세요.","answer":["2"],"explanation":["먼저 한 명이 받은 수: 12 ÷ 2 = 6.","그다음 6을 3장씩 담아요: 6 ÷ 3 = 2.","그래서 2봉지예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_math_u3_review_d#25','math',3,1,'u3','','g3_1_math_u3_review_d','unit_review','M3-1-u3-C6',4,'essay','teacher','하랑이는 42 ÷ 6 = 8이라고 했어요. 곱셈으로 확인해 맞는지 판단하고 바른 몫을 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M3-1-u3-C6","difficulty":4,"kind":"essay","stem":"하랑이는 42 ÷ 6 = 8이라고 했어요. 곱셈으로 확인해 맞는지 판단하고 바른 몫을 구해 보세요.","answer_guide":{"answer":"예: 6 × 8 = 48로 42가 아니므로 틀렸다. 6단에서 6 × 7 = 42이므로 바른 몫은 7이다.","scoring_points":["6 × 8 = 48로 확인했는가","틀렸다고 판단했는가","바른 몫 7을 구했는가"]},"explanation":["6 × 8 = 48 ≠ 42.","6 × 7 = 42.","바른 몫은 7이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
